(window.GIM_TS=window.GIM_TS||{})["Kiddushin.2"]={"from":48,"a":[["\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יכול הקונה להגביה את הפיל \u0003ב\u0004אמצעות \u0003חבילי\u0004 (חבילות) \u0003זמורות,\u0004 שהוא מוליך ומעלה את הפיל על גביהן ונחשב הדבר כהגבהת הפיל.","\u0003נכסים שיש להם אחריות,\u0004 כלומר, קרקעות, ושאר נכסים הקבועים בקרקע \u0003נקנין בכסף ו\u0004כן \u0003בשטר ו\u0004כן \u0003בחזקה.\u0004 נכסים \u0003שאין להם אחריות,\u0004 כלומר, מטלטלין — \u0003אין נקנין אלא במשיכה.\u0004 ועוד, \u0003נכסים שאין להם אחריות נקנין עם נכסים שיש להם אחריות בכסף ובשטר ובחזקה,\u0004 כלומר, המטלטלין עוברים לרשות הקונה כאשר נקנו יחד עם קרקעות, ועשה קנין בקרקעות, בבת אחת.","ובמקרה של טענות לגבי קרקעות ומטלטלין יחד, אם הודה הנתבע במקצת הטענה לגבי המטלטלין והתחייב בכך שבועה, הריהם המטלטלין \u0003זוקקין את הנכסים שיש להם אחריות לישבע\u0004 גם \u0003עליהן,\u0004 אף שאין נשבעים על טענה בענייני קרקעות.","ומבררים: דין זה שקרקעות נקנות \u0003בכסף מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"שדות בכסף יקנו\"\u0004 (ירמיה לב, מד). ושואלים: אם משם הראיה — \u0003ואימא עד דאיכא\u0004 \u0005[ואמור עד שיש]\u0006 גם \u0003שטר, דכתיב\u0004 \u0005[שנאמר]\u0006 בהמשך הפסוק \u0003\"וכתוב בספר\u0004 (שטר) \u0003וחתום\"\u0004 (שם)! ומשיבים: \u0003אי כתיב\u0004 \u0005[אילו\u0006 היה \u0005נאמר]\u0006 \u0003\"\u0004בכסף \u0003יקנו\" לבסוף\u0004 — הייתי אומר \u0003כדקאמרת\u0004 \u0005[כמו שא\u0006 \u0005תה אומר]\u0006 שצריך לעשות שטר, ואחר כך בכסף יקנו, אבל \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"יקנו\" מעיקרא\u0004 \u0005[מתחילה],\u0006 משמע כי \u0003כסף\u0004 עצמו \u0003קני\u0004 \u0005[קונה]\u0006 ואילו ה\u0003שטר\u0004 — \u0003ראיה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא.\u0004","\u0003אמר רב: לא שנו\u0004 שקרקע נקנית בכסף בלבד \u0003אלא במקום שאין כותבין את השטר, אבל במקום שכותבין את השטר\u0004 — \u0003לא קנה\u0004 עד זמן נתינת השטר ללוקח. \u0003ואי פריש\u0004 \u0005[ואם פירש]\u0006 שרצונו לקנות את הקרקע משעת מתן הכסף — הרי \u0003פריש\u0004 \u0005[פירש],\u0006 ונקנתה הקרקע עם מתן הכסף.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב אידי בר אבין כי זבין ארעא, אמר\u0004 \u0005[כאשר היה קונה קרקע, היה אומר]:\u0006 \u0003אי בעינא בכספא\u0004 \u0005[אם אני רוצה\u0006 לקנות \u0005בכסף]\u0006 — \u0003איקני\u0004 \u0005[אקנה],\u0006 \u0003אי בעינא בשטרא\u0004 \u0005[אם אני רוצה\u0006 לקנות \u0005בשטר]\u0006 — \u0003איקני\u0004 \u0005[אקנה],\u0006 שמראש התנה שתהיה האפשרות בידו להחליט במה ייגמר הקנין. ומסבירים את טעמו: \u0003אי בעינא בכספא\u0004 \u0005[אם אני רוצה\u0006 לקנות \u0005בכסף]\u0006 — \u0003איקני\u0004 \u0005[אקנה]\u0006 — \u0003דאי בעיתו למיהדר, לא מציתו הדריתו\u0004 \u0005[שאם תרצו\u0006 בכם, \u0005אינכם יכולים לחזור],\u0006 שהרי כבר עבר הכסף מיד ליד, \u0003ואי בעינא בשטרא\u0004 \u0005[אם אני רוצה\u0006 לקנות \u0005בשטר]\u0006 — \u0003איקני\u0004 \u0005[אקנה]\u0006 — \u0003דאי בעינא למיהדר הדרנא\u0004 \u0005[שאם ארצה לחזור]\u0006 בי מן העיסקה \u0005[אחזור]\u0006 \u0003בי\u0004 כל עוד לא קיבלתי את השטר.","שנינו במשנה שקרקעות נקנים \u0003בשטר.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וכתוב בספר וחתום והעד עדים\"\u0004 (שם), \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 מקודם ששטר זה \u0003שטר ראיה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא! אלא מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים, שנאמר \u0003\"ואקח את ספר המקנה\"\u0004 (שם יא) ומלשון זו למדים שהספר = השטר הוא עצמו עושה קנין. \u0003אמר שמואל: לא שנו\u0004 דבר זה שהשטר עצמו קונה \u0003אלא בשטר מתנה, אבל במכר לא קנה עד שיתן לו דמים,\u0004 והשטר עצמו אינו עושה קנין.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב המנונא\u0004 ממה ששנינו בברייתא: דרך הקנין \u0003בשטר כיצד? כתב לו על הנייר או על החרס, אף על פי שאין בהם\u0004 בנייר ובחרס \u0003שוה פרוטה,\u0004 בנוסח \u0003\"שדי מכורה לך\"\u0004 או \u0003\"שדי נתונה לך\u0004 במתנה \u0003\"\u0004— \u0003הרי זו מכורה ונתונה.\u0004 משמע שהשטר בלבד גומר את הקנין בין במכר ובין במתנה! \u0003הוא מותיב לה והוא מפרק לה\u0004 \u0005[הוא היה מקשה\u0006 את הק ושיה \u0005הזו והוא היה מתרץ אותה],\u0006 שכאן מדובר \u0003במוכר שדהו מפני רעתה.\u0004 כלומר, שהמוכר עצמו מעונין להפטר משדה זה מפני שערכו יורד, והוא מעונין לגמור את העברת השדה מהר ככל האפשר, ובמקרה זה כתיבת השטר בלבד גומרת את הקנין.","\u0003רב אשי אמר:\u0004 אפשר לפרש שכל הברייתא הזו מדברת רק בענין אחד, לא במכר ממש אלא \u0003במתנה ביקש ליתנה לו, ולמה כתב לו לשון מכר\u0004 בשטר המתנה — \u0003כדי ליפות את כוחו,\u0004 שאם יתברר ששדה זה משועבד למלווים יוכל לגבות את דמיו של השדה מנכסים אחרים של המוכר = הנותן, שהרי נתן לו כוח של קנין מכר. וכיון שעיקרו של שטר הוא מתנה, השטר עצמו גומר את הקנין.","שנינו במשנה שהקרקעות נקנים \u0003בחזקה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? \u0003אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושבו בעריכם אשר תפשתם\"\u0004 (שם מ, י), \u0003במה תפשתם\u0004 את הערים — \u0003בישיבה,\u0004 משמע שעצם הישיבה במקום, שהיא חזקה — היא עצמה עושה קנין. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 ראיה אחרת: נאמר \u0003\"וירשתם אתה וישבתם בה\"\u0004 (דברים יא, לא) וכך יש להבין: \u0003במה ירשתם\u0004 — \u0003בישיבה,\u0004 משמע שקרקעות נקנים בחזקה.","שנינו במשנה שנכסים \u0003שאין להם אחריות אין נקנין אלא במשיכה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך\"\u0004 (ויקרא כה, יד) לשון זו מורה שמדובר ב\u0003דבר הנקנה מיד ליד,\u0004 כלומר, במשיכה.","ושואלים: \u0003ול\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר דבר תורה מעות קונות\u0004 ולא המשיכה, אלא שתקנת חכמים היא שייקנו במשיכה, \u0003מאי איכא למימר\u0004 \u0005[מה\u0006 אם כן \u0005יש לומר]?\u0006 שהרי לדעתו גם נכסים שאין להם אחריות נקנים בכסף! ומשיבים: ר' יוחנן יכול לומר כי \u0003תנא תקנתא דרבנן קתני\u0004 \u0005[התנא שנה תקנת חכמים]\u0006 שכך עושים הלכה למעשה, ולא הזכיר עיקר דין תורה.","שנינו עוד במשנה ש\u0003נכסים שאין להם אחריות\u0004 (מטלטלין) נקנים עם נכסים שיש להם אחריות (קרקעות). ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר חזקיה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויתן להם אביהם מתנות\u0004 רבות לכסף ולזהב ולמגדנות \u0003עם ערי מצרות ביהודה\"\u0004 (דברי הימים ב כא, ג), שאת המתנות המטלטלין נתן עם הערים, ולא היה צריך למסור בידם, אלא נתן אותן אגב הקרקעות שנתן להם.","לענין זה של קנין מטלטלין אגב הקרקעות \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: האם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו המטלטלין הללו \u0003צבורים\u0004 בתוך הקרקע הנקנית, \u0003או לא? אמר רב יוסף תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003ר' עקיבא אומר: קרקע כל שהוא חייבת בפאה, ובבכורים\u0004"],["\u0003ו\u0004יכול \u0003לכתוב עליה\u0004 המלוה \u0003פרוסבול\u0004 שלא תשמט השנה השביעית את חובותיו, \u0003ולקנות עמה נכסים שאין להם אחריות. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו המטלטלין \u0003צבורים\u0004 בה, אם כן קרקע \u0003כל שהוא למאי חזי\u0004 \u0005[למה\u0006 היא \u0005ראויה],\u0006 מה אפשר לצבור בה?","\u0003תרגומא\u0004 \u0005[תירגם,\u0006 הסביר \u0005אותה]\u0006 \u0003רב שמואל בר ביסנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: כגון שנעץ בה\u0004 בקרקע כלשהו \u0003מחט\u0004 ומכרה אגב הקרקע, ואפשר איפוא לקנות משהו גם על ידי קניית קרקע כלשהי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: קבסתן\u0004 \u0005[אתה\u0006 \u0005מגעיל\u0006 \u0005אותי]!\u0006 וכי \u0003איכפל\u0004 \u0005[טרח]\u0006 ה\u0003תנא\u0004 כל כך \u0003לאשמועינן\u0004 \u0005[להשמיע לנו]\u0006 קניית \u0003מחט\u0004 שאותה מוכרים אגב הקרקע? \u0003אמר רב אשי: מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 ש\u0003לא תלה בה\u0004 במחט \u0003מרגניתא דשוויא אלפא זוזי\u0004 \u0005[מרגלית ששווה אלף זוז]\u0006 ואפשר לקנות הרבה אגב קרקע זו. ומכל מקום לא נפתרה השאלה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, ש\u0003אמר ר' אלעזר: מעשה במדוני אחד\u0004 (איש מהישוב מדון) \u0003שהיה בירושלים שהיו לו מטלטלין הרבה, וביקש ליתנם במתנה\u0004 והיה הדבר קשה לו, שלא יכול היה להמתין עד שימשכום המקבלים. \u0003אמרו לו: אין לו תקנה עד שיקנם על גבי קרקע. מה עשה? הלך ולקח\u0004 (קנה) \u0003בית סלע סמוך לירושלים, ואמר:\u0004 חלק \u0003צפוני זה\u0004 של בית הסלע נתון \u0003לפלוני, ועמו מאה צאן ומאה חביו\u0004 \u0003ת. ומת\u0004 המדוני, \u0003וקיימו\u0004 חכמים \u0003את דבריו\u0004 ונתנו המתנות.","\u0003ואי אמרת בעינן\u0004 \u0005[ואם אומר אתה\u0006 שכדי לקנות מטלטלין אגב קרקע \u0005צריכים אנו]\u0006 שיהיו המטלטלין \u0003צבורים בה, בית סלע למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]\u0006 וכי אפשר לשים בו מאה צאן ומאה חביות? ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003בית סלע\u0004 כוונתו למקום ששיעורו כמטבע של \u0003סלע ממש?\u0004 לא, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003סלע\u0004 — מדובר במקום \u0003דנפיש טובא\u0004 \u0005[ש\u0006היה \u0005גדול מאד],\u0006 וייתכן שצברו בתוכו את המתנות הללו. \u0003ו\u0004אם כן \u0003אמאי קרו ליה\u0004 \u0005[מדוע קראו לו]\u0006 \u0003סלע\u0004 — \u0003דקשי\u0004 \u0005[ש\u0006היה \u0005קשה]\u0006 \u0003כסלע.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר, ש\u0003אמר רב יהודה אמר רב: מעשה באדם אחד שחלה בירושלים,\u0004 ו\u0003כ\u0004דעת \u0003ר' אליעזר\u0004 שלדעתו אף חולה (שכיב מרע) אינו יכול להקנות דברים אלא בקנין גמור, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 ש\u0003בריא היה\u0004 — \u0003כרבנן\u0004 \u0005[כ\u0006דברי \u0005חכמים],\u0006 שלדעתם אם המדובר היה בחולה יכול היה לתת אותם ב\"מתנת שכיב מרע\" על ידי דיבור בלבד אלא שאותו אדם היה בריא ולכן לא יכול היה לתת אלא בקנין כראוי,","\u0003שהיו לו מטלטלין הרבה וביקש ליתנם במתנה, אמרו לו: אין לו תקנה עד שיקנם על גבי קרקע. מה עשה? הלך ולקח\u0004 (קנה) קרקע בגודל \u0003בית רובע סמוך לירושלים, ואמר: טפח על טפח\u0004 נתון \u0003לפלוני ועמו מאה צאן ומאה חביות, ומת וקיימו חכמים את דבריו. ואי\u0004 \u0003אמרת בעינן\u0004 \u0005[ואם אומר אתה\u0006 ש\u0005צריכים אנו]\u0006 שיהיו המטלטלין \u0003צבורים, טפח על טפח למאי חזי\u0004 \u0005[למה ראוי]?\u0006 וכי אפשר לצבור בו את כל המטלטלין הללו!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003לדמי\u0004 \u0005[לכסף]\u0006 שרצה לתת כסף בשווי אותן חביות וצאן, ואת הכסף הזה אמנם אפשר היה לשים שם. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שהמדובר דווקא בכסף. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שמדובר ב\u0003מאה צאן ומאה חביות ממש, ניקנינהו ניהליה\u0004 \u0005[שיקנה אותם לו\u0006 למקבל\u0005]\u0006 \u0003ב\u0004קנין \u0003חליפין\u0004 והיתה לו איפוא תקנה, מלבד קניית קרקע והקנאת המטלטלין על ידה. אבל לפי שהם טענו שמדובר בכסף, וכסף אינו נקנה בחליפין לכן הוצרך לקנייה זו.","על הסבר זה מקשים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אומר אתה — שהנותן התכוון \u0003ל\u0004הקניית \u0003דמי\u0004 \u0005[כספים]\u0006 שאינם נקנים בחליפין — אולם גם כאן יכול היה לעשות בדרך אחרת: \u0003ניקנינהו ניהליה\u0004 \u0005[שיקנה אותם לו\u0006 למקבל\u0005]\u0006 \u0003במשיכה. אלא\u0004 על כרחך חייב אתה לומר \u0003דליתיה\u0004 \u0005[שאינו\u0006 נמצא\u0005]\u0006 \u0003מקבל\u0004 ה\u0003מתנה\u0004 באותו מקום, ורצה לזכות לו היכן שהוא נמצא. אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר לומר \u0003דליתיה\u0004 \u0005[שאינו]\u0006 \u0003למקבל מתנה\u0004 באותו מקום, ולא יכול היה להקנות לו בחליפין ולפיכך הקנה לו אגב קרקע, אפילו שלא היו צבורים.","ושואלים: והלא יש דרך אחרת \u0003וניזכינהו ניהליה\u0004 \u0005[ושיזכה אותם לו]\u0006 \u0003אגב אחר\u0004 כלומר, בקנין משיכה שיעשה אדם אחר עבור המקבל, ומשיבים: \u0003לא סמכה דעתיה\u0004 \u0005[אין דעתו\u0006 של הנותן \u0005סומכת]\u0006 על כך, כי \u0003סבר שמיט ואכיל להו\u0004 \u0005[סבור\u0006 הוא \u0005שישמוט ויאכל אותם]\u0006 אותו אדם, ושמא ישתמש בנכסים אלה, ולכן רצה להבטיח שהקנין ייגמר מיד.","\u0003ואלא\u0004 לפי זה \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הביטוי \u0003\"אין לו תקנה\"\u0004 שאמרו חכמים ביחס למבקש להקנות רק על ידי קנין אגב קרקע? והרי ראינו שיש דרך לעשות זאת על ידי זיכוי אלא שהוא לא רצה בכך! ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003למאי\u0004 \u0005[למה]\u0006 ש\u0003לא סמכה דעתיה\u0004 \u0005[דעתו]\u0006 על אחר, ולא רוצה להעביר את הרכוש ואת הנכסים על ידי אחר, כלומר, בנסיבות אלה — \u0003אין לו תקנה עד שיקנם על גבי קרקע.\u0004 ואין לנו אם כן ראיה מכרעת אם יכול להקנות גם נכסים שאינם צבורים בקרקע.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת, ממה ששנינו: \u0003מעשה ברבן גמליאל וזקנים שהיו באים בספינה, אמר להם רבן גמליאל לזקנים: עישור\u0004 (מעשר) של התבואה \u0003שאני עתיד למוד\u0004 (למדוד) ולהפריש מתבואת שדותי"],["\u0003נתון לו ליהושע\u0004 בן חנניה, שהיה לוי, \u0003ומקומו\u0004 של אותו מעשר \u0003מושכר לו,\u0004 כך שיוכל לקנות את המעשר אגב הקרקע. \u0003ועישור אחר שאני עתיד למוד\u0004 (למדוד) כמעשר עני \u0003נתון לו לעקיבא בן יוסף, כדי שיזכה בו לעניים, ומקומו מושכר לו.\u0004 אם כן \u0003שמע מינה בעינן\u0004 \u0005[למד מכאן\u0006 כי \u0005צריכים אנו]\u0006 שיהיו המטלטלין \u0003צבורים בה\u0004 בקרקע שהרי הדגיש \"מקומו\". ודוחים: \u0003שאני התם כי היכי\u0004 \u0005[שונה שם\u0006 ש\u0005כדי]\u0006 ש\u0003לא ליטרחינהו\u0004 \u0005[להטריח אותם]\u0006 שיצטרכו להעביר את המעשרות למקום אחר, לכן הקנה להם את הקרקע במקום המעשר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ש\u0003אמר רבא בר יצחק אמר רב: שני\u0004 מיני \u0003שטרות הן:\u0004 אם אמר \u0003\"זכו בשדה זו לפלוני וכתבו לו את השטר\u0004 כראיה על מכירת השדה \u0003\"\u0004— \u0003חוזר בשטר,\u0004 כלומר, יכול להתחרט ולומר להם לא לכתוב את השטר, \u0003ו\u0004אולם \u0003אינו חוזר בשדה,\u0004 שכבר זכה הקונה בשדה. ואולם אם אמר באופן זה: \u0003\"\u0004זכו בשדה זו לפלוני \u0003על מנת שתכתבו לו את השטר\"\u0004 ועדיין לא נתנו — \u0003חוזר בין בשטר בין בשדה,\u0004 שעל מנת שיכתוב לו שטר הקנה את השדה.","\u0003ורב חייא בר אבין אמר\u0004 בשם \u0003רב הונא: שלשה שטרות הן; תרי\u0004 \u0005[שניים]\u0006 — \u0003הא דאמרן\u0004 \u0005[אלה שאמרנו],\u0006 \u0003אידך\u0004 \u0005[\u0006ו\u0005האחר]:\u0006 \u0003אם קדם מוכר וכתב לו את השטר,\u0004 שיכול המוכר לכתוב שטר מכירה, ונותן אותו כאשר מקבל את התמורה, \u0003כאותה ששנינו: כותבים שטר למוכר אף על פי שאין לוקח עמו.\u0004 ובמקרה שזה שקדם וכתב את השטר \u0003כיון שהחזיק\u0004 הלוקח \u0003עמו בקרקע\u0004 — \u0003נקנה שטר בכל מקום שהוא.\u0004","ועל כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לא בעינן\u0004 \u0005[\u0006ש\u0005אין אנו צריכים]\u0006 שיהיו הנכסים \u0003צבורים בה,\u0004 שהרי כאן השטר נקנה אגב הקרקע בכל מקום שהוא! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שטר דאפסירא דארעא\u0004 \u0005[ש\u0006כמו \u0005הרסן של הקרקע]\u0006 \u0003הוא\u0004 שעל ידו מחזיקים בקרקע ואינו זקוק להיות בתוכה ממש.","ומקשים: \u0003והא עלה קתני\u0004 \u0005[והרי על\u0006 הלכה זו שהשטר נקנה בכל מקום שהוא \u0005שנינו]:\u0006 \u0003זו היא ששנינו נכסים שאין להם אחריות נקנין עם נכסים שיש להם אחריות בכסף בשטר ובחזקה!\u0004 משמע שאין הבדל בין שטר לשאר נכסים, ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 כי \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיו הנכסים \u0003צבורים בה.\u0004 ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 שיאמר המקנה בקנין \u0003אגב\u0004 במפורש שמקנה לו קרקע ואגב כך גם מטלטלין, \u0003או לא?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה \u0003דקתני כל הני\u0004 \u0005[ששנה\u0006 את \u0005כל\u0006 דינים \u0005אלה]\u0006 מקודם בדיני קנין מטלטלין על ידי מקרקעין, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 בהם לשון \u0003אגב,\u0004 ומשמע שאין צורך בכך. ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאמר לו \u0003\"קני\"\u0004 \u0005[קנה],\u0006 \u0003מי קתני\u0004 \u0005[האם שנה]?\u0006 והרי בודאי צריך היה לומר לו \"קנה\"!","\u0003אלא\u0004 על כרחך אתה חייב לומר \u0003עד דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003\"קני\", הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תוסיף \u0003עד דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003\"אגב\",\u0004 ואין ראיה ממה שלא נזכר הדבר שם, משום שלא היה ענין אותן הברייתות לדון באופן האמירה, אלא בצד המשפטי העקרוני של הבעיה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: שיהיו הנכסים בקרקע \u0003צבורים\u0004 — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים],\u0006 אבל שהמקנה יאמר במפורש שהוא מקנה את המטלטלין \u0003אגב\u0004 קרקע \u0003ו\u0004גם לומר במפורש \"\u0003קני\"\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: כשהמקנה רוצה לתת \u0003שדה במכר ומטלטלין\u0004 רוצה לתת \u0003במתנה מהו\u0004 הדין? האם יכול להקנות אותם בבת אחת בקנין אגב קרקע? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מן המעשה ברבן גמליאל שאמר: \u0003עישור שאני עתיד למוד, נתון ליהושע ומקומו מושכר לו, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאף שהשדה היה בהשכרה (שהוא כעין מכר) והמעשר ניתן במתנה — אפשר להקנותם ביחד!","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה נוספת: נתן \u0003שדה לאחד, ומטלטלין לאחר מהו?\u0004 האם אפשר להקנות מטלטלין לאדם אחד אגב קרקע שמקנה לאחר? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003עישור שאני עתיד למוד נתון לעקיבא בן יוסף כדי שיזכה בו לעניים ומקומו מושכר לו.\u0004 שאף שהמתנה היתה לעניים, והמקום הושכר לר' עקיבא — אפשר היה להקנותם.","ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מושכר\"\u0004 כאן — \u0003מושכר למעשר,\u0004 שקרקע זו לא הושכרה לר' עקיבא לצרכיו, אלא רק לצורך החזקת המעשר, ואם כן הכל הוא לצורך העניים. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ודחה באופן אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ר' עקיבא\u0004 שכיון שהיה גבאי צדקה, ש\u0003יד עניים הוה\u0004 \u0005[היה],\u0006 שגבאי צדקה נחשב כאילו היה רק יד הזוכה עבור העניים כעניים עצמם, ואין הדבר נחשב כזכיה על מנת להקנות לאחרים.","\u0003אמר רבא: לא שנו\u0004 שאדם קונה מטלטלין אגב הקרקע \u0003אלא שנתן דמי כולן\u0004 — דמי הקרקע ודמי המטלטלין כולם, \u0003אבל\u0004 אם \u0003לא נתן דמי\u0004 המטלטלין \u0003כולן\u0004 אף על פי שהקנה לו — \u0003לא קנה\u0004 מטלטלין \u0003אלא כנגד\u0004 (כשיעור) \u0003מעותיו\u0004 ששילם.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא\u0004 ששנינו בה: \u0003יפה\u0004 (גדול) \u0003כח הכסף מכח השטר\u0004 בצד אחד, \u0003ו\u0004יפה \u0003כח השטר מכח הכסף\u0004 בצד אחר. ופרטי הדברים: \u0003יפה כח הכסף\u0004 — \u0003שהכסף פודין בו הקדשות, ו\u0004פודים בו \u0003מעשר שני\u0004 — \u0003מה שאין כן בשטר. ויפה כח השטר\u0004 — \u0003שהשטר מוציא בבת ישראל,\u0004 שעל ידי שטר (גט) יכול לגרש אשה, \u0003מה שאין כן בכסף. ו\u0004עוד","\u0003יפה כח שניהם מכח חזקה, וכח חזקה מכח שניהם.\u0004 כיצד? \u0003יפה כח שניהם\u0004 מכח חזקה — \u0003ששניהם קונים בעבד עברי\u0004 שנקנה הן בכסף והן בשטר, \u0003מה שאין כן\u0004 \u0003בחזקה. יפה כח חזקה: שחזקה\u0004 אם \u0003מכר לו עשר שדות בעשר מדינות, כיון שהחזיק באחת מהם\u0004 — \u0003קנאם כולם\u0004 בבת אחת."],["\u0003במה דברים אמורים\u0004 — \u0003שנתן לו דמי\u0004 הקרקעות \u0003כולן, אבל\u0004 אם \u0003לא נתן לו דמי כולן\u0004 — \u0003לא קנה אלא כנגד מעותיו,\u0004 וכדברי רבא. ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה ששנינו בברייתא \u0003לשמואל.\u0004 ש\u0003אמר שמואל: מכר לו עשר שדות בעשר מדינות, כיון שהחזיק באחת מהן\u0004 — \u0003קנה את כולן.\u0004","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: תדע\u0004 שכן הוא, \u0003שאילו מסר לו עשר בהמות באפסר אחד ואמר ליה\u0004 \u0005[לו]\u0006 \u0003\"קני\"\u0004 \u0005[\"קנה\u0006 אותם\"\u0005]\u0006 \u0003מי לא קני\u0004 \u0005[האם אינו קונה]?\u0006 ואף כאן כל השדות נחשבים כשדה אחד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 \u0003איגודו,\u0004 האפסר האוגד את כל הבהמות, נמצא \u0003בידו, הכא\u0004 \u0005[כאן]\u0006 בשדות \u0003אין איגודו בידו.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן אחר: \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: תדע דלא קני\u0004 \u0005[שאינו קונה]\u0006 את כל השדות בחזקה שעשה בשדה אחד, שהרי \u0003אילו מסר לו עשר בהמות באפסר אחד ואמר לו \"זו קני\"\u0004 \u0005[קנה]\u0006 — \u0003מי קני\u0004 \u0005[האם קונה]\u0006 הוא את כולן? אף כאן כשהחזיק בשדה אחד בלבד כאילו אמר לו \"קנה זו\", ולא קנה בכך את שאר השדות.","ודוחים את ההשוואה: \u0003מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הבהמות הן \u0003גופים מוחלקים\u0004 ולכן כאשר אמר לו על בהמה אחת \"זו קנה\" — אין הבהמות האחרות ניקנות עימה. \u0003הכא סדנא דארעא חד\u0004 \u0005[כאן הסדן,\u0006 הבסיס, \u0005של הארץ אחד]\u0006 \u0003הוא,\u0004 וכיון שקונה קרקע במקום אחד — קונה עימה את כל שאר הקרקעות.","שנינו במשנה שנכסים שאין להם אחריות, כלומר, מטלטלין, \u0003זוקקים את הנכסים\u0004 שיש להם אחריות, כלומר, קרקעות, להישבע גם עליהן, על אף שאין נשבעים על הקרקעות בפני עצמן. \u0003אמר עולא: מנין,\u0004 כיצד אנחנו למדים \u0003לגלגול שבועה מן התורה,\u0004 שאם חייב אדם להישבע על דבר אחד, שיכול הצד שכנגד להשביע אותו על טענות אחרות שעליהן לבדן אינו יכול לחייבו שבועה —","\u0003שנאמר\u0004 בסוטה \u0003\"ואמרה האשה אמן אמן\"\u0004 (במדבר ה, כב), \u0003ותנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003על מה היא אומרת\u0004 לשון כפולה \u0003\"אמן אמן\"? \"אמן\"\u0004 אחד — שמקבלת \u0003על\u0004 עצמה את \u0003האלה\u0004 (הקללה) הנאמרת על ידי הכהן המשקה אותה, \u0003\"אמן\"\u0004 שני \u0003על השבועה\u0004 שמשביעים אותה. וכן \"אמן אמן\": \u0003\"אמן\"\u0004 — \u0003אם מאיש זה\u0004 שנחשדה בו, \u0003\"אמן\"\u0004 — \u0003אם מאיש אחר.\u0004 ועוד: \u0003\"אמן\"\u0004 — \u0003שלא סטיתי\u0004 הן כשהייתי \u0003ארוסה ו\u0004הן כשהייתי \u0003נשואה ו\u0004הן בזמן שהייתי \u0003שומרת יבם ו\u0004הן כשהייתי \u0003כנוסה\u0004 על ידי היבם.","ותחילה מבררים הלכה זו לגופה: \u0003האי ארוסה היכי דמי\u0004 \u0005[ארוסה זו\u0006 שהזכרנו, \u0005כיצד היתה]?\u0006 \u0003אילימא דקני\u0004 \u0005[אם תאמר שקינא]\u0006 \u0003לה כשהיא ארוסה וקא משקי לה\u0004 \u0005[ומשקה אותה]\u0006 את המים המרים \u0003כשהיא ארוסה\u0004 — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארוסה ושומרת יבם\u0004 כשנחשדו שהן סוטות \u0003לא שותות ולא נוטלות כתובה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — שבלשון השבועה \u0003\"\u0004כי שטית \u0003תחת אישך\"\u0004 (שם כ) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי לא היתה עדיין תחת אישה.","\u0003אלא\u0004 צריך לומר \u0003דקני\u0004 \u0005[שקינא]\u0006 \u0003לה כשהיא ארוסה\u0004 על מה שעשתה כשהיא ארוסה, \u0003ונסתרה כשהיא ארוסה, וקא משקי לה\u0004 \u0005[ומשקה אותה]\u0006 \u0003כשהיא נשואה.\u0004","אולם במקרה כזה \u0003מי בדקי לה מיא\u0004 \u0005[האם בודקים אותה המים]?\u0006 הלא \u0003\"ונקה האיש מעון\"\u0004 (שם, לא) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 לומר: \u0003בזמן שהאיש מנוקה מעון\u0004 — ה\u0003מים בודקים את אשתו,\u0004 אבל אם \u0003אין איש מנוקה מעון\u0004 באותו ענין — \u0003אין המים בודקים את אשתו.\u0004 וכיון שחשד בה כשהיתה ארוסה, שהרי קינא לה, והיא אמנם נסתרה אסור היה לו לישא אותה, ואם עשה כן — הרי הוא עצמו חוטא, ובמקרה כזה אין המים בודקים את אשתו. הרי שבארוסה כשלעצמה אין כל דרך שתיבדק כסוטה.","\u0003אלא\u0004 יש לומר שהשבעה זו היא רק \u0003על ידי גלגול,\u0004 שאף שבמישרין אינו יכול להשביע אותה על כך, מכל מקום אם קינא לה ונסתרה לאחר הנישואין כיון שהיא נשבעת על מה שעשתה כשהיא נשואה — יכול להשביע אותה, בדרך של גלגול שבועה, גם על מה שהיה בזמן האירוסין!","ומעירים: \u0003אשכחן סוטה דאיסורא\u0004 \u0005[מצאנו\u0006 גלגול שבועה ב\u0005סוטה\u0006 שהוא מדיני \u0005איסורים],\u0006 ואולם \u0003ממונא מנלן\u0004 \u0005[\u0006בענייני \u0005ממונות\u0006 כבמשנתנו \u0005מניין לנו]\u0006 שיש גם כן גלגול שבועה? \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית מדרשו]\u0006 של \u0003ר' ישמעאל: קל וחומר\u0004 הדברים: \u0003ומה סוטה\u0004"],["\u0003שלא ניתנה להתבע בעד אחד,\u0004 שלכל הדעות כדי שתתחייב הסוטה בשבועה ראשונה צריך שיעידו שני עדים, וראינו שבסוטה \u0003מגלגלין\u0004 עליה שבועה אחרת, \u0003ממון שניתן להתבע בעד אחד,\u0004 שאם יש עד אחד שמסייע לטענת התובע מחייבים את הנתבע שבועה — \u0003אינו דין שמגלגלין\u0004 עליו שבועה אחרת?","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה \u0003ב\u0004טענת \u0003ודאי,\u0004 שברור לתובע שכך היה הדבר, ואולם בטענת \u0003ספק,\u0004 שאינו טוען בוודאות שהנתבע חייב לו אלא בחשד בלבד \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שיכול לגלגל שבועה אחרת?","ומשיבים: \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן יוחאי אומר: נאמרה\u0004 בתורה \u0003שבועה בחוץ\u0004 (מחוץ למקדש) בכל מקום, כגון שבועת הפקדון שהיא נעשית בפני כל בית דין, \u0003ונאמרה שבועה בפנים\u0004 (בעזרה שבמקדש) בסוטה, \u0003מה שבועה האמורה בפנים\u0004 — \u0003עשה בה ספק כודאי,\u0004 שהרי הבעל אינו טוען טענת ודאי כנגד אשתו וכל עיקרה של טענתו הוא מספק ומכל מקום יכול לגלגל מכוח טענה זו גם שבועה אחרת — \u0003אף שבועה האמורה בחוץ עשה בה ספק כודאי\u0004 ומגלגלים על ידה שבועה אחרת גם בטענת ספק.","ולענין הלכה שואלים: \u0003עד היכן\u0004 הוא \u0003גלגול שבועה?\u0004 שהרי אמרנו שיכול התובע לגלגל שבועה על הנתבע גם על טענות אחרות שאינן מענין התביעה המתבררת עתה בבית הדין, ואולם עד היכן יכול לתבוע ולחייבו שבועה על תביעתו זו? \u0003אמר רב יהודה אמר רב:\u0004 אפילו ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"הישבע לי שאין עבדי אתה\"\u0004 יכול לגלגל עליו שבועה על כך, אם חייב הנתבע שבועה על דבר אחר.","ותוהים: \u0003ההוא\u0004 (זה) שאומר כך לחבירו הלא \u0003שמותי משמתינן ליה\u0004 \u0005[מנדים אותו]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקורא לחבירו \"עבד\"\u0004 — \u0003יהא בנידוי.\u0004 הקורא לחבירו \u0003\"ממזר\"\u0004 — \u0003סופג\u0004 (לוקה, מקבל) \u0003את\u0004 מלקות \u0003הארבעים.\u0004 הקורא לחבירו \u0003\"רשע\"\u0004 — הנעלב \u0003יורד עמו לחייו,\u0004 שרשאי להציק לו בדרכים שונות. ואם כן, הטוען כנגד חבירו שהוא עבד — מענישים אותו. ובודאי אין מגלגלים שבועה בטענה כגון זו!","\u0003אלא אמר רבא:\u0004 יכול התובע לגלגל עליו שבועה בטענה: \u0003הישבע לי שלא נמכרת לי בעבד עברי.\u0004 שאז אינו בא לפוסלו מבחינת היוחסין, אלא טוען שהלה נמכר לו כעבד עברי וצריך לעבוד עבורו. ושואלים: והרי במקרה זה אין בכך חידוש, שכן \u0003האי טענתא מעלייתא היא\u0004 \u0005[\u0006טענה \u0005זו טענה מעולה היא],\u0006 \u0003ממונא אית ליה גביה\u0004 \u0005[\u0006חוב \u0005ממון יש לו אצלו],\u0006 ואם כן טענה זו דינה כשאר טענת ממון ופשוט שמגלגלים! ומשיבים: \u0003רבא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר רבא: עבד עברי גופו קנוי,\u0004 ואם כן הטענה היא יותר מאשר טענת ממון, אלא טענה של קנין הגוף.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו טענה לגבי \u0003קרקע,\u0004 והרי כבר למדנו במשנתנו שיש גלגול שבועה על קרקעות! ומשיבים: יש בכך חידוש, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003קרקע הוא דעבדי אינשי דמזבני בצינעא\u0004 \u0005[שעשויים אנשים שמוכרים בצינעה],\u0006 \u0003אם איתא דזבין\u0004 \u0005[\u0006וגם \u0005אם יש\u0006 אמת בטענת התובע \u0005שמכר\u0006 לו\u0005]\u0006 — \u0003לית ליה קלא\u0004 \u0005[אין לו,\u0006 למכר, \u0005קול]\u0006 ואין הדבר נודע לרבים ולכן יכול לטעון שמכר לו על אף שאין איש יודע על כך.","אבל \u0003האי\u0004 \u0005[זה]\u0006 המוכר עצמו לעבד עברי, \u0003אם איתא דזבין\u0004 \u0005[אם יש\u0006 אמת בדבר \u0005שמכר]\u0006 — \u0003קלא אית ליה\u0004 \u0005[קול יש לו],\u0006 וכיון שלא היה קול בדבר לא יוכל לטעון, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא שבכל זאת אין העדר השמועה הוכחה, ויכול לגלגל עליו שבועה גם על טענה זו.","\u0003כל הנעשה דמים באחר\u0004 שהוא נעשה תמורה, תשלום לדבר אחר, \u0003כיון שזכה זה\u0004 אחד הצדדים בחלקו בעיסקה — \u0003נתחייב זה\u0004 הצד השני \u0003בחליפיו,\u0004 ונחשב החפץ השני כשייך לו לגמרי, ואם התקלקל או אבד — ההפסד הוא שלו. \u0003כיצד? החליף שור בפרה או חמור בשור, כיון שזכה זה,\u0004 אחד מהם, בדבר שקיבל לאחר שעשה בו קנין — \u0003נתחייב זה בחליפיו,\u0004 שהצד האחר חייב להשלים את חלקו בעיסקה.","שואלים: \u0003חליפין\u0004 המוזכרים במשנה שנעשו דמים באחר \u0003מאי ניהו\u0004 \u0005[מה הם]?\u0006 אם הכוונה ל\u0003מטבע,\u0004 שבמטבע מעריכים את דמיו של כל חפץ ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003מטבע נעשה חליפין\u0004 ואפשר לעשות קנין חליפין אף על ידי מטבעות והרי זה בניגוד למסקנת ההלכה בנושא זה! \u0003אמר רב יהודה\u0004 אפשר להבין את המשנה באופן אחר, ולא במשמעות ש\"כל הנעשה דמים\" כוונתו הוא למעות. אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003כל הנישום דמים באחר\u0004 כלומר, כל דבר שיש לו ערך כספי, שאפשר להעריך את מחירו כשווה ערך לדבר אחר,"],["\u0003כיון שזכה זה\u0004 בדבר \u0003נתחייב\u0004 השני \u0003בחליפין.\u0004 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 מלשון המשנה להסביר בדרך זו: \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה לאחר מכן: \u0003כיצד?\u0004 — \u0003החליף שור בפרה או חמור בשור,\u0004 משמע שמסביר את הדברים שנאמרו קודם. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, שמדובר במשנה בקנין חליפין של חפצים ולא בכסף.","ושואלים: \u0003ולמאי דסליק אדעתין מעיקרא\u0004 \u0005[ולמה שעלה על דעתנו מתחילה]\u0006 לומר ש\u0003מטבע נעשה חליפין, מאי\u0004 \u0005[מה]\u0006 משמעות לשון \u0003כיצד\u0004 — החליף שור בפרה וכו', אם בכסף אנו עוסקים! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 שלפי שיטה זו צריך להבין את המשנה כך: לא רק שמטבע נעשה חליפין אלא \u0003פירות נמי עבדי\u0004 \u0005[גם כן עושים]\u0006 \u0003חליפין.\u0004 ומסבירים: \u0003כיצד?\u0004 — \u0003החליף בשר שור בפרה או בשר חמור בשור, כיון שזכה זה נתחייב בחליפין.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003רב ששת,\u0004 ש\u0003אמר: פירות עבדי\u0004 \u0005[עושים]\u0006 \u0003חליפין,\u0004 שיש דין קנין חליפין לא רק בכלים אלא גם בפירות, ובכלל זה בעלי חיים. \u0003אלא לרב נחמן\u0004 ש\u0003אמר: פירות לא עבדי\u0004 \u0005[אין עושים]\u0006 \u0003חליפין, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 כאן?","ומשיבים: לשיטתו עוסקת המשנה רק בכסף, כסברה הראשונה ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003יש דמים שהן כחליפין, כיצד?\u0004 — אם \u0003החליף דמי שור בפרה או דמי חמור בשור,\u0004 שלאחר שמשך הקונה את השור מציע למוכר שיקבל במקום כסף את הפרה שלו, ופרה זו נקנית איפוא לא כקנין חליפין אלא כעין כסף.","\u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 הרי אין כסף קונה מטלטלין — \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' יוחנן,\u0004 ש\u0003אמר: דבר תורה,\u0004 כלומר, מעיקר הדין \u0003מעות קונות,\u0004 וכאשר משלם כסף זוכה המשלם בחפץ, אף שלא משכו בידו. \u0003ומה טעם אמרו\u0004 חכמים \u0003משיכה קונה\u0004 ולא מעות — \u0003גזירה שמא יאמר לו\u0004 המוכר לקונה לאחר שקיבל את הכסף ממנו \u0003\"נשרפו חיטיך בעלייה\".\u0004 כלומר, שאם תארע שריפה (או אונס אחר) לאחר קבלת המעות, לא יטרח המוכר להציל את החפץ שבביתו, מאחר שכבר איננו שלו ונמצא הקונה מפסיד. משום כך תיקנו חכמים שלא יהא קנין אלא אחר שימשוך הקונה את החפץ.","ומה שבמשנתנו נראה שיש קנין במעות בלבד — יש להסביר כי \u0003מילתא דשכיח\u0004 \u0005[דבר המצוי]\u0006 \u0003גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 ואמרו שאין מעות קונות, ואילו \u0003מילתא דלא שכיח\u0004 \u0005[דבר שאינו מצוי]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 וקנין חליפין על ידי כסף (\"דמי חמור בשור\") הוא דבר שאינו שכיח, ולכן לא גזרו בו חכמים והשאירו קנין כסף במקומו.","ושואלים: \u0003ול\u0004דעת \u0003ריש לקיש,\u0004 החולק על ר' יוחנן, ש\u0003אמר משיכה מפורשת מן התורה\u0004 ואין קנין אלא במשיכה בלבד ואין לחלק דין דבר מצוי לדבר שאינו מצוי, \u0003הניחא אי סבר לה\u0004 \u0005[זה נוח אם\u0006 הוא \u0005סבור]\u0006 \u0003כ\u0004דעת \u0003רב ששת\u0004 ש\u0003אמר פירות עבדי\u0004 \u0005[עושים]\u0006 \u0003חליפין\u0004 הריהו \u0003מתרץ\u0004 (מיישב) את המשנה \u0003כ\u0004דעת \u0003רב ששת.\u0004","\u0003אלא אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כ\u0004דעת \u0003רב נחמן\u0004 ש\u0003אמר פירות לא עבדי\u0004 \u0005[אין עושים]\u0006 \u0003חליפין, ומטבע לא קני\u0004 \u0005[אינו קונה]\u0006 לא מדין תורה ולא מדברי סופרים, \u0003במאי מוקי לה\u0004 \u0005[במה מעמיד\u0006 הוא \u0005אותה]?\u0006 ומשיבים: \u0003על כרחך\u0004 נאלץ אתה לפי דיוק זה, לומר כי \u0003כ\u0004דעת \u0003רב ששת סבירא ליה\u0004 \u0005[סבור הוא].\u0006","\u0003רשות הגבוה בכסף,\u0004 שהגבוה = ההקדש יש לו כוח קנין על ידי נתינת כסף למוכר. \u0003ורשות\u0004 (דרך הקנין) של \u0003ההדיוט\u0004 היא \u0003בחזקה.\u0004 ועוד: \u0003אמירתו לגבוה\u0004 כשאדם מקדיש דבר מסויים באמירה בלבד — הרי זה \u0003כמסירתו\u0004 בפועל \u0003להדיוט,\u0004 ונקנה הדבר להקדש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד רשות הגבוה בכסף?\u0004 — \u0003גיזבר\u0004 של ההקדש \u0003שנתן מעות בבהמה\u0004 (עבור בהמה), \u0003אפילו\u0004 ה\u0003בהמה\u0004 נמצאת \u0003בסוף העולם\u0004 — \u0003קנה\u0004 מיד. \u0003ובהדיוט לא קנה\u0004 את הבהמה \u0003עד שימשוך\u0004 אותה.","\u0003כיצד אמירתו לגבוה\u0004 נידונה \u0003כמסירתו להדיוט? האומר \"שור זה עולה\"\u0004 או \u0003\"בית זה הקדש\", אפילו\u0004 היו אלה \u0003בסוף העולם\u0004 — \u0003קנה\u0004 ההקדש. ואין צורך במעשה קנין אחר, אלא האמירה בלבד גומרת את הקנין. אולם \u0003בהדיוט\u0004 במקרה כגון זה, \u0003לא קנה\u0004"],["\u0003עד שימשוך\u0004 או \u0003יחזיק.\u0004 ועוד ביתרון כוחו של ההקדש: חפץ של הקדש ש\u0003משכו\u0004 ההדיוט על מנת לקנותו \u0003במנה\u0004 (מאה דינר) \u0003ולא הספיק לפדותו\u0004 ולשלם בפועל את מאה הדינר לגיזבר ההקדש \u0003עד שעמד\u0004 מחירו של החפץ \u0003במאתים\u0004 — \u0003נותן\u0004 ההדיוט \u0003מאתים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — שהרי נאמר \u0003\"ונתן הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט) משמע שאינו קונה מן ההקדש אלא במתן הכסף בפועל.","ואולם אם קרה להיפך ש\u0003משכו\u0004 ההדיוט כאשר היה מחירו \u0003במאתים, ולא הספיק לפדותו עד שעמד\u0004 מחירו של החפץ \u0003במנה\u0004 — גם אז \u0003נותן מאתים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003לא יהא כח הדיוט חמור מהקדש,\u0004 וכיון שההדיוט גומר את קנייניו במשיכה — נקנה לו החפץ במחיר זה, ואין להקדש להפסיד במקום שבו היה המכר מתקיים כך אצל ההדיוט.","וכן אם כאשר \u0003פדאו\u0004 שילם \u0003במאתים, ולא הספיק למושכו עד שעמד\u0004 מחירו \u0003במנה\u0004 — \u0003נותן מאתים, מאי טעמא\u0004 \u0005[מה טעם]\u0006 — כאמור \u0003\"ונתן הכסף וקם לו\"\u0004 שקנין ההקדש הוא בכסף. אבל אם \u0003פדאו במנה ולא הספיק למושכו עד שעמד במאתים\u0004 — \u0003מה שפדה פדוי, ואין נותן אלא מנה.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הכי נמי נימא\u0004 \u0005[כאן גם כן נאמר]:\u0006 \u0003לא יהא כח הדיוט חמור מהקדש,\u0004 ובמקרה כגון זה אם היה זה בהדיוט, היה צריך להוסיף עד מאתיים כפי שהיה שווה הדבר בשעת משיכה שרק אז הוא קונה את הדבר והקדש לא יותר גרוע מהדיוט?","ומשיבים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003הדיוט\u0004 שנתן כסף וחוזר בו לפני שמשך \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ב\u0004קללה של \u0003\"מי שפרע\u0004 מאנשי דור המבול ומדור הפלגה הוא עתיד להיפרע ממי שאינו עומד בדיבורו \u0003\" קאי\u0004 \u0005[\u0006הוא \u0005עומד]?\u0006 וכיון שכן, אין כאן כוח הדיוט חמור מהקדש, שכן גם בהדיוט קנה בכסף לענין שלא יוכל לחזור בו.","\u0003כל מצות הבן\u0004 המוטלות \u0003על האב\u0004 לעשות לבנו \u0003אנשים חייבין\u0004 בהן \u0003ונשים פטורות. וכל מצות האב\u0004 המוטלות \u0003על הבן\u0004 — \u0003אחד אנשים ואחד נשים חייבין\u0004 בהן. \u0003ו\u0004עוד הבדל בחיוב מצוות בין גברים ונשים: \u0003כל מצות עשה שהזמן גרמא\u0004 \u0005[גורם],\u0006 כלומר, שקיומן הוא דווקא בזמן מסויים ולא בכל עת — \u0003אנשים חייבין\u0004 בהן \u0003ונשים פטורות. וכל מצות עשה שלא הזמן גרמא\u0004 — \u0003אחד האנשים ואחד הנשים חייבין.\u0004","\u0003וכל מצות לא תעשה, בין\u0004 אלו \u0003שהזמן גרמא בין\u0004 אלו \u0003שלא הזמן גרמא\u0004 — \u0003אחד האנשים ואחד הנשים חייבין, חוץ מ\u0004האיסורים של \u0003\"בל תקיף\",\u0004 המורה על איסור הקפת פאת הראש, \u0003ו\"בל תשחית\"\u0004 המורה על איסור השחתת הזקן (\"לא תקיפו פאת ראשכם, ולא תשחית את פאת זקנך\". ויקרא יט, כז). \u0003ו\u0004האיסור לכהנים של \u0003\"בל תטמא למתים\"\u0004 שחלים רק על גברים ולא על נשים, למרות שהם מצוות לא תעשה.","תחילה מבררים את לשון המשנה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל מצות הבן על האב\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כל מצות דמיחייב ברא למיעבד לאבא\u0004 \u0005[שמחוייב הבן לעשות לאב],\u0006 כלומר, מצוות המוטלות על הבן לעשות עבור אביו, ועל זה שנינו במשנה ש\u0003נשים פטורות, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר במצות כיבוד אב ואם \u0003\"איש\", אין לי אלא איש,\u0004 דהיינו גבר, שחייב בכך, \u0003אשה מנין\u0004 שגם היא חייבת? \u0003כשהוא אומר\u0004 באותו פסוק \u0003\"איש אמו ואביו תיראו\"\u0004 (שם יט, ג) בלשון רבים, \u0003הרי\u0004 אמורים \u0003כאן שנים\u0004 גם איש וגם אשה!","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את המשנה: \u0003כל מצות הבן, המוטלות על האב לעשות לבנו\u0004 — \u0003אנשים חייבין\u0004 בהן \u0003ונשים פטורות.\u0004","ומעירים: אם כן \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנה \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]\u0006 באופן מפורט ומפורש: \u0003האב חייב בבנו למולו, ולפדותו\u0004 (פדיון הבן הבכור מן הכהן), \u0003וללמדו תורה,\u0004 \u0003ולהשיאו אשה, וללמדו אומנות\u0004 (מקצוע). \u0003ויש אומרים: אף להשיטו במים,\u0004 כלומר, ללמד אותו לשחות. \u0003ר' יהודה אומר: כל\u0004 אב \u0003שאינו מלמד את בנו אומנות\u0004 — \u0003מלמדו ליסטות\u0004 (שוד). ותוהים על הלשון: \u0003ליסטות סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי ודאי אינו מלמדו ממש ליסטות! \u0003אלא\u0004 כך יש להבין: \u0003כאילו מלמדו ליסטות.\u0004 שכיון שאין לבן מקצוע למחייתו עלול הוא להתפתות להיות שודד או רמאי. עד כאן דברי הברייתא, שהיא אישור לפירושו של רב יהודה על המשנה. ומעתה באים לדון בה לגופה.","\u0003\"למולו\" מנלן\u0004 \u0005[מניין לנו]\u0006 שהאב מחוייב במצוה זו? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימל אברהם את יצחק בנו\"\u0004 (בראשית כא, ד). ומעירים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003לא מהליה אבוה\u0004 \u0005[מל אותו אביו]\u0006 \u0003מיחייבי בי דינא למימהליה\u0004 \u0005[חייבים בית דין למול אותו],\u0006 שחובה זו מוטלת על הכלל כאשר האב לא קיים אותה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"המול לכם\u0004 \u0003כל זכר\"\u0004 (שם יז, י,) כלומר, שזו היא מצוה כללית, שאינה תלויה דווקא באב. \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003לא מהליה בי דינא\u0004 \u0005[מלו אותו בית דין]\u0006 \u0003מיחייב איהו למימהל נפשיה\u0004 \u0005[חייב הוא,\u0006 הבן, \u0005למול את עצמו]\u0006 כשמגיע לבגרות. \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וערל זכר אשר לא ימול את בשר ערלתו ונכרתה\u0004 הנפש ההיא מעמיה","\u0003\"\u0004(שם, יד). ועוד, \u0003איהי מנלן דלא מיחייבא\u0004 \u0005[היא,\u0006 האשה, האם, \u0005מניין לנו שאינה מחוייבת]\u0006 למול את בנה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם \u0003\"\u0004וימל אברהם את יצחק בנו בן שמונת ימים \u0003כאשר צוה אתו אלהים\"\u0004 (שם כא, ד) ויש כאן הדגשה: \u0003אותו ולא אותה.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 שהיתה מצוה זו \u0003מיד,\u0004 בשעה שניתנה לאברהם, ואולם \u0003לדורות מנלן\u0004 \u0005[מניין לנו]\u0006 שיש לקיים את המצוה? \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל מקום שנאמר \"צו\" אינו אלא\u0004 לשון \u0003זירוז,\u0004 וכן כוונתו היא שהדבר ייעשה \u0003מיד, ו\u0004אף שתהיה מצוה זו נוהגת \u0003לדורות\u0004 וכן במצות מילה נאמר לשון ציווי.","ומסבירים: מניין שלשון \"צו\" היא לשון \u0003זירוז\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וצו את יהושע וחזקהו ואמצהו\"\u0004 (דברים ג, כח) ולשון \"צו\" שם אינה ציווי מוגדר אלא לשון כוללת שמובנה: זירוז וחיזוק. \u0003מיד ולדורות\u0004 מניין לנו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מן היום אשר צוה ה' והלאה לדרתיכם\"\u0004 (במדבר טו, כג) ומכאן למדים שכל מקום שנאמר בו \"צו\" כוונתו מאותו יום והלאה לכל הדורות.","עוד שנינו שאחת מחובות האב ביחס לבן היא \u0003לפדותו.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל בכור בניך תפדה\"\u0004 (שמות לד, כ). \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003לא פרקיה אבוה\u0004 \u0005[פדה אותו אביו]\u0006 \u0003מיחייב איהו למפרקיה\u0004 \u0005[מחוייב הוא לפדות אותו,\u0006 את עצמו\u0005]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פדה תפדה\"\u0004 (במדבר יח, טו) וכפילות הלשון מלמדת שצריך לפדות מכל מקום.","\u0003ואיהי מנלן דלא מיפקדה\u0004 \u0005[והיא,\u0006 האשה, האם, \u0005מניין לנו שאינה מצווה]\u0006 לפדות את בנה — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"תיפדה\"\u0004 ואפשר לקרוא אותו \u0003\"תפדה\",\u0004 לומר: \u0003כל שמצווה לפדות את עצמו\u0004 — \u0003מצווה לפדות את אחרים, וכל שאינו מצווה לפדות את עצמו\u0004 — \u0003אינו מצווה לפדות אחרים.\u0004 ואשה שאינה מצווה לפדות עצמה, אינה מצווה גם לפדות את בנה.","ושואלים: \u0003ואיהי מנלן דלא מיחייבא למיפרק נפשה\u0004 \u0005[והיא,\u0006 האשה, \u0005מניין לנו\u0006 \u0005שאינה מחוייבת לפדות\u0006 את \u0005עצמה]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"תפדה\"\u0004 שאפשר לקוראו גם \u0003\"תיפדה\",\u0004 לומר: \u0003כל שאחרים מצווים לפדותו\u0004 — \u0003מצווה לפדות את עצמו, וכל שאין אחרים מצווים לפדותו אין מצווה לפדות את עצמו.\u0004 וכיון שאין מצוה לפדות את הבת, אין גם מצוה לבת לפדות עצמה. \u0003ומנין שאין אחרים מצווין לפדותה\u0004 את הבת — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כל בכור בניך תפדה\"\u0004 (שמות לד, כ) \u0003בניך ולא בנותיך.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003:\u0004 בכור שלא נפדה, ונולד לו בן בכור, ונמצא כי \u0003הוא\u0004 חייב \u0003לפדות\u0004 את עצמו \u0003ו\u0004חייב גם את \u0003בנו לפדות\u0004 — \u0003הוא קודם לבנו.\u0004 שאם אין בידו כסף מספיק צריך הוא לפדות קודם את עצמו. \u0003ר' יהודה אומר: בנו קודמו.\u0004 ומדוע \u0003שזה,\u0004 האב, \u0003מצותו על אביו\u0004 היתה לפדות אותו, שהמצוה בעיקרה מוטלת על אבי הבן שיפדה אותו, ורק כאשר האב לא עשה זאת חלה המצוה על הבן עצמו. \u0003ו\u0004אילו \u0003זה מצות\u0004 פדיון \u0003בנו עליו\u0004 במפורש, ולכן עליו להקדים במצוה המפורשת לפדות את הבן.","\u0003אמר ר' ירמיה: הכל מודין\u0004"],["\u0003כל היכא דליכא\u0004 \u0005[כל מקום שאין]\u0006 \u0003אלא חמש סלעים\u0004 בידו, וצריך הוא לפדות את עצמו וגם את בנו — \u0003הוא קודם לבנו\u0004 בפדיון. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003מצוה דגופיה עדיפא\u0004 \u0005[של עצמו עדיפה]\u0006 על מצוה שהוא עושה עבור אחרים. \u0003כי פליגי היכא דאיכא\u0004 \u0005[כאשר חלוקים\u0006 הם \u0005במקום שיש]\u0006 לאב קרקעות בשווי \u0003חמש\u0004 סלעים שהם \u0003משועבדים\u0004 בידי אחרים לצורך גביית חוב, \u0003ו\u0004קרקעות בשווי \u0003חמש\u0004 סלעים שהם \u0003בני חורין.\u0004","וזה טעמה של המחלוקת, \u0003ר' יהודה סבר: מלוה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בתורה,\u0004 כלומר, כל התחייבות שהיא מן התורה — \u0003ככתובה בשטר דמיא\u0004 \u0005[היא נחשבת]\u0006 ונגבית מן המשועבדים ככל הלוואה בשטר. ומשום כך \u0003בהני\u0004 \u0005[באותם]\u0006 \u0003חמש\u0004 סלעים שהם בני חורין \u0003פריק לבריה\u0004 \u0005[פודה את בנו],\u0006 \u0003ואזיל כהן וטריף ליה לחמש משועבדים לדידיה\u0004 \u0005[והולך\u0006 ה\u0005כהן וטורף מן הקונים את\u0006 הקרקע בשווי \u0005חמש\u0006 הסלעים ה\u0005משועבדים בשביל\u0006 פדיונו \u0005שלו].\u0006","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מלוה דכתיב באורייתא לאו ככתובה בשטר דמיא\u0004 \u0005[מלוה הכתוב בתורה אינו נחשב ככתוב בשטר]\u0006 לפי שאינו התחייבות מסויימת ומוגדרת על אדם זה \u0003והילכך\u0004 (ומשום כך) \u0003מצוה דגופיה\u0004 \u0005[של גופו,\u0006 של עצמו\u0005]\u0006 \u0003עדיף\u0004 ופודה את עצמו מהבני חורין. ופדיון בנו אינו יכול לפדות מהקרקעות המשועבדים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היה בידו כסף \u0003לפדות את בנו ולעלות לרגל\u0004 — \u0003פודה את בנו ואחר כך עולה לרגל. ר' יהודה אומר: עולה לרגל, ואחר כך פודה את בנו.\u0004 וטעמו של דבר — \u0003שזו,\u0004 העליה לרגל, היא \u0003מצוה עוברת,\u0004 ואם לא יקיימנה עכשיו תתבטל, \u0003וזו,\u0004 פדיון הבן, היא \u0003מצוה שאינה עוברת\u0004 — שיכול לעשותה גם לאחר מכן.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח],\u0006 מובן הדבר \u0003ל\u0004דעת \u0003ר' יהודה, כדקאמר טעמא\u0004 \u0005[כפי שאמר את הטעם]\u0006 והסביר את דבריו, \u0003אלא רבנן מאי טעמייהו\u0004 \u0005[חכמים מה טעמם]\u0006 שאומרים שצריך לפדות את בנו תחילה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כל בכור בניך תפדה\"\u0004 (שמות לד, כ) \u0003והדר\u0004 \u0005[ואחר כך]\u0006 בהמשך נאמר \u0003\"ולא יראו פני ריקם\"\u0004 (שם) בעליה לרגל. משמע שכך הסדר הראוי, שמצוות פדיון קודמת לעליה לרגל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם היו לו חמשה בנים\u0004 בכורים \u0003מחמש נשים\u0004 שונות \u0003שחייב לפדות\u0004 את \u0003כולן\u0004 — \u0003תלמוד לומר \"כל בכור בניך תפדה\",\u0004 שהמלה \"כל\" באה לרבות כל בן בכור שיש לו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הלא \u0003בפטר רחם תלא רחמנא\u0004 \u0005[תלתה התורה]\u0006 את המצוה \"קדש לי כל פטר רחם\" (שמות יג, א), וכיון שכולם הם פטר רחם לאמותיהם חייב לפדותם!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003נילף\u0004 \u0005[נלמד\u0006 בגזירה שווה\u0005]\u0006 \u0003בכור בכור מנחלה, מה להלן\u0004 בדין נחלה הבכור הנזכר שם שמקבל פי שניים הוא דווקא \u0003\"ראשית אנו\"\u0004 (דברים כא, יז), כלומר, בנו הראשון של האב, ואין הדבר תלוי בפטר רחם של האם, \u0003אף כאן\u0004 לענין פדיון תלוי הדבר גם ב\u0003ראשית אונו,\u0004 והראשון שנולד לו יתחייב לפדותו. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ובכור לענין פדיון תלוי רק בהיותו פטר רחם.","על מה ששנינו \u0003ללמדו תורה\u0004 שואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שחייב האב ללמד את בנו תורה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולמדתם אתם את בניכם\"\u0004 (דברים יא, יט). \u0003והיכא דלא אגמריה אבוה\u0004 \u0005[והיכן שלא לימד אותו אביו]\u0006 \u0003מיחייב איהו למיגמר נפשיה\u0004 \u0005[חייב הוא ללמד את עצמו]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 אם נקרא שלא בניקוד המקובל — \u0003\"ולמדתם\".\u0004","ועוד, \u0003איהי מנלן דלא מיחייבא\u0004 \u0005[היא,\u0006 האשה, האם, \u0005מניין שאינה מחוייבת]\u0006 ללמד את בנה — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 הציווי \u0003\"ולימדתם\"\u0004 כדרך שבכתוב, ואפשר לקחת גם \u0003\"ולמדתם\"\u0004 לומר: \u0003כל שמצווה ללמוד\u0004 — \u0003מצווה ללמד, וכל שאינו מצווה ללמוד\u0004 בעצמו תורה — \u0003אינו מצווה ללמד,\u0004 ואשה שאינה מצווה ללמוד, אינה מצווה גם ללמד.","ושואלים: \u0003ואיהי מנלן דלא מיחייבה למילף נפשה\u0004 \u0005[והיא,\u0006 האשה \u0005מניין לנו שאינה מחוייבת ללמד\u0006 את \u0005עצמה]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ולימדתם\"\u0004 ואפשר לקרוא גם \u0003\"ולמדתם\",\u0004 לומר: \u0003כל שאחרים מצווין ללמדו\u0004 — \u0003מצווה ללמד את עצמו, וכל שאין אחרים מצווין ללמדו\u0004 — \u0003אין מצווה ללמד את עצמו. ומנין שאין אחרים מצווין ללמדה\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולמדתם אתם את בניכם\"\u0004 (דברים יא, יט), להדגיש: \u0003את בניכם ולא\u0004 את \u0003בנותיכם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוא\u0004 האב צריך \u0003ללמוד ובנו\u0004 צריך \u0003ללמוד\u0004 ואין בידם כדי זה וזה — \u0003הוא קודם לבנו. ר' יהודה אומר: אם בנו זריז\u0004 (מהיר הבנה) \u0003וממולח\u0004 (חריף) \u0003ותלמודו מתקיים בידו\u0004 (יש לו כושר זכרון) — \u0003בנו קודמו.\u0004 וכך מסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב יעקב בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בר יעקב שדריה אבוה לקמיה\u0004 \u0005[שלח אותו אביו לפני]\u0006 \u0003אביי\u0004 ללמוד. \u0003כי אתא חזייה\u0004 \u0005[כאשר בא\u0006 הבן לביתו \u0005ראה אותו]\u0006 אביו ש\u0003לא הוה מיחדדין שמעתיה\u0004 \u0005[היו שמועותיו מחודדות],\u0006 שלא היה חריף ובקי מספיק. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא עדיפא מינך\u0004 \u0005[אני עדיף ממך]\u0006 ללכת ללמוד, משום כך \u0003תוב את, דאיזיל אנא\u0004 \u0005[שב אתה\u0006 ותטפל בצרכי הבית כדי \u0005שאלך אני\u0006 ללמוד\u0005].\u0006","מסופר, \u0003שמע אביי דקא הוה אתי\u0004 \u0005[שהיה\u0006 רב אחא בר יעקב \u0005בא].\u0006 \u0003הוה ההוא מזיק בי רבנן\u0004 \u0005[היה מזיק אחד,\u0006 שד, ב\u0005בית החכמים\u0006 בית המדרש\u0005]\u0006 של \u0003אביי, דכי הוו עיילי בתרין אפילו ביממא הוו מיתזקי\u0004 \u0005[שכאשר היו נכנסים\u0006 אליו \u0005בשניים\u0006 בזוגות, \u0005אפילו ביום היו ניזקים].\u0006 מה עשה אביי — \u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשי העיר: ש\u0003לא ליתיב ליה אינש אושפיזא\u0004 \u0005[ייתן לו אדם,\u0006 לרב אחא בר יעקב, \u0005אכסניה]\u0006 מקום ללון בו כדי לאלצו ללון בבית המדרש, וכיון שרב אחא בר יעקב צדיק גדול \u0003אפשר דמתרחיש ניסא\u0004 \u0005[שיתרחש נס]\u0006 על ידו ויהרוג את המזיק.","כיון שלא מצא רב אחא בר יעקב מקום ללון \u0003על, בת בההוא בי רבנן\u0004 \u0005[נכנס\u0006 ו\u0005לן באותו בית\u0006 מדרש של ה\u0005חכמים].\u0006 \u0003אידמי ליה כתנינא דשבעה רישוותיה\u0004 \u0005[נדמה לו\u0006 המזיק \u0005כתנין\u0006 בעל \u0005שבעה ראשים].\u0006 פתח רב אחא בר יעקב בתפילה, ועם \u0003כל כריעה\u0004 ש\u0003כרע\u0004 בתפילה \u0003נתר חד רישיה\u0004 \u0005[נפל ראש אחד\u0006 של המזיק\u0005]\u0006 עד שמת. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב אחא בר יעקב \u0003למחר\u0004 לאנשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא איתרחיש ניסא\u0004 \u0005[היה\u0006 \u0003מתרחש נס]\u0004 \u0003סכינתין\u0004 \u0005[הייתם מסכנים אותי\u0006 בכך\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם היה לפניו \u0003ללמוד תורה ולישא אשה\u0004 מה יקדים — \u0003ילמוד תורה ואחר כך ישא אשה. ואם אי אפשר לו בלא אשה\u0004 — \u0003ישא אשה ואחר כך ילמוד תורה. אמר רב יהודה אמר שמואל: הלכה, נושא אשה ואחר כך ילמוד תורה\u0004 בכל מקרה.","\u0003ר' יוחנן אמר:\u0004 כיצד יכול לעשות זאת? \u0003ריחיים\u0004 של עול פרנסה תלויים \u0003בצוארו ויעסוק בתורה?!\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 הלכה למעשה: \u0003הא\u0004 \u0005[זו, דברי שמואל\u0006\u0005]\u0006 — \u0003לן\u0004 \u0005[לנו,\u0006 לבני בבל\u0005],\u0006 \u0003והא\u0004 \u0005[וזו,\u0006 דברי ר' יוחנן\u0005]\u0006 — \u0003להו\u0004 \u0005[להם,\u0006 לבני ארץ ישראל\u0005],\u0006 שבארץ ישראל דחוקים בפרנסתם, ואם נושא אשה — הרי זה עול כבד שאינו מאפשר לו ללמוד.","אגב כך מספרים: \u0003משתבח ליה\u0004 \u0005[היה משתבח בו]\u0006 \u0003רב חסדא לרב הונא ב\u0004שבחיו של \u0003רב המנונא,\u0004 ש\u0003אדם גדול הוא. אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003כשיבא לידך\u0004 (אליך) — \u0003הביאהו לידי\u0004 (שלח אותו אלי). \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רב המנונא לפני רב הונא \u0003חזייה דלא פריס סודרא\u0004 \u0005[ראה אותו שאינו מכסה\u0006 ראשו ב\u0005סודר]\u0006 כדרך תלמידי חכמים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא לא פריסת סודרא\u0004 \u0005[מה טעם אין אתה מכסה\u0006 את ראשך \u0005בסודר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 משום \u0003דלא נסיבנא\u0004 \u0005[שאינני נשוי]\u0006 ולא נהגו שרווקים יתכסו בסודר. \u0003אהדרינהו לאפיה מיניה\u0004 \u0005[הפך\u0006 רב הונא \u0005את פניו ממנו]\u0006 בנזיפה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי דלא חזית להו לאפי\u0004 \u0005[ראה שאין אתה רואה\u0006 את \u0005פני]\u0006 \u0003עד דנסבת\u0004 \u0005[שתתחתן].\u0006","ומעירים: \u0003רב הונא\u0004 הולך בעניין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: בן עשרים שנה ולא נשא אשה\u0004 — הריהו \u0003כל ימיו בעבירה.\u0004 ותוהים: \u0003בעבירה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 וכי אדם כזה כל ימיו עובר עבירות? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שכוונתו היתה: \u0003כל ימיו בהרהור עבירה\u0004 שכיון שלא נשא אשה בצעירותו מתרגל בהרהור עבירה, ואינו יוצא מזה כל ימיו.","\u0003אמר רבא, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: עד\u0004 גיל \u0003עשרים שנה יושב הקדוש ברוך הוא ומצפה לאדם מתי ישא אשה,\u0004 \u0003כיון שהגיע\u0004 גיל \u0003עשרים ולא נשא, אומר: תיפח עצמותיו,\u0004 כלומר, יקולל ואין צורך לדאוג לו עוד.","\u0003אמר רב חסדא: האי דעדיפנא מחבראי\u0004 \u0005[זה שאני מעולה מחברי]\u0006 הטעם \u0003דנסיבנא בשיתסר\u0004 \u0005[שנשאתי\u0006 אשה \u0005ב\u0006גיל \u0005שש עשרה]\u0006 \u0003ואי הוה נסיבנא בארביסר\u0004 \u0005[ואם הייתי נושא ב\u0006גיל \u0005ארבע עשרה]\u0006"],["\u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003לשטן: גירא\u0004 \u0005[חץ]\u0006 \u0003בעיניך\u0004 כלומר, לא הייתי מתיירא כלל מיצר הרע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לר' נתן בר אמי: אדידך\u0004 \u0005[עד שידך]\u0006 \u0003על צוארי דבריך\u0004 \u0005[של בנך],\u0006 כלומר, כל עוד יש לך סמכות ושליטה עליו אתה צריך להשיא לו אשה. ומתי הוא זמן זה — \u0003משיתסר\u0004 \u0005[מ\u0006שנת \u0005שש עשרה]\u0006 \u0003ועד עשרים ותרתי\u0004 \u0005[ושתים]\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003מתמני סרי\u0004 \u0005[משמונה עשרה]\u0006 שנה \u0003עד עשרים וארבעה.\u0004","ומעירים, שחילוקי דעות אלה הם \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 באותו נושא, שבפירוש הפסוק \u0003\"חנך לנער על פי דרכו\"\u0004 (משלי כב, ו) נחלקו \u0003ר' יהודה ור' נחמיה\u0004 אימתי הוא זמן זה; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משיתסר\u0004 \u0005[מ\u0006שנת \u0005שש עשרה]\u0006 \u0003ועד עשרים ותרתין\u0004 \u0005[ושתים],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מתמני סרי\u0004 \u0005[משמונה עשרה]\u0006 \u0003ועד עשרים וארבעה\u0004 והענין אחד הוא, שבעוד שיש לאב השפעה גדולה על בנו צריך לדאוג לו.","כהמשך לחובת האב ללמד את בנו תורה שואלים: \u0003עד היכן חייב אדם ללמד את בנו תורה? אמר רב יהודה אמר שמואל: כגון\u0004 אדם אחד שהיה בימיהם ושמו \u0003זבולון בן דן, שלימדו אבי אביו מקרא ומשנה ותלמוד הלכות ואגדות. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003למדו מקרא\u0004 — \u0003אין מלמדו משנה, ואמר רבא\u0004 בפירוש ברייתא זו: \u0003מקרא\u0004 — \u0003זו תורה\u0004 ולא נביאים וכתובים. ואין עליו חובה ללמד את כל השאר וגם משנה!","ומשיבים, כך יש להבין את דברי שמואל: \u0003כזבולון בן דן, ולא כזבולון בן דן\u0004 לכל דבר. \u0003כזבולון בן דן\u0004 — \u0003שלמדו אבי אביו, ולא כזבולון בן דן\u0004 ש\u0003אילו התם\u0004 \u0005[שם]\u0006 לימד אותו \u0003מקרא משנה ותלמוד הלכות ואגדות, ואילו הכא\u0004 \u0005[כאן]\u0006 הלכה למעשה לכל אדם — חובה ללמדו \u0003מקרא לבד.\u0004","ושואלים: \u0003ואבי אביו מי מיחייב\u0004 \u0005[האם חייב]\u0006 ללמד את בן בנו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ולמדתם אתם את בניכם\"\u0004 (דברים יא, יט) — הרי זה בא לומר: \u0003ולא בני בניכם. ומה אני מקיים\u0004 את הכתוב \u0003\"והודעתם לבניך ולבני בניך\"\u0004 (שם ד, ט) \u0003לומר לך: שכל המלמד את בנו תורה\u0004 — \u0003מעלה עליו הכתוב כאילו למדו לו ולבנו ולבן בנו, עד סוף כל הדורות!\u0004","ומשיבים: \u0003הוא\u0004 ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ולמדתם אתם את בניכם\"\u0004 — \u0003אין לי אלא בניכם, בני בניכם מנין\u0004 שחובה ללמדם? \u0003תלמוד לומר: \"והודעתם לבניך ולבני בניך\". אם כן מה תלמוד לומר \"בניכם\"\u0004 שבא לצמצם — הרי זה בא לומר: \u0003בניכם ולא בנותיכם.\u0004","באותו ענין \u0003אמר ר' יהושע בן לוי: כל המלמד את בן בנו תורה מעלה עליו הכתוב כאילו קבלה מהר סיני, שנאמר \"והודעתם לבניך ולבני בניך\" וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר \u0003\"יום אשר עמדת לפני ה' אלקיך בחרב\"\u0004 (שם י).","\u0003ר' חייא בר אבא אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לר' יהושע בן לוי דשדי דיסנא ארישיה\u0004 \u0005[שהטיל,\u0006 פרש \u0005כיסוי\u0006 זול \u0005על ראשו]\u0006 \u0003וקא ממטי ליה לינוקא לבי כנישתא\u0004 \u0005[והיה מביא את התינוק לבית הכנסת]\u0006 ללמוד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי כולי האי\u0004 \u0005[מה כל זה]\u0006 שאתה ממהר עד כדי כך, שאין לך זמן להתלבש כראוי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי זוטר מאי דכתיב\u0004 \u0005[האם\u0006 דבר \u0005קטן\u0006 ולא חשוב הוא \u0005מה שנאמר]\u0006 \u0003\"והודעתם לבניך\" וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 מיד בהמשך הדברים \u0003\"יום אשר עמדת לפני ה' אלקיך בחרב\"? מכאן ואילך,\u0004 לאחר ששמע דברים אלה, \u0003ר' חייא בר אבא לא טעים אומצא\u0004 \u0005[היה טועם אומצה,\u0006 בשר\u0005]\u0006 \u0003עד דמקרי לינוקא ומוספיה\u0004 \u0005[עד שהיה מקרא לתינוק ומוסיף לו]\u0006 על מה שלמד אתמול. \u0003רבה בר רב הונא לא טעים אומצא\u0004 \u0005[טועם בשר]\u0006 \u0003עד דמייתי לינוקא לבית מדרשא\u0004 \u0005[שהיה מביא את התינוק לבית המדרש].\u0006","\u0003אמר רב ספרא משום\u0004 (בשם) \u0003ר' יהושע בן חנניא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ושננתם לבניך\"\u0004 (שם ו, ז) בכפל הנו\"ן, \u0003אל תקרי\u0004 \u0005[תקרא,\u0006 תבין\u0005]\u0006 \u0003\"ושננתם\"\u0004 במובן של הכפלה, פעם שניה, שחוזר ושונה, \u0003אלא \"ושלשתם\"\u0004 ששונה וחוזר ושונה ונמצא שיש בלימוד שלשה חלקים.","ומכאן אמרו: \u0003לעולם ישלש אדם שנותיו,\u0004 שיחלקם: \u0003שליש במקרא, שליש במשנה שליש בתלמוד.\u0004 ושואלים: איך יכול אדם לחלק כך את שנותיו, שכן \u0003מי\u0004 \u0005[האם]\u0006 הוא \u0003יודע כמה חיי\u0004 \u0005[\u0006משך ה\u0005חיים]\u0006 שיידע מהו שליש חייו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 דרשה זו אלא \u0003ליומי\u0004 \u0005[לימים]\u0006 שכך יחלק כל יום מימות חייו.","\u0003לפיכך\u0004 כיון שהיו מקדישים זמן רב כל כך למקרא \u0003נקראו\u0004 חכמים \u0003ראשונים \"סופרים\"\u0004 — מפני \u0003שהיו סופרים כל האותיות שבתורה, שהיו אומרים: וא\"ו\u0004 של המלה \u0003\"גחון\"\u0004 (ויקרא יא, מב) — \u0003חציין של אותיות של ספר תורה.\u0004 המילים \u0003\"דרש דרש\"\u0004 (שם י, טז) — \u0003חציין של תיבות\u0004 (המלים) שבספר התורה, הפסוק המתחיל במלה \u0003\"והתגלח\"\u0004 (שם יג, לג) הוא חציים \u0003של\u0004 ה\u0003פסוקים.\u0004 וכן \u0003\"יכרסמנה חזיר מיער\"\u0004 (תהלים פ, יד) ה\u0003עי\"ן\u0004 שבמלה \u0003\"יער\"\u0004 — \u0003חציין של תהלים\u0004 במנין האותיות. הפסוק \u0003\"והוא רחום יכפר עון\"\u0004 (שם עח, לח) הוא \u0003חציו\u0004 ב\u0003פסוקים\u0004 של ספר תהלים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: וא\"ו\u0004 של המלה \u0003\"גחון\", מהאי גיסא או מהאי גיסא\u0004 \u0005[מצד זה או מצד זה]?\u0006 כלומר, האם הוא שייך לחצי הראשון או השני של התורה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ניתי\u0004 \u0005[נביא]\u0006 \u0003ספר תורה ואימנינהו\u0004 \u0005[ונמנה אותן,\u0006 את האותיות\u0005]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רבה בר בר חנה\u0004 בענין אחר: \u0003לא זזו משם עד שהביאו\u0004 \u0003ספר תורה ומנאום,\u0004 ואם כן יכולים גם אנו לעשות כן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אינהו בקיאי\u0004 \u0005[הם\u0006 היו \u0005בקיאים]\u0006 \u0003ב\u0004כתיבן של כל המילים שהן \u0003חסירות ויתרות\u0004 ולכן יכלו לדייק במנין האותיות, \u0003אנן לא בקיאינן\u0004 \u0005[אנחנו איננו בקיאים]\u0006 בכך ולכן גם אם נמנה לא נוכל להגיע למסקנה ברורה.","וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: \"והתגלח\"\u0004 שאמרנו שהוא חצי הפסוקים, \u0003מהאי גיסא או מהאי גיסא\u0004 \u0005[מצד זה או מצד זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: פסוקי מיהא ליתו לימנויי\u0004 \u0005[\u0006את \u0005הפסוקים על כל פנים נביא ונמנה]\u0006 שהרי בזה אין ספיקות! ומשיבים: \u0003בפסוקי נמי לא בקיאינן\u0004 \u0005[בפסוקים גם כן אין אנו בקיאים]\u0006 וראיה לכך \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב אחא בר אדא\u0004 מארץ ישראל לבבל, \u0003אמר: במערבא פסקי ליה להאי קרא לתלתא פסוקי\u0004 \u0005[בארץ ישראל מחלקים פסוק זה לשלושה פסוקים]\u0006 והוא הפסוק \u0003\"ויאמר ה' אל משה הנה אנכי בא אליך בעב הענן\"\u0004 (שמות יט, ט). ושמא יש עוד פסוקים שאין אנו יודעים לפסקם כראוי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חמשת אלפים ושמונה מאות ושמונים ושמונה פסוקים הוו\u0004 \u0005[הם]\u0006 \u0003פסוקי ספר תורה, יתר עליו תהלים שמונה\u0004 פסוקים, \u0003חסר ממנו\u0004 ספר \u0003דברי הימים שמונה\u0004 פסוקים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ושננתם\"\u0004 יש לפרשו גם במשמעות שנון, חד, כלומר, \u0003שיהו דברי תורה מחודדים\u0004 וברורים \u0003בפיך, שאם ישאל לך אדם דבר אל תגמגם\u0004 מתוך הספק \u0003ותאמר לו\u0004 את הדבר באופן מסופק, \u0003אלא אמור לו מיד, שנאמר:\u0004"],["\u0003\"אמר לחכמה אחתי את\u0004 ומודע לבינה תקרא\" (משלי ז, ד) כלומר, שהוא בקי בה כמו שהוא מכיר את אחותו. \u0003ואומר: \"קשרם על אצבעתיך כתבם על לוח לבך\"\u0004 (שם ג), \u0003ואומר: \"כחצים ביד גבור כן בני הנעורים\"\u0004 (תהלים קכז, ד), \u0003ואומר: \"חצי גבור שנונים\"\u0004 (שם קכ, ד), \u0003ואומר: \"חציך שנונים עמים תחתיך יפלו\"\u0004 (שם מה, ו), \u0003ואומר: \"אשרי הגבר אשר מלא את אשפתו מהם לא יבשו כי ידברו את אויבים\u0004 \u0003בשער\"\u0004 (שם קכז, ה) ומכל אלו הפסוקים משמע שהבנים נמשלו לחיצים שנונים.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"את אויבים בשער\"\u0004 לענין זה? \u0003אמר ר' חייא בר אבא: אפילו האב ובנו, הרב ותלמידו שעוסקין\u0004 יחד \u0003בתורה בשער,\u0004 בענין, \u0003אחד\u0004 — \u0003נעשים אויבים זה את זה\u0004 מתוך להט הלימוד. \u0003ו\u0004אולם \u0003אינם זזים משם עד שנעשים אוהבים זה את זה, שנאמר: \"\u0004על כן יאמר בספר מלחמות ה' \u0003את והב בסופה\"\u0004 (במדבר כא, יד) שמפרש \"והב\" מלשון אהבה, \u0003אל תקרי\u0004 (תקרא) \u0003\"בסופה\" אלא \"בסופה\",\u0004 בסופו של הויכוח הם מגיעים לאהבה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר לגבי דברי תורה \u0003\"ושמתם\u0004 את דברי אלה על לבבכם\u0003\"\u0004 (דברים יא, יח) ומפרשים זאת כאילו היה כתוב \u0003סם תם\u0004 (סם שלם) תרופה גמורה, לומר כי \u0003נמשלה תורה כסם חיים. משל לאדם שהכה את בנו מכה גדולה והניח לו רטיה\u0004 (תחבושת) \u0003על מכתו, ואמר לו: בני, כל זמן שהרטיה זו על מכתך\u0004 ומרפאה אותך \u0003אכול מה שהנאתך\u0004 ממנו, \u0003ושתה מה שהנאתך\u0004 ממנו, \u0003ורחוץ בין בחמין בין בצונן ואין אתה מתיירא,\u0004 כי היא מרפאה את מכתך. \u0003ואם אתה מעבירה\u0004 (מורידה) ממך \u0003הרי היא\u0004 המכה \u0003מעלה נומי\u0004 (נמק).","\u0003כך הקדוש ברוך הוא אמר להם לישראל: בני, בראתי יצר הרע\u0004 שהוא המכה הגדולה \u0003ובראתי לו תורה תבלין\u0004 לתקנו ולמתקו. \u0003ואם אתם עוסקים בתורה\u0004 — \u0003אין אתם נמסרים בידו\u0004 של היצר הרע, \u0003שנאמר: \"הלוא אם תיטיב שאת\"\u0004 (בראשית ד, ז) — שאם אדם מיטיב דרכו ועוסק בתורה הוא מתרומם מעל היצר הרע,","\u0003ואם אין אתם עוסקין בתורה\u0004 — \u0003אתם נמסרים בידו, שנאמר: \"לפתח חטאת רבץ\"\u0004 (שם), \u0003ולא עוד אלא שכל משאו ומתנו\u0004 מה שעוסק בו היצר הרע הוא רק \u0003בך, שנאמר: \"ואליך תשוקתו\"\u0004 (שם). \u0003ואם אתה רוצה אתה מושל בו, שנאמר: \"ואתה תמשל בו\"\u0004 (שם).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קשה יצר הרע, שאפילו יוצרו קראו רע, שנאמר: \"כי יצר לב האדם רע מנעריו\"\u0004 (שם ח, כא). \u0003אמר רב יצחק: יצרו של אדם מתחדש עליו בכל יום, שנאמר: \"\u0004וכל יצר מחשבות לבו \u0003רק רע כל היום\"\u0004 (שם ו, ה).","\u0003ואמר ר' שמעון בן לוי: יצרו של אדם מתגבר עליו בכל יום ומבקש\u0004 ל\u0003המיתו, שנאמר: \"צופה רשע לצדיק ומבקש להמיתו\"\u0004 (תהלים לז, לב) \u0003ואלמלא הקדוש ברוך הוא עוזרו\u0004 לאדם להתגבר על יצרו \u0003אין יכול לו, שנאמר: \"אלהים לא יעזבנו בידו\"\u0004 (שם לג).","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בני, אם פגע בך מנוול זה\u0004 היצר הרע — \u0003משכהו לבית המדרש,\u0004 כלומר, לך לבית המדרש. ושם, \u0003אם אבן הוא\u0004 — הרי הוא \u0003נימוח, ואם ברזל הוא\u0004 — \u0003מתפוצץ, שנאמר\u0004 לענין דברי תורה: \u0003\"הלוא כה דברי כאש נאם ה' וכפטיש יפצץ סלע\"\u0004 (ירמיה כג, כט), כלומר, כמו שהסלע מפוצץ את הפטיש, כך בלימוד תורה יכול להתגבר על היצר הרע הקשה כברזל. ולענין אבן, ש\u0003אם אבן הוא — נימוח\u0004 (נשחק), \u0003שנאמר\u0004 לגבי התורה: \u0003\"הוי כל צמא לכו למים\"\u0004 (ישעיה נה, א) \u0003ואומר: \"אבנים שחקו מים\"\u0004 (איוב יד, יט), כלומר, שכוח המים יפה מכוח האבן שהריהי נשחקת על ידי המים.","אמרנו שמצווה האב על בנו \u0003להשיאו אשה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 הדבר? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קחו נשים והולידו בנים ובנות וקחו לבניכם נשים ואת בנותיכם תנו לאנשים\"\u0004 (ירמיה כט, ו).","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בנו\u0004 — \u0003בידו,\u0004 ויכול לומר לו שישא אשה, \u0003אלא בתו\u0004 וכי \u0003בידו היא?\u0004 הלא הדבר תלוי באנשים אח רים, אם ירצו לשאתה! ומשיבים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 ירמיה: \u0003ניתן\u0004 \u0005[שייתן]\u0006 \u0003לה\u0004 האב \u0003מידי ולבשייה ונכסייה\u0004 \u0005[דבר\u0006 בנדוניה \u0005וילבישנה ויכסנה]\u0006 \u0003כי היכי דקפצו עלה אינשי\u0004 \u0005[כדי שיקפצו\u0006 ימהרו \u0005עליה אנשים\u0006 לשאתה\u0005].\u0006","עוד אמרנו שמצווה האב על בנו \u0003ללמדו אומנות.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 הדבר? \u0003אמר חזקיה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ראה חיים עם אשה אשר אהבת\"\u0004 (קהלת ט, ט) ומפרש: \u0003אם\u0004 משמעות הכתוב הזה \u0003\"אשה\" ממש היא,\u0004 יש לומר כך: \u0003כשם שחייב להשיאו אשה\u0004 — \u0003כך חייב ללמדו אומנות\u0004 (\"חיים\"). ו\u0003אם\u0004 \"אשה\" שבכתוב זה היא בדרך משל, ומשמעותה \u0003תורה היא\u0004 — יש ללמוד כך: \u0003כשם שחייב ללמדו תורה\u0004 — \u0003כך חייב ללמדו אומנות.\u0004","עוד שנינו ש\u0003יש אומרים\u0004 שצריך האב \u0003אף להשיטו בנהר\u0004 (ללמדו לשחות). ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של דבר — \u0003חיותיה\u0004 \u0005[\u0006צורך \u0005חייו]\u0006 \u0003הוא\u0004 שאם יפול למים לא יטבע.","\u0003ר' יהודה אומר: כל שאינו מלמדו אומנות\u0004 — \u0003מלמדו ליסטות.\u0004 תוהים: \u0003ליסטות סלקא דעתך\u0004 \u0005[עולה על דעתך],\u0006 הלא ודאי אין מלמדו ליסטות! \u0003אלא, כאילו מלמדו ליסטות.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין חכמים האומרים שמצוה ללמדו אומנות ובין דברי ר' יהודה? ומשיבים: \u0003איכא בינייהו דאגמריה עיסקא\u0004 \u0005[יש ביניהם\u0006 הבדל כגון \u0005שלימדו\u0006 האב \u0005עיסוק\u0006 במסחר\u0005],\u0006 שלדעת תנא קמא די בכך, ולדעת ר' יהודה צריך ללמדו אומנות ממש.","שנינו במשנה שב\u0003כל מצות האב על הבן\u0004 נשים חייבות. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כל מצות האב על הבן? אילימא כל מצותא דמיחייב אבא למיעבד לבריה\u0004 \u0005[אם תאמר כל המצוות שמחוייב האב לעשות לבנו]\u0006 \u0003נשים חייבות\u0004 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האב חייב בבנו למולו ולפדותו.\u0004 ומכאן נדייק: \u0003אביו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב בכך, \u0003אמו\u0004 — \u0003לא!\u0004","\u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל מצות האב המוטלת על הבן לעשות לאביו, אחד אנשים ואחד נשים חייבין.\u0004 ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 איפוא במשנה \u0005לזו ששנו חכמים\u0006 בברייתא\u0005],\u0006 על מה שנאמר: \"איש אמו ואביו תיראו\" (ויקרא יט, ג). \u0003\"איש\"\u0004 — \u0003אין לי אלא איש,\u0004 גבר, בלבד, \u0003אשה מנין\u0004 שאף היא חייבת בכבוד הוריה? \u0003כשהוא אומר \"תיראו\"\u0004 — \u0003הרי כאן שנים,\u0004 איש ואשה.","\u0003אם כן\u0004 ששניהם חייבים \u0003מה תלמוד לומר\u0004 מדוע נאמר במקרא דווקא \u0003\"איש\"?\u0004 — מכיון ש\u0003איש סיפק\u0004 (אפשר) \u0003בידו לעשות\u0004 לכבוד הוריו, \u0003אשה אין\u0004 תמיד \u0003סיפק בידה לעשות, מפני שרשות אחרים\u0004 (בעלה) \u0003עליה.\u0004 שעסוקה בביתה ואינה יכולה תמיד לעסוק בכבוד הוריה. \u0003אמר רב אידי בר אבין אמר רב:\u0004 משום כך, אם \u0003נתגרשה\u0004 אשה מבעלה, \u0003שניהם\u0004 גם הבת וגם הבן \u0003שוים\u0004 לענין כיבוד אב ואם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נאמר \"כבד את אביך ואת אמך\"\u0004 (שמות כ, יב) \u0003ונאמר \"כבד את ה' מהונך\"\u0004 (משלי ג, ט), \u0003השוה\u0004 איפוא \u0003הכתוב כבוד אב ואם לכבוד המקום,\u0004 שבשניהם אמר לשון כבוד.","וכן \u0003נאמר: \"איש אמו ואביו תיראו\"\u0004 (ויקרא יט, ג) \u0003ונאמר: \"את ה' אלהיך תירא ואתו תעבד\"\u0004 (דברים ו, יג) \u0003השוה הכתוב מוראת אב ואם למוראת המקום,\u0004 וכן","\u0003נאמר:\u0004 \"ו \u0003מקלל אביו ואמו מות יומת\"\u0004 (שמות כא, יז), \u0003ונאמר: \"איש איש כי יקלל אלהיו ונשא חטאו\"\u0004 (ויקרא כד, טו) נמצא ש\u0003השוה הכתוב ברכת\u0004 (כלומר, קללה, בלשון נקיה) \u0003אב ואם לברכת המקום. אבל בהכאה\u0004 שנאמר שהמכה את אביו ואמו חייב מיתה \u0003ודאי אי אפשר\u0004 לומר כן כלפי \u0003הקדוש ברוך הוא.\u0004","\u0003וכן בדין,\u0004 כלומר, סברה היא שתהיה השוואה כזו, כיון \u0003ששלשתן שותפין בו\u0004 ביצירתו. וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה שותפין הן באדם: הקדוש ברוך הוא\u0004 שנותן בו נשמה, \u0003ואביו ואמו. בזמן שאדם מכבד את אביו ואת אמו אמר הקדוש ברוך הוא: מעלה\u0004 (מחשיב) \u0003אני עליהם כאילו דרתי ביניהם, וכבדוני\u0004 גם אותי.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003רבי אומר: גלוי וידוע לפני מי שאמר והיה העלם שבן מכבד את אמו יותר מ\u0004מה שהוא מכבד את \u0003אביו, מפני\u0004"],["\u0003שמשדלתו\u0004 (מפתה אותו) \u0003בדברים\u0004 רבים ולא בגערות וביד קשה, \u0003לפיכך הקדים הקדוש ברוך הוא\u0004 בציווי \"כבד את אביך ואת אמך\" (שמות כ, יב) \u0003כיבוד אב לכיבוד אם\u0004 — כדי להזהיר על דבר שאינו כל כך טבעי. \u0003ו\u0004כן \u0003גלוי וידוע לפני מי שאמר והיה העולם שהבן מתיירא מאביו יותר מאמו, מפני שמלמדו תורה\u0004 ואגב כך הוא מענישו — \u0003לפיכך הקדים הקדוש ברוך הוא\u0004 בפסוק \"איש אמו ואביו תיראו\" (ויקרא יט, ג) \u0003מורא האם למורא האב.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003בזמן שאדם מצער את אביו ואת אמו אמר הקדוש ברוך הוא: יפה עשיתי שלא דרתי ביניהם, שאלמלי\u0004 (שאילו) \u0003דרתי ביניהם, ציערוני\u0004 גם אותי. \u0003אמר ר' יצחק: כל העובר עבירה בסתר\u0004 — \u0003כאילו דוחק רגלי שכינה,\u0004 שכביכול מסלק את הקדוש ברוך הוא ממקומו. \u0003שנאמר: \"כה אמר ה' השמים כסאי והארץ הדם רגלי\"\u0004 (ישעיה סו, א), והעושה עבירה בסתר, הרי הוא כמעיד בעצמו שאינו חושב שהקדוש ברוך הוא נמצא באותו מקום, והוא איפוא כביכול דוחק רגליו מן הארץ.","ובאותו ענין \u0003אמר ר' יהושע בן לוי: אסור לאדם שיהלך ארבע אמות בקומה זקופה, שנאמר: \"מלא כל הארץ כבודו\"\u0004 (שם ו, ג), ומפני כבוד המקום צריך לנהוג בענווה ובשפלות קומה. ומסופר: \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לא מסגי\u0004 \u0005[היה מהלך]\u0006 \u0003ארבע אמות בגילוי הראש. אמר\u0004 בלבו: \u0003שכינה למעלה מראשי,\u0004 וצריך אני לנהוג בכבוד.","וביחס לכיבוד אב ואם מסופר: \u0003שאל בן אלמנה אחת את ר' אליעזר:\u0004 אם \u0003אבא אומר\u0004 לי \u0003\"השקיני מים\" ו\u0004גם \u0003אימא אומרת\u0004 לי \u0003\"השקיני מים\", איזה מהם קודם,\u0004 את מי אני צריך לכבד תחילה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנח כבוד אמך ועשה כבוד אביך,\u0004 לפי \u0003שאתה ואמך חייבים בכבוד אביך. בא לפני ר' יהושע\u0004 ושאל אותו אותה שאלה, \u0003אמר לו\u0004 ר' יהושע \u0003כך\u0004 כפי שענה לו ר' אליעזר.","\u0003אמר לו: רבי,\u0004 ואם \u0003נתגרשה\u0004 אמי \u0003מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מבין ריסי עיניך\u0004 שרואים שהן דומעות \u0003ניכר שבן אלמנה אתה\u0004 ואין לך כלל אב, ואם כן למה אתה שואל את השאלה כאילו היתה זו עבורך הלכה למעשה? ומתוך כך ענה לו על שאלתו בבדיחות הדעת: \u0003הטל להן מים בספל וקעקע\u0004 (השמע קול) \u0003להן כ\u0004דרך שעושים ל\u0003תרנגולין\u0004 שיבואו. כלומר, כיון שנתגרשה אמו כבוד שניהם שווה ואין לו להקדים אחד מהם.","\u0003דרש עולא רבה\u0004 \u0005[הגדול]\u0006 \u0003אפיתחא דבי נשיאה\u0004 \u0005[על פתחו של בית הנשיא]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"יודוך ה' כל מלכי ארץ כי שמעו אמרי פיך\"\u0004 (תהלים קלח, ד), \u0003מאמר פיך\u0004 בלשון יחיד \u0003לא נאמר, אלא \"אמרי פיך\",\u0004 בלשון רבים, מה הם \"אמרי פיך\"? — \u0003בשעה שאמר הקדוש ברוך הוא \"אנכי\" ו\"לא יהיה לך\"\u0004 (שמות כ, ב–ג) \u0003אמרו אומות העולם: לכבוד עצמו הוא דורש,\u0004 שהרי שני דיברות אלה מדברות בכבוד ה'.","\u0003כיון שאמר \"כבד את אביך ואת אמך\"\u0004 (שם יב) \u0003חזרו והודו\u0004 (\"יודוך ה'\") \u0003למאמרות הראשונות\u0004 שכולן אמת ולכן נאמר \"אמרי פיך\". \u0003רבא אמר: מהכא\u0004 \u0005[מכאן]\u0006 מובן יותר מה שנאמר \u0003\"ראש דברך אמת\"\u0004 (תהלים קיט, קס) — וכי \u0003ראש דברך\u0004 אמת \u0003ולא סוף דברך? אלא מסוף דברך ניכר\u0004 לכל \u0003שראש דברך אמת.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב עולא: עד היכן\u0004 מגיעה מצות \u0003כיבוד אב ואם? אמר להם: צאו וראו מה עשה גוי אחד באשקלון, ודמא בן נתינה שמו. פעם אחת בקשו חכמים\u0004 לקנות ממנו \u0003פרקמטיא\u0004 (סחורה) \u0003בששים ריבוא\u0004 דינרי זהב \u0003שכר\u0004 (רווח), \u0003והיה מפתח\u0004 של מקום הסחורה \u0003מונח תחת מראשותיו של אביו\u0004 שישן באותה שעה, \u0003ולא ציערו\u0004 להעירו משנתו למרות שאבד בכך רווח גדול.","\u0003אמר רב יהודה אמר שמואל: שאלו את ר' אליעזר: עד היכן כיבוד אב ואם? אמר להם: צאו וראו מה עשה גוי אחד לאביו באשקלון, ודמא בן נתינה שמו\u0004 של הבן. פעם אחת \u0003בקשו\u0004 לקנות \u0003ממנו חכמים אבנים\u0004 יקרות \u0003לאפוד\u0004 שבבגדי הכהן הגדול \u0003בששים ריבוא שכר, ורב כהנא מתני\u0004 \u0005[היה שונה]\u0006 שהיה מדובר \u0003בשמונים ריבוא\u0004 רווח, \u0003והיה מפתח\u0004 של קופתו \u0003מונח תחת מראשותיו של אביו, ולא ציערו\u0004 להעירו משנתו והפסיד משום כך את רווח העיסקה.","\u0003לשנה האחרת נתן הקדוש ברוך הוא שכרו שנולדה לו פרה אדמה בעדרו,\u0004 והיו ישראל זקוקים לה. \u0003נכנסו חכמי ישראל אצלו, אמר להם: יודע אני בכם שאם אני מבקש מכם כל ממון שבעולם\u0004 תמורת אותה פרה ש\u0003אתם נותנין לי, אלא אין אני מבקש מכם אלא אותו ממון שהפסדתי בשביל כבוד אבא.\u0004","\u0003ואמר ר' חנינא: ומה\u0004 (והרי) \u0003מי שאינו מצווה\u0004 על כך מן התורה, שהרי הוא גוי, \u0003ועושה\u0004 — \u0003כך\u0004 גדול שכרו, מי שהוא \u0003מצווה ועושה\u0004 — \u0003על אחת כמה וכמה.\u0004 ש\u0003אמר ר' חנינא: גדול\u0004 מי ש\u0003מצווה ועושה ממי שאינו מצווה ועושה.\u0004","\u0003אמר רב יוסף\u0004 שהיה סומא: \u0003מריש הוה אמינא\u0004 \u0005[מראש,\u0006 מתחילה, \u0005הייתי אומר]:\u0006 \u0003מאן דהוה אמר\u0004 \u0005[מי שיהא אומר]\u0006 \u0003לי\u0004 כי \u0003הלכה כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: סומא פטור מן המצות\u0004 — \u0003עבידנא יומא טבא לרבנן\u0004 \u0005[עושה אני יום טוב,\u0006 סעודה \u0005לחכמים],\u0006 \u0003דהא לא מיפקידנא והא עבידנא\u0004 \u0005[שהרי אינני מצווה ואני עושה\u0006 את המצוות\u0005]\u0006 וגדול שכרי. \u0003השתא דשמעיתא להא\u0004 \u0005[עכשיו ששמעתי את זו]\u0006 ש\u0003אמר ר' חנינא: גדול מצווה ועושה יותר ממי שאינו מצווה ועושה,\u0004 אם כן \u0003אדרבה\u0004 (להיפך): \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לי\u0004 ש\u0003אין הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 וסומא אכן חייב במצוות אז \u0003עבידנא יומא טבא לרבנן\u0004 \u0005[עושה אני יום טוב לחכמים],\u0006 שהרי גדול מי שמצווה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: פעם אחת היה\u0004 אותו דמא בן נתינא \u0003לבוש סירקון\u0004 (בגד מפואר) \u0003של זהב, והיה יושב בין גדולי רומי. ובאתה אמו וקרעתו\u0004 את הבגד \u0003ממנו, וטפחה לו על ראשו, וירקה לו בפניו, ולא הכלימה\u0004 (בייש אותה).","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו: יש מאכיל לאביו פסיוני ו\u0004מעשהו זה \u0003טורדו\u0004 (מוציאו) \u0003מן העולם\u0004 הבא, \u0003ויש מטחינו\u0004 (גורם לו לטחון) \u0003בריחים\u0004 שהיא עבודה קשה ביותר,"],["\u0003ו\u0004עם כל זה הריהו \u0003מביאו\u0004 בכך \u0003לחיי העולם הבא.\u0004","\u0003אמר ר' אבהו: כגון אבימי ברי\u0004 \u0005[בני]\u0006 \u0003קיים מצות כיבוד\u0004 כראוי. ומספרים: \u0003חמשה בני סמכי הוה ליה\u0004 \u0005[בנים סמוכים\u0006 להוראה \u0005היו לו]\u0006 \u0003לאבימי בחיי אביו\u0004 ר' אבהו, והוא עצמו היה איפוא כבר אדם מבוגר ואדם סמוך, \u0003וכי הוה אתא\u0004 \u0005[וכאשר היה בא]\u0006 \u0003ר' אבהו\u0004 אביו, \u0003קרי אבבא\u0004 \u0005[\u0006ו\u0005קורא בפתח]\u0006 שרוצה להכנס, \u0003רהיט ואזיל ופתח ליה\u0004 \u0005[היה\u0006 אבימי עצמו \u0005רץ והולך ופותח לו]\u0006 \u0003ואמר\u0004 \u0005[והיה אומר]\u0006 בינתיים: \u0003אין, אין, עד דמטאי התם\u0004 \u0005[כן, כן, עד שאגיע לשם,\u0006 לפתח\u0005],\u0006 כדי שלא יחשוב אביו אף לרגע שאין משגיחים בו.","\u0003יומא חד\u0004 \u0005[יום אחד]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו לאבימי בנו: \u0003אשקיין מיא\u0004 \u0005[השקה אותי מים].\u0006 \u0003אדאייתי ליה\u0004 \u0005[עד שהביא לו]\u0006 את המים \u0003נמנם\u0004 בינתיים ר' אבהו. \u0003גחין קאי עליה\u0004 \u0005[\u0006היה אבימי \u0005גוחן,\u0006 ו\u0005עומד עליו]\u0006 \u0003עד דאיתער\u0004 \u0005[שנתעורר\u0006 אביו\u0005].\u0006 \u0003איסתייעא מילתיה\u0004 \u0005[הסתייע\u0006 לו \u0005הדבר]\u0006 \u0003ו\u0004בזכות מצוה זו \u0003דרש אבימי\u0004 באותה שעה את \u0003\"מזמור לאסף\"\u0004 (תהלים עט).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יעקב בר אבוה לאביי: כגון אנא\u0004 \u0005[אני]\u0006 שאני חביב ביותר על הורי, ש\u0003עד דאתינא מבי\u0004 \u0005[שאני מגיע מבית]\u0006 ה\u0003רב אבא מדלי\u0004 \u0005[אבי מביא]\u0006 \u0003לי כסא\u0004 \u0005[כוס]\u0006 \u0003ואמא מזגה\u0004 \u0005[ואמי מוזגת]\u0006 \u0003לי\u0004 \u0005לי],\u0006 \u0003היכי איעביד\u0004 \u0005[איך אעשה]?\u0006 אם אקבל מהם, האם יש בכך משום חסרון כבוד להם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאמך קביל\u0004 \u0005[קבל]\u0006 את הכיבוד הזה, \u0003ומאבוך\u0004 \u0005[ומאביך]\u0006 \u0003לא תקבל\u0004 ש\u0003כיון דבר\u0004 \u0005[שבן]\u0006 \u0003תורה הוא חלשה דעתיה\u0004 \u0005[תחלש דעתו]\u0006 אם יראה שאין אתה מתייחס אליו בכבוד הראוי.","מסופר: \u0003ר' טרפון הוה ליה ההיא אמא\u0004 \u0005[היתה לו אם]\u0006 \u0003דכל אימת דהות בעיא למיסק לפוריא\u0004 \u0005[שכל פעם שהיתה רוצה לעלות למיטה]\u0006 \u0003גחין וסליק לה\u0004 \u0005[היה מתכופף ו\u0006היתה \u0005עולה עליו],\u0006 \u0003וכל אימת דהות נחית, נחתת עלויה\u0004 \u0005[וכל פעם שהיתה יורדת\u0006 מן המיטה. \u0005היתה יורדת עליו].\u0006 \u0003אתא וקא משתבח בי מדרשא\u0004 \u0005[בא והשתבח\u0006 ב\u0005בית המדרש]\u0006 שהוא מקיים מצות כיבוד הורים בשלימות. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003עדיין לא הגעת לחצי כיבוד. כלום זרקה ארנקי\u0004 (ארנק) של כסף \u0003בפניך לים ולא הכלמתה\u0004 על כך?","\u0003רב יוסף כי הוה שמע קל כרעא דאמיה\u0004 \u0005[כאשר היה שומע\u0006 את \u0005קול רגלי אמו]\u0006 כשהולכת, \u0003אמר: איקום מקמי שכינה דאתיא\u0004 \u0005[אקום מפני\u0006 ה\u0005שכינה שבאה].\u0006 \u0003אמר ר' יוחנן: אשרי מי ש\u0004מעולם \u0003לא חמאן\u0004 \u0005[ראה אותם]\u0006 את אביו ואמו, מפני שקשה מאד לכבדם כראוי. מספרים ש\u0003ר' יוחנן\u0004 עצמו לא ראה את הוריו מעולם, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003עברתו אמו\u0004 — \u0003מת אביו,\u0004 כאשר \u0003ילדתו\u0004 — \u0003מתה אמו. וכן\u0004 היה ל\u0003אביי.\u0004 ותוהים: \u0003איני\u0004 \u0005[כך הוא]\u0006 שאביי לא ראה את אמו? \u0003והאמר\u0004 \u0005[והרי היה אומר]\u0006 \u0003אביי\u0004 פעמים רבות את המשפט: \u0003אמרה לי אם!\u0004 ומשיבים: \u0003ההיא מרבינתיה הואי\u0004 \u0005[אותה\u0006 \"אם\" \u0005אומנתו היתה]\u0006 ולא אמו.","\u0003רב אסי הוה ליה ההיא\u0004 \u0005[היתה לו אותה]\u0006 \u0003אמא זקינה. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003בעינא\u0004 \u0005[רוצה אני]\u0006 \u0003תכשיטין. עבד\u0004 \u0005[עשה]\u0006 \u0003לה.\u0004 אמרה לו: \u0003בעינא גברא\u0004 \u0005[רוצה אני איש]\u0006 להינשא לו, אמר לה: \u0003נייעין\u0004 \u0005[אחפש]\u0006 \u0003לך.\u0004 אמרה לו: \u0003בעינא גברא דשפיר כותך\u0004 \u0005[רוצה אני איש ש\u0006יהיה \u0005יפה כמותך]\u0006 ואז ראה שדעתה מבולבלת ולא יוכל לספק כל רצונותיה, \u0003שבקה ואזל לארעא דישראל\u0004 \u0005[עזבה והלך לארץ ישראל].\u0006","\u0003שמע דקא אזלה אבתריה\u0004 \u0005[שמע ש\u0006היא \u0005הולכת אחריו]\u0006 ועולה גם היא לארץ ישראל. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו לצאת מארץ\u0004 ישראל \u0003לחוצה לארץ\u0004 כדי לקבל את פניה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור.\u0004 שאל: לצאת \u0003לקראת אמא מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איני יודע.\u0004 \u0003אתרח פורתא\u0004 \u0005[המתין\u0006 רב אסי \u0005מעט],\u0006 \u0003הדר אתא\u0004 \u0005[חזר ובא\u0006 אליו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אסי, נתרצית\u0004 (החלטת שברצונך) \u0003לצאת\u0004 — \u0003המקום יחזירך לשלום,\u0004 ולא אמר יותר.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב אסי \u0005לפני]\u0006 \u0003ר' אלעזר\u0004 לפי שלא ידע רב אסי כיצד לפרש את משמעות דברי ר' יוחנן אלה. ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חס ושלום, דלמא מירתח רתח\u0004 \u0005[שמא\u0006 הוא \u0005כועס עלי]\u0006 על שרציתי לצאת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר לך\u0004 בדיוק? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003המקום יחזירך לשלום. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואם איתא דרתח\u0004 \u0005[יש\u0006 מקום לומר \u0005שכעס]\u0006 — \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003מברך לך\u0004 \u0005[אותך],\u0006 ובודאי היתה כוונתו להתיר לך ברצון גמור לצאת. \u0003אדהכי והכי\u0004 \u0005[בינתיים]\u0006 עד שיצא לקראת אמו \u0003שמע לארונא דקאתי\u0004 \u0005[שארונה בא],\u0006 שמתה והביאו את ארונה לארץ. \u0003אמר: אי ידעי\u0004 \u0005אילו הייתי יודע]\u0006 \u0003לא נפקי\u0004 \u0005[הייתי יוצא],\u0006 שאחרי מותה לא היה צריך לצאת לכבודה מן הארץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מכבדו\u0004 את אביו \u0003בחייו, ומכבדו במותו.\u0004 מכבדו \u0003בחייו כיצד? הנשמע בדבר אביו למקום,\u0004 כלומר, ההולך בשליחות אביו למקום מסויים, \u0003לא יאמר\u0004 לאנשים שהוא בא אליהם כדי לזרזם: \u0003\"שלחוני בשביל עצמי\",\u0004 או \u0003\"מהרוני בשביל עצמי\",\u0004 או \u0003\"פטרוני\u0004 וגמרו את העסק \u0003בשביל עצמי\". אלא כולהו\u0004 \u0005[כולם]\u0006 יאמר בלשון: \u0003\"\u0004עשו זאת \u0003בשביל אבא\",\u0004 וזו דרך כבוד.","\u0003במותו כיצד\u0004 מכבדו? — \u0003היה אומר דבר שמועה מפיו\u0004 של אביו, \u0003לא יאמר \"כך אמר אבא\", אלא\u0004 יאמר \u0003\"כך אמר אבא מרי\u0004 (מורי), \u0003הריני כפרת משכבו\". והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאומר בסגנון זה דווקא \u0003תוך שנים עשר חדש\u0004 למותו, ואולם \u0003מכאן ואילך אומר \"זכרונו לברכה לחיי העולם הבא\".\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חכם\u0004 הדורש ברבים — \u0003משנה שם אביו,\u0004 שכאשר הוא אומר דבר בשם אביו אינו מזכיר את אביו בשמו, \u0003ו\u0004כן משנה את \u0003שם רבו\u0004 ולא יקרא לו בשמו. \u0003תורגמן\u0004 שמתרגם את דברי החכם \u0003אינו משנה לא\u0004 את \u0003שם אביו ולא\u0004 את \u0003שם רבו.\u0004 ושואלים: \u0003אבוה דמאן\u0004 \u0005[\u0006ב\u0005אביו של מי]\u0006 מדובר? \u0003אילימא אבוה\u0004 \u0005[אם תאמר\u0006 שמדובר ב\u0005אביו]\u0006 של ה\u0003מתורגמן\u0004 שהזכירו הרב בדרשה — \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003תורגמן לאו בר חיובא\u0004 \u0005[לא בן חיוב]\u0006 \u0003הוא\u0004 במצות כיבוד אב, וכיצד יזכיר המתורגמן את אביו בשמו?","\u0003אלא אמר רבא:\u0004 הכוונה ל\u0003שם אביו של חכם, ושם רבו של חכם. כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003מר בר רב אשי כי הוה דריש בפירקא\u0004 \u0005[כשהיה דורש בדרשה הקבועה]\u0006 והיה אומר הלכה בשם אביו רב אשי, \u0003איהו אמר\u0004 \u0005[הוא היה אומר]:\u0006 כך אמר \u0003אבא מרי\u0004 \u0005[אבי מורי],\u0006 \u0003ואמוריה אמר\u0004 \u0005[והמתורגמן שלו\u0006 היה \u0005אומר]:\u0006 \u0003הכי\u0004 \u0005[כך].\u0006 \u0003אמר רב אשי\u0004 שהבן לא הזכיר את שם האב, אבל המתורגמן רשאי להזכירו בשמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו מורא ואיזהו כיבוד? מורא\u0004 אביו הוא: \u0003לא עומד במקומו\u0004 הקבוע של אביו, \u0003ולא יושב במקומו, ולא סותר את דבריו\u0004 להביע דברים כנגד דברי אביו, \u0003ולא מכריעו,\u0004 שלא יכריע דברים בויכוח שמתווכח אדם אחר עם אביו. איזהו \u0003כיבוד? מאכיל ומשקה\u0004 את אביו, \u0003מלביש ומכסה, מכניס ומוציא\u0004 בכל צרכי הבית.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים:"],["\u0003משל מי?\u0004 כלומר, זה שמאכיל ומשקה את אביו על חשבון מי הוא? \u0003רב יהודה אמר: משל בן. רב נתן בר אושעיא אמר: משל אב. אורו ליה רבנן\u0004 \u0005[הורו לו חכמים]\u0006 \u0003לרב ירמיה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהורו \u0003לבריה\u0004 \u0005[לבנו]\u0006 של \u0003רב ירמיה כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 \u0003משל אב.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003נאמר \"כבד את אביך ואת אמך\"\u0004 (שמות כ, יב), \u0003ונאמר \"כבד את ה' מהונך\"\u0004 (משלי ג, ט) לגזירה שווה: \u0003מה להלן\u0004 בכיבוד המקום נעשה הכיבוד \"מהונך\", כלומר, \u0003בחסרון כיס\u0004 (הוצאה כספית), \u0003אף כאן\u0004 בכיבוד אב נעשה הכיבוד \u0003בחסרון כיס. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שהוא מכבדו \u0003משל אב, מאי נפקא ליה מיניה\u0004 \u0005[מה\u0006 חסרון כיס \u0005יוצא לו מזה]?\u0006 ומשיבים: \u0003לביטול מלאכה.\u0004 שאף שאת גוף הממון אינו חייב להוציא משלו, מכל מקום צריך הבן להתבטל ממלאכתו לצורך כיבוד האב, ונמצא שיש לו בכך חסרון כיס.","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך ממה ששנינו בברייתא: \u0003שני אחים,\u0004 או \u0003שני שותפין\u0004 וכן \u0003האב ובנו,\u0004 או \u0003הרב ותלמידו\u0004 — \u0003פודין זה לזה מעשר שני\u0004 בלי להוסיף חומש, שדינם כדין זר הפודה מעשר שני של חבירו שאינו חייב בתוספת חומש. \u0003ומאכילין זה לזה מעשר עני,\u0004 שאם האחד עני, רשאי האחר להאכילו ממעשר עני שהפריש מתבואתו.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שחובת כיבוד האב היא \u0003משל בן, נמצא זה,\u0004 הבן, \u0003פורע חובו משל עניים,\u0004 שהרי מוטלת עליו החובה לדאוג מממונו לכבוד אביו — והוא משלם אותה ממעשר עני! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן שנותן לאביו את כל צרכיו הבסיסיים מממונו ואם אביו צריך \u0003להעדפה\u0004 (לתוספת) יותר מזה יכול הוא לתת מכסף מעשר עני.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003היינו דקתני עלה\u0004 \u0005[זה ששנינו עליה]\u0006 על ברייתא זו ש\u0003אמר ר' יהודה: תבא מאירה\u0004 (קללה) \u0003למי שמאכיל את אביו מעשר עני. ואי\u0004 \u0005[ואם]\u0006 \u0003להעדפה, מאי נפקא מינה\u0004 \u0005[מה יוצא מכך],\u0006 שהרי הבן ממלא את חובתו ועוד מוסיף כדי שיהיה לאב יותר, ומדוע תבוא עליו קללה?! ומשיבים: \u0003אפילו הכי זילא ביה מילתא\u0004 \u0005[אפילו כך מזולזל בו הדבר]\u0006 באב, שמאכילים אותו מכסף המיועד לצדקה לעניים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003שאלו את ר' אליעזר עד היכן כיבוד אב ואם? אמר להם: כדי שיטול\u0004 האב \u0003ארנקי ויזרקנו לים בפניו\u0004 של בנו \u0003ואינו מכלימו. ואי\u0004 \u0005[ואם]\u0006 \u0003אמרת\u0004 שהוא \u0003משל אב, מאי נפקא ליה מיניה\u0004 \u0005[מה יוצא,\u0006 איכפת \u0005לו מזה]\u0006 שאם זורק האב את הארנק של עצמו, מדוע יקפיד הבן על כך? ומשיבים: מדובר פה \u0003בראוי ליורשו,\u0004 וכיון שסבור שכסף זה יגיע לבסוף לרשותו לכן צריך לומר שלא יכעס.","\u0003וכי הא\u0004 \u0005[וכמו\u0006 מעשה \u0005זה]\u0006 של \u0003רבה בר רב הונא.\u0004 ש\u0003רב הונא קרע שיראי באנפי\u0004 \u0005[היה קורע בגדי משי בפניו]\u0006 של \u0003רבה בריה\u0004 \u0005[בנו].\u0006 \u0003אמר: איזול איחזי אי רתח אי לא רתח\u0004 \u0005[אלך\u0006 ו\u0005אראה אם כועס או אינו כועס],\u0006 כדי לנסותו אם מכבד הוא את אביו. ושואלים: \u0003ודלמא רתח וקעבר\u0004 \u0005[ושמא יכעס\u0006 עליו הבן \u0005ו\u0006נמצא שהאב \u0005עובר]\u0006 על האיסור של \u0003\"\u0004ו\u0003לפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שהוא נותן לפניו מכשול, שעלול לחטוא על ידו! ומשיבים: מדובר באופן \u0003דמחיל ליה ליקריה\u0004 \u0005[ש\u0006האב \u0005מוחל על כבודו]\u0006 מראש, ונמצא שגם אם יכעס הבן אין זה נקרא זלזול בכבוד אב.","ושואלים: \u0003והא קעבר\u0004 \u0005[והרי\u0006 הוא \u0005עובר]\u0006 בקריעת הבגדים \u0003משום \"בל תשחית\"\u0004 (ראה דברים כ, יט)! ומשיבים: \u0003דעבד ליה בפומבייני\u0004 \u0005[שהיה עושה אותו\u0006 קרע, \u0005במקום התפרים]\u0006 כך שהיה רק נראה כקורע. ואומרים: \u0003ודילמא משום הכי לא רתח\u0004 \u0005[ושמא משום כך\u0006 הבן \u0005אינו כועס]\u0006 מפני שלא נגרם שום נזק בדבר? ומשיבים: \u0003דעבד ליה בשעת ריתחיה\u0004 \u0005[שהיה עושה\u0006 זאת \u0005בשעת כעסו]\u0006 ואז לא היה הבן מבחין בפרט זה.","וממשיכים בענין כיבוד אב. \u0003מתני ליה\u0004 \u0005[היה משנה,\u0006 מלמד \u0005לו]\u0006 \u0003רב יחזקאל לרמי בריה\u0004 \u0005[בנו]:\u0006 אם נתערבו \u0003הנשרפים\u0004 (חייבי מיתת שריפה) \u0003בנסקלים\u0004 (בחייבי מיתת סקילה), \u0003ר' שמעון אומר: ידונו\u0004 כולם \u0003בסקילה\u0004 הקלה, \u0003שהשריפה חמורה\u0004 ממנה.","שכיון שיש ספק בדבר — נוהגים בכולם להקל, שלש יטת ר' שמעון שריפה חמורה מסקילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של רב יחזקאל: \u0003אבא, לא תיתנייא הכי\u0004 \u0005[אל תשנה\u0006 אותה \u0005כך]\u0006 כי אין זו גירסה נכונה. כי לפי גירסה זו \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 שיאמר שהטעם הוא כי \u0003שריפה חמורה, תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו מטעם אחר \u0003דרובא\u0004 \u0005[שהרוב]\u0006 \u0003נסקלים נינהו\u0004 \u0005[הם],\u0006 שהרי כך משמעות הלשון — שהנשרפים שהם מיעוט נתערבו בין הרבה נסקלים, ויש איפוא ללכת אחר הרוב! \u0003אלא הכי איתנייא\u0004 \u0005[כך אשנה אותה]:\u0006 \u0003הנסקלים\u0004 שנתערבו \u0003בנשרפים\u0004 שלמרות שהנסקלים הם מיעוט, הולכים אחר המיעוט כדי להקל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יחזקאל: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003וחכמים אומרים ידונו בשריפה\u0004 הקלה, \u0003שהסקילה חמורה\u0004 ממנה. ולפי גירסתך \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 הטעם ש\u0003סקילה חמורה? תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו מטעם אחר — \u0003דרובא נשרפים נינהו\u0004 \u0005[שהרוב נשרפים הם]\u0006 והולכים אחר הרוב!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה בנו: אין זו קושיה מדברי חכמים כי \u0003התם רבנן הוא דקאמרו ליה\u0004 \u0005[שם חכמים הם שאמרו לו]\u0006 \u0003לר' שמעון\u0004 כך: \u0003דקאמרת\u0004 \u0005[\u0006מה \u0005שאתה אומר]\u0006 \u0003שריפה חמורה\u0004 — \u0003לא\u0004 כך הוא, אלא \u0003סקילה חמורה,\u0004 אבל במקרה זה שהנשרפים הם רוב — ידונו בשריפה אפילו אם שריפה היתה חמורה משום שהנסקלים בטלים ברוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה\u0004 לאחר מכן: \u0003שיננא, לא תימא ליה לאבוך הכי\u0004 \u0005[גדול השיניים, אל תאמר לו לאביך כך]\u0006 בלשון זו שאינה דרך כבוד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה אביו עובר על דברי תורה, אל יאמר לו\u0004 במפורש \u0003\"אבא עברת על דברי תורה\", אלא אומר לו: \"אבא כך כתוב בתורה\".\u0004 ותוהים: אם אומר לו \u0003\"כך כתוב בתורה\"\u0004 — \u0003צעורי קא מצער ליה\u0004 \u0005[\u0006הרי \u0005מצער אותו\u0006 בכך\u0005]!\u0006 \u0003אלא אומר לו: \"אבא, מקרא כתוב בתורה כך\"\u0004 שאומר לו מקרא זה, ומאליו מבין האב שעשה דבר שלא כראוי.","\u0003אלעזר בן מתיא אומר:\u0004 אם \u0003אבא אומר \"השקיני מים\", ו\u0004יש \u0003מצוה\u0004 המוטלת עלי \u0003לעשות\u0004 באותו זמן — \u0003מניח אני כבוד אבא, ועושה את המצוה.\u0004 וטעם הדבר — \u0003שאני ואבא חייבים\u0004 שנינו \u0003במצוה. איסי בן יהודה אומר: אם אפשר למצוה\u0004 זו \u0003ליעשות על ידי אחרים\u0004 — \u0003תיעשה על ידי אחרים, וילך הוא\u0004 ויעסוק \u0003בכבוד אביו,\u0004 שהרי מצות כיבוד אב מוטלת רק עליו. \u0003אמר רב מתנה: הלכה\u0004 בדבר זה \u0003כאיסי בן יהודה.\u0004","\u0003אמר רב יצחק בר שילא, אמר רב מתנה, אמר רב חסדא: האב שמחל על כבודו\u0004 — \u0003כבודו מחול,\u0004 ואין בנו נחשב כעובר על המצוה אם אינו נוהג בו כבוד. אבל \u0003הרב שמחל על כבודו\u0004 — \u0003אין כבודו מחול. ו\u0004אילו","\u0003רב יוסף אמר: אפילו הרב שמחל על כבודו\u0004 — \u0003כבודו מחול. שנאמר: \"וה' הולך לפניהם יומם\"\u0004 (שמות יג, כא), הרי שהקדוש ברוך הוא, אף שהוא רבם של ישראל, מוחל על כבודו, וטורח לפני ישראל. \u0003אמר רבא: הכי השתא\u0004 \u0005[איך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 \u0003הקדוש ברוך הוא עלמא דיליה\u0004 \u0005[העולם שלו]\u0006 \u0003הוא, ותורה דיליה\u0004 \u0005[שלו]\u0006 \u0003היא, מחיל ליה ליקריה\u0004 \u0005[\u0006יכול הוא \u0005למחול על כבודו],\u0006 שהרי הוא גזר איך צריך לנהוג והוא יכול לשנות מגזירות עצמו,"],["\u0003הכא\u0004 \u0005[כאן]\u0006 וכי \u0003תורה דיליה\u0004 \u0005[שלו]\u0006 \u0003היא\u0004 שיכול הרב למחול על כבודה?! \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: אין\u0004 \u0005[כן],\u0006 \u0003תורה דיליה\u0004 \u0005[שלו]\u0006 \u0003היא,\u0004 של החכם הלומד אותה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"\u0004כי אם בתורת ה' חפצו \u0003ובתורתו יהגה יומם ולילה\"\u0004 (תהלים א, ב), לומר כי מתחילה התורה היא \"תורת ה'\", ולאחר שהגה בה היא נעשית \"תורתו\".","ושואלים: \u0003איני\u0004 \u0005[כך הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא משקי בי הלולא דבריה\u0004 \u0005[היה משקה\u0006 את האורחים \u0005בשמחת החתונה של בנו]\u0006 \u0003ודל ליה כסא\u0004 \u0005[ומזג לו כוס]\u0006 \u0003לרב פפא ולרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע וקמו מקמיה\u0004 \u0005[ועמדו לפניו]\u0006 כשהתקרב אליהם. וכן השקה \u0003לרב מרי ולרב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא ולא קמו מקמיה\u0004 \u0005[עמדו מ\u0006\u0005פניו].\u0006 \u0003איקפד\u0004 \u0005[הקפיד]\u0006 \u0003ואמר: הנו רבנן רבנן, והנו רבנן לאו רבנן\u0004 \u0005[חכמים אלה\u0006 שלא קמו מפני הם \u0005חכמים, וחכמים אלה\u0006 שקמו מפני \u0005אינם חכמים]?\u0006 כלומר, סבורים אתם שאתם חכמים גדולים כל כך שאינכם צריכים לכבד חכם?","\u0003ותו\u0004 \u0005[ועוד]\u0006 מעשה היה, ש\u0003רב פפא הוה משקי בי הלולא\u0004 \u0005[היה משקה\u0006 את האורחים \u0005במשתה החתונה]\u0006 של \u0003אבא מר בריה\u0004 \u0005[בנו]\u0006 \u0003ודלי ליה כסא\u0004 \u0005[ומזג לו כוס]\u0006 \u0003לר' יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה ולא קם מקמיה\u0004 \u0005[עמד מפניו]\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 רב פפא על כך. וגם מכאן משמע שאף שמחל על כבודו (והשקה לאורחים) אין כבודו מחול! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 שהרב מוחל על כבודו — \u0003הידור מיעבד ליה בעו\u0004 \u0005[לעשות לו\u0006 איזה עניין של \u0005הידור,\u0006 כמבקשים לעמוד לפניו, \u0005צריכים\u0006 היו\u0005].\u0006","\u0003אמר רב אשי: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003הרב שמחל על כבודו\u0004 — \u0003כבודו מחול,\u0004 אולם \u0003נשיא שמחל על כבודו\u0004 — \u0003אין כבודו מחול. מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003מעשה בר' אליעזר ור' יהושע ור' צדוק שהיו מסובין בבית המשתה\u0004 של \u0003בנו של רבן גמליאל,\u0004 שהיה נשיא הסנהדרין, \u0003והיה רבן גמליאל עומד ומשקה עליהם. נתן הכוס לר' אליעזר ולא נטלו, נתנו לר' יהושע וקיבלו. אמר לו ר' אליעזר: מה זה יהושע? אנו יושבין ורבן גמליאל ברבי\u0004 (הגדול), \u0003עומד ומשקה עלינו?!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מצינו גדול ממנו ששמש\u0004 את אורחיו, ש\u0003אברהם\u0004 אבינו \u0003גדול ממנו\u0004 — \u0003ושמש\u0004 אורחים. שהרי \u0003אברהם גדול הדור היה, וכתוב בו \"והוא עמד עליהם\u0004 תחת העץ ויאכלו\u0003\"\u0004 (בראשית יח, ח), \u0003ושמא תאמרו: כמלאכי השרת נדמו לו\u0004 ומשום כך כיבד אותם — הרי \u0003לא נדמו לו אלא לערביים. ואנו, לא יהא רבן גמליאל ברבי עומד ומשקה עלינו?!\u0004","\u0003אמר להם ר' צדוק: עד מתי אתם מניחים כבודו של מקום\u0004 שאפשר להביא ראיה מהקדוש ברוך הוא עצמו \u0003ואתם עוסקים בכבוד הבריות?\u0004 הלא \u0003הקדוש ברוך הוא משיב רוחות, ומעלה נשיאים\u0004 (עננים), \u0003ומוריד מטר, ומצמיח אדמה, ועורך שולחן לפני כל אחד ואחד, ואנו לא יהא רבן גמליאל ברבי עומד ומשקה עלינו?\u0004 משמע שאף נשיא שמחל על כבודו — כבודו מחול!","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב אשי: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נשיא שמחל על כבודו\u0004 — \u0003כבודו מחול,\u0004 מכל מקום \u0003מלך שמחל על כבודו\u0004 — \u0003אין כבודו מחול,\u0004 שמה \u0003שנאמר:\u0004 \u0003\"שום תשים עליך מלך\"\u0004 (דברים יז, טו) כוונתו: \u0003שתהא אימתו עליך,\u0004 שמצוה היא לירוא ממנו, ומצוה זו אף המלך עצמו אינו יכול למחול עליה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"מפני שיבה תקום\"\u0004 (ויקרא יט, לב), \u0003יכול אפילו מפני זקן אשמאי\u0004 (פשוט, בור) — \u0003תלמוד לומר \"זקן\", ואין זקן אלא חכם, שנאמר: \"אספה לי שבעים איש מזקני ישראל\u0004 אשר ידעת כי הם זקני העם ושוטריו\u0003\"\u0004 (במדבר יא, טז). \u0003ר' יוסי הגלילי אומר: אין \"זקן\" אלא מי שקנה חכמה,\u0004 וכעין קיצור (\"נוטריקון\") — זה קנה, וכן מצאנו לשון קנין שהיא מתייחסת לחכמה, \u0003שנאמר\u0004 שאומרת החכמה: \u0003\"ה' קנני ראשית דרכו\"\u0004 (משלי ח, כב).","ולענין הלכה למעשה, \u0003יכול יעמוד מפניו\u0004 מפני הזקן מיד כשרואהו \u0003ממקום רחוק\u0004 — \u0003תלמוד לומר:\u0004 \"מפני שיבה \u0003תקום והדרת\u0004 פני זקן\" \u0003לא אמרתי\u0004 שיש חובה ב\u0003קימה אלא במקום שיש הידור,\u0004 ואם עומד כאשר הזקן הוא רחוק, אין זה ניכר שהוא נותן לו כבוד.","\u0003יכול יהדרנו בממון,\u0004 שיהא חייב לתת לו ממון לכבודו — \u0003תלמוד לומר: \"תקום והדרת\", מה קימה\u0004 היא דבר \u0003שאין בה חסרון כיס\u0004 (הוצאה כספית) — \u0003אף הידור\u0004 הוא דבר \u0003שאין בו חסרון כיס. יכול יעמוד מפניו\u0004 גם \u0003מבית הכסא ומבית המרחץ\u0004 — \u0003תלמוד לומר: \"תקום והדרת\", לא אמרתי\u0004 מצות \u0003קימה אלא במקום שיש הידור,\u0004 ומקומות אלה אינם מקומות מכובדים שראוי לכבד אדם בהם.","\u0003יכול יעצים\u0004 (יעצום), הרואה, את \u0003עיניו\u0004 מן הזקן \u0003כמי שלא ראהו\u0004 — \u0003תלמוד לומר: \"תקום... ויראת\u0004 מאלוהיך\u0003\"\u0004 (ויקרא יט, לב) שכל \u0003דבר המסור ללב נאמר בו \"ויראת מאלהיך\",\u0004 שהרי אי אפשר להוכיח אם ראה או לא ראה, אלא זה דבר המסור ללב האדם, וגלוי רק לאלוקיו.","\u0003ר' שמעון בן אלעזר אומר: מנין לזקן שלא יטריח\u0004 על הבריות לכבדו — \u0003תלמוד לומר: \"זקן ויראת\",\u0004 לומר שגם הזקן מצווה על יראת ה', שלא יטריח את הבריות. ולסיום מביאה הברי יתא דעה נוספת: \u0003איסי בן יהודה אומר:\u0004 מה שנאמר \u0003\"מפני שיבה תקום\",\u0004 הרי זה בא לומר: \u0003אפילו כל שיבה במשמע\u0004 ולאו דווקא חכם.","ומבררים את פרטיה של ברייתא זו: לכאורה דעת \u0003ר' יוסי הגלילי היינו תנא קמא\u0004 \u0005[היא\u0006 שיטת \u0005התנא הראשון]\u0006 שזקן הוא חכם ומה בא להוסיף? ומשיבים: \u0003איכא בינייהו יניק וחכים\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה לגבי \u0005צעיר וחכם];\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר: יניק וחכים\u0004 \u0005[צעיר וחכם]\u0006 — \u0003לא\u0004 \u0005[צעיר וחכם לא]\u0006 נקרא זקן, שאין מצות כיבוד אלא לזקן חכם, ואילו \u0003ר' יוסי הגלילי סבר: אפילו יניק וחכים\u0004 \u0005[צעיר וחכם]\u0006 מצוה לכבדו, שאין הכוונה כלל לזקנה בשנים אלא בחכמה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי? אמר\u0004 \u0005[\u0006יכול היה ר' יוסבי הגלילי \u0005לומר]\u0006 \u0003לך: אי סלקא דעתך כדקאמר תנא קמא\u0004 \u0005[אם עולה על דעתך\u0006 לפרש \u0005כפי שאמר תנא קמא]\u0006 — \u0003אם כן נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"מפני שיבה זקן תקום והדרת\", מאי שנא דפלגינהו רחמנא\u0004 \u0005[מה שונה, שחילק אותם הכתוב]\u0006 \"שיבה\" לחוד ו\"זקן\" לחוד — \u0003למימר\u0004 \u0005[לומר]\u0006 לך: \u0003דהאי לאו האי, והאי לאו האי\u0004 \u0005[שזה אינו זה, וזה אינו זה],\u0006 שזקן אינו צריך להיות בגדר \"שיבה\". \u0003שמע מינה אפילו יניק וחכים\u0004 \u0005[למד מכאן\u0006 ש\u0005אפילו צעיר וחכם]\u0006 נקרא \"זקן\".","\u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 אומר שהפסוק נכתב כך \u0003משום דבעי למיסמך\u0004 \u0005[שרצה לסמוך]\u0006 \u0003\"זקן\"\u0004 ל\u0003\"ויראת\"\u0004 כדברי ר' שמעון בן אלעזר. ושואלים: \u0003ותנא קמא מאי טעמא\u0004 \u0005[והתנא הראשון מה הטעם],\u0006 מדוע סבור הוא שרק מפני חכם זקן צריך לעמוד? ומשיבים: שהוא סבור \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר \u0003כדקאמר\u0004 \u0005[כפי שאומר]\u0006 \u0003ר' יוסי הגלילי\u0004 — \u0003אם כן נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006"],["\u0003\"מפני שיבה תקום והדרת, תקום והדרת פני זקן\" ומדלא כתב הכי\u0004 \u0005[ומ\u0006תוך \u0005שלא כתב כך]\u0006 לחלקם לגמרי, \u0003שמע מינה חד הוא\u0004 \u0005[למד מכאן,\u0006 ש\u0005אחד הוא]\u0006 \"זקן\" ו\"שיבה\".","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003יכול יהדרנו בממון\u0004 — \u0003תלמוד לומר: \"תקום והדרת\": מה קימה\u0004 היא דבר \u0003שאין בה חסרון כיס\u0004 (הוצאה כספית) — \u0003אף הידור שאין בו חסרון כיס.\u0004 ושואלים: \u0003וקימה לית\u0004 \u0005[אין]\u0006 \u0003בה חסרון כיס\u0004 כלל? \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 גם במקרה \u0003דקא נקיב מרגניתא\u0004 \u0005[ש\u0006הוא \u0005נוקב מרגליות]\u0006 שהיא מלאכה שמקבלים עליה שכר מרובה, \u0003אדהכי והכי קאים מקמיה ובטיל\u0004 \u0005[ובינתיים\u0006 הוא \u0005עומד לפניו ובטל]\u0006 \u0003ממלאכתו\u0004 ומפסיד משכרו ונמצא שאף קימה אפשר שיהא בה חסרון כיס!","\u0003אלא\u0004 יש להקדים ולומר כך: \u0003אקיש\u0004 \u0005[הקש,\u0006 השווה\u0005]\u0006 \u0003קימה להידור; מה הידור שאין בו ביטול\u0004 מלאכה — \u0003אף קימה שאין בה ביטול\u0004 מלאכה, והעוסק במלאכתו אינו צריך אפוא לקום מפני החכם. \u0003ו\u0004מתוך כך \u0003אקיש נמי\u0004 \u0005[הקש גם כן]\u0006 \u0003הידור לקימה, מה קימה שאין בה חסרון כיס,\u0004 שהרי כך הגדרנוה — כל שאין עימה ביטול מלאכה — \u0003אף הידור שאין בו חסרון כיס. מכאן אמרו: אין בעלי אומניות רשאין\u0004 (כלומר, אינם חייבים) \u0003לעמוד מפני תלמידי חכמים, בשעה שעוסקין במלאכתם.\u0004","ושואלים: \u0003ולא,\u0004 וכי אין הם חייבים לקום? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 כאשר באים מביאי הביכורים לירושלים \u0003כל בעלי אומניות עומדים מפניהם, ושואלים בשלומם, ואומרים להם: אחינו אנשי מקום פלוני בואכם לשלום!\u0004 משמע שעומדים אפילו לפני אנשים העוסקים במצוה וכל שכן לפני תלמידי חכמים! \u0003אמר ר' יוחנן:\u0004 אין זו קושיה, אכן \u0003מפניהם עומדים,\u0004 אבל \u0003מפני תלמידי חכמים אין עומדים.\u0004","ומתוך כך \u0003אמר ר' יוסי בר אבין: בוא וראה כמה חביבה מצוה בשעתה, שהרי מפניהם\u0004 של מקיימי מצוה \u0003עומדים\u0004 בעלי אומניות ואילו \u0003מפני תלמידי חכמים אין עומדים.\u0004 את הראיה הזו דוחים: מכאן אין להוכיח לגבי כל מצוה בשעתה, \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 במביאי ביכורים, ש\u0003אם כן,\u0004 שאין נוהגים בהם כבוד, נמצא ש\u0003אתה מכשילן לעתיד לבא,\u0004 שלא ירצו שוב לבוא, ולכן תקנו שיכבדום במיוחד, ואין הדין כן בשאר עושי מצוה.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003יכול יעמוד מפניו\u0004 של \u0003רבו\u0004 \u0003מבית הכסא ומבית המרחץ\u0004 — תלמוד לומר: \"תקום והדרת\" לא אמרתי קימה אלא במקום שיש הידור. ושואלים: \u0003ולא,\u0004 האם אין מכבדים שם? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' חייא הוה יתיב בי מסחותא\u0004 \u0005[היה יושב\u0006 ב\u0005בית המרחץ]\u0006 \u0003וחליף ואזיל\u0004 \u0005[והיה חולף ועובר]\u0006 \u0003ר' שמעון בר רבי\u0004 על פניו, \u0003ולא קם מקמיה\u0004 \u0005[ולא עמד מלפניו]\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 ר' שמעון בר רבי על כך, \u0003ואתא אמר ליה לאבוה\u0004 \u0005[ובא ואמר לו לאביו\u0006 (רבי)\u0005]:\u0006 \u0003שני חומשים\u0004 מתוך חמשת ה\"חומשים\" שמחולק בהם ספר תהלים \u0003שניתי לו בספר תהלים, ולא עמד מפני!\u0004 משמע שגם בבית המרחץ יש ענין זה של כיבוד!","\u0003ותו\u0004 \u0005[ועוד]\u0006 מסופר: \u0003בר קפרא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' שמואל בר ר' יוסי, הוה יתיב בי מסחותא\u0004 \u0005[היה יושב\u0006 ב\u0005בית המרחץ],\u0006 \u0003על ואזיל\u0004 \u0005[נכנס ועבר]\u0006 \u0003ר' שמעון בר רבי, ולא קם מקמיה\u0004 \u0005[עמד מפניו],\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 ר' שמעון \u0003ואתא אמר ליה לאבוה\u0004 \u0005[ובא\u0006 ו\u0005אמר לו לאביו]:\u0006 \u0003שני שלישי שליש שניתי לו בתורת כהנים\u0004 (ספרא — מדרש ההלכה לספר ויקרא) \u0003ולא עמד מפני! ואמר לו\u0004 רבי: \u0003שמא בהן\u0004 במה ששנית לו היה \u0003יושב ומהרהר,\u0004 ולא ראה שנכנסת.","ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בהן יושב ומהרהר, הא לאו הכי\u0004 \u0005[הרי לולא כן]\u0006 \u0003לא\u0004 היה רבי מצדיק אותו! ומכאן משמע שצריך לעמוד מפני החכם אף בבית המרחץ!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין צריך לעמוד בפניו בבית המרחץ הרי זה \u0003בבתי גואי\u0004 \u0005[בבתים,\u0006 בחדרים, \u0005פנימיים],\u0006 כשכולם ערומים ובכגון זה ודאי שאין בכך משום כבוד, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שצריך לעמוד בפניו בבית המרחץ הרי זה \u0003בבתי בראי\u0004 \u0005[בבתים,\u0006 בחדרים, \u0005החיצונים]\u0006 שבהם אנשים עדיין לבושים ובכך יש משום כבוד.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: בכל מקום מותר להרהר\u0004 בדברי תורה \u0003חוץ מבית המרחץ ומבית הכסא.\u0004 ואם אמר רבי \"בהן היה יושב ומהרהר\", משמע שהיה זה במקום שאין בו כל דיני בית המרחץ, דהיינו החדרים החיצוניים. את הראיה הזו דוחים: \u0003דילמא לאונסיה שאני\u0004 \u0005[שמא לאונסו שונה],\u0006 שייתכן ששקע בהרהור ושכח שהוא נמצא במקום האסור בכך.","שנינו באותה ברייתא: \u0003יכול יעצים עיניו כמי שלא ראהו\u0004 וכו'. ותוהים: \u0003אטו ברשיעי עסקינן\u0004 \u0005[וכי ברשעים אנו עוסקים],\u0006 בכאלה שעוברים בזדון, ואינם מקיימים מצוה?","\u0003אלא\u0004 הכוונה: \u0003יכול יעצים עיניו מקמי דלימטיה זמן חיובא\u0004 \u0005[לפני שיגיע זמן החיוב\u0006 לקום\u0005]\u0006 בעוד הזקן רחוק, \u0003דכי מטא\u0004 \u0005[שכאשר מגיע]\u0006 \u0003זמן חיובא\u0004 \u0005[החיוב]\u0006 \u0003הא לא חזי דקאים מקמיה\u0004 \u0005[הרי אינו רואה אותו שיקום מלפניו]\u0006 ובכך סבור הוא שיוכל להשתמט מחיוב המצוה, \u0003תלמוד לומר: \"תקום ויראת\"\u0004 שהדבר מסור ללב, ועליך להיות ירא מיודע התעלומות.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003איזוהי קימה שיש בה הידור\u0004 כשנמצא — \u0003הוי אומר זה\u0004 שניכר שעומד לכבודו בתוך \u0003ארבע אמות. אמר אביי: לא אמרן\u0004 \u0005[לא אמרנו]\u0006 דבר זה שקמים רק בתוך ארבע אמות \u0003אלא ברבו שאינו מובהק, אבל ברבו המובהק\u0004 — עומד לפניו \u0003מלא עיניו,\u0004 ממקום שעיניו רואות אותו אפילו הוא יותר מארבע אמות.","וכן מסופר: \u0003אביי מכי הוה חזי ליה לאודניה דחמרא\u0004 \u0005[מזמן שהיה רואה את אוזו חמורו]\u0006 של \u0003רב יוסף דאתי\u0004 \u0005[ש\u0006הוא \u0005בא],\u0006 \u0003הוה קאים\u0004 \u0005[היה עומד].\u0006 מסופר: \u0003אביי הוה רכיב חמרא וקא מסגי אגודא דנהר\u0004 \u0005[היה רוכב\u0006 על \u0005חמור והולך על שפת נהר]\u0006 \u0003סגיא,\u0004 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב משרשיא ורבנן\u0004 \u0005[וחכמים\u0006 אחרים\u0005]\u0006 \u0003באידך גיסא\u0004 \u0005[בצידו האחר]\u0006 של הנהר \u0003ולא קמו מקמיה\u0004 \u0005[עמדו מפניו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ו\u0004כי \u0003לאו\u0004 \u0005[ולא]\u0006 \u0003רב מובהק\u0004 שלכם \u0003אנא\u0004 \u0005[אני]]?\u0006 וחייבים אתם לקום אפילו מרחוק. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אדעתין\u0004 \u0005[לא\u0006 היה \u0005בדעתנו],\u0006 כלומר, לא ראינוך כלל.","שנינו שם ש\u0003ר' שמעון בן אלעזר אומר: מנין לזקן שלא יטריח\u0004 על הבריות לגרום שיעמדו מפניו — \u0003תלמוד לומר: \"זקן ויראת\". אמר אביי: נקטינן\u0004 \u0005[מוחזק בידינו]\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 הוא, החכם, \u0003מקיף,\u0004 שמטריח עצמו להקיף מסביב כדי שלא יצטרכו הנמצאים לטרוח ולעמוד מלפניו — \u0003חיי\u0004 \u0005[יחיה,\u0006 יאריך ימים\u0005].\u0006 מסופר: \u0003אביי\u0004 היה \u0003מקיף,\u0004 וכן \u0003ר' זירא\u0004 היה \u0003מקיף.\u0004","ועוד בענין כבוד הרב, מסופר: \u0003רבינא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' ירמיה מדיפתי, חלף ההוא גברא קמיה\u0004 \u0005[עבר אדם אחד לפניו]\u0006 \u0003ולא מיכסי רישא\u0004 \u0005[כיסה\u0006 את \u0005ראשו].\u0006 \u0003אמר: כמה חציף הא גברא\u0004 \u0005[חצוף אדם זה]\u0006 שאינו נוהג אפילו כבוד מעט זה לכסות ראשו מפני כבוד הרב. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מ\u0004העיר \u0003מתא מחסיא ניהו\u0004 \u0005[הוא]\u0006 \u0003דגיסי\u0004 \u0005[שרגילים]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 ולכן אין מדקדקים כל כך בכבודם.","על מה ששנינו \u0003איסי בן יהודה אומר:\u0004 מה שנאמר \u0003\"מפני שיבה תקום\"\u0004 הרי זה בא לומר: \u0003ואפילו כל שיבה במשמע\u0004 ולא רק תלמידי חכמים. \u0003אמר ר' יוחנן: הלכה כאיסי בן יהודה.\u0004 מסופר: \u0003ר' יוחנן\u0004 עצמו \u0003הוה קאי מקמי סבי דארמאי\u0004 \u0005[היה עומד לפני זקני הגויים].\u0006 \u0003אמר: כמה הרפתקי עדו עלייהו דהני\u0004 \u0005[כמה הרפתקאות\u0006 ומאורעות חיים \u0005באו עליהם, על אלה]\u0006 וראוי לכבד אותם בשל חכמת החיים שקנו. \u0003רבא מיקם\u0004 \u0005[לעמוד]\u0006 \u0003לא קאי\u0004 \u0005[היה עומד],\u0006 ואולם \u0003הידור\u0004 מסויים \u0003עבד להו\u0004 \u0005[היה עושה להם\u0006 לכבדם\u0005].\u0006","\u0003אביי יהיב ידא לסבי\u0004 \u0005[היה נותן יד לזקנים]\u0006 שישענו עליו. \u0003רבא משדר שלוחיה\u0004 \u0005[היה שולח את שליחו]\u0006 שיעזור להם. \u0003רב נחמן משדר גוזאי\u0004 \u0005[היה שולח את הסריסים,\u0006 המשרתים\u0005]\u0006 לעזור להם. \u0003אמר: אי לאו\u0004 \u0005[אם לא]\u0006 \u0003תורה\u0004 שיש בי \u0003כמה נחמן בר אבא איכא בשוקא\u0004 \u0005[יש בשוק]?\u0006 ואינו רשאי לזלזל בכבוד תורתו, אם יכול לעשות מצוה זו על ידי אחרים.","\u0003אמר ר' אייבו אמר ר' ינאי:\u0004"],["\u0003אין תלמיד חכם רשאי לעמוד מפני רבו אלא שחרית וערבית\u0004 (בבוקר ובערב), \u0003כדי שלא יהיה כבודו\u0004 של הרב \u0003מרובה מכבוד שמים,\u0004 שהרי אינו עומד לפני הקדוש ברוך הוא בתפילה אלא פעמיים ביום. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו, \u0003ר' שמעון בן אלעזר אומר: מנין לזקן שלא יטריח\u0004 את הבריות לעמוד לפניו על ידי שעובר לפניהם — \u0003תלמוד לומר:\u0004 \"והדרת פני \u0003זקן ויראת\u0004 מאלהיך\" (ויקרא יט, לב), וסמיכות המילים \"זקן ויראת\" באה ללמד שאף על הזקן להיות ירא שמים, ולא להטריח את הבריות.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003שחרית וערבית בלבד, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא ניטרח\u0004 \u0005[יטריח]?\u0006 \u0003חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא\u0004 על האנשים שלפניו, ואין בכך טירחה יתירה! \u0003אלא לאו כולי יומא\u0004 \u0005[האם לא\u0006 הכוונה היא \u0005שכל היום]\u0006 חייבים לעמוד מפניו! ומשיבים: \u0003לא, לעולם שחרית וערבית בלבד, ואפילו הכי\u0004 \u0005[כך]\u0006 כל \u0003כמה\u0004 ש\u0003אפשר ליה\u0004 \u0005[לו]\u0006 — \u0003לא ניטרח\u0004 \u0005[יטריח].\u0006","\u0003אמר ר' אלעזר: כל תלמיד חכם שאין עומד מפני רבו נקרא רשע, ואינו מאריך ימים, ותלמודו משתכח, שנאמר: \"וטוב לא יהיה לרשע ולא יאריך ימים כצל אשר איננו ירא מלפני אלהים\"\u0004 (קהלת ח, יג), \u0003מורא זו\u0004 (\"איננו ירא\") שבפסוק \u0003איני יודע מהו\u0004 באיזה מורא מדובר — \u0003כשהוא אומר \"\u0004והדרת פני זקן \u0003ויראת מאלהיך\"\u0004 (ויקרא יט, לב) — \u0003הרי\u0004 למד אני ש\u0003מורא זו קימה.\u0004 ומכאן שאם אינו קם, נקרא רשע ואינו מאריך ימים, ותלמודו משתכח (\"וטוב לא יהיה\").","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא ל\u0003מוראת רבית\u0004 (\"אל תיקח מאיתו נשך ותרבית ויראת מאלהיך\". ויקרא כה, לו) \u0003ומוראת משקלות\u0004 (דברים כה, טו–טז) שגם בהם נאמרה לשון שמשמעה יראה! ומשיבים: \u0003ר' אלעזר\u0004 בגזירה שווה: \u0003\"פני\u0004 זקן \u0003\"\u0004ו\"מל\u0003פני\u0004 האלהים\" \u0003גמר\u0004 \u0005[למד].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003בנו והוא,\u0004 הבן, \u0003רבו\u0004 של האב, \u0003מהו\u0004 הדין, האם צריך הבן \u0003לעמוד מפני אביו? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים]\u0006 \u0003קום מקמי אבוך\u0004 \u0005[עמוד מפני אביך],\u0006 משמע שאף על פי שהיה רב יהודה גדול בתורה ומלמד את אביו, מכל מקום חייב הוא לעמוד מפניו. ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב יחזקאל\u0004 אביו של רב יהודה ש\u0003בעל מעשים הוה\u0004 \u0005[היה],\u0006 שהיה צדיק במעשיו ש\u0003אפילו מר שמואל\u0004 עצמו \u0003נמי קאים מקמיה\u0004 \u0005[גם כן היה עומד מפניו].\u0006","ושואלים: אם כן \u0003אלא מאי קאמר ליה\u0004 \u0005[מה אמר לו]\u0006 שמואל לר' יהודה שיקום מפני אביו אם לא לצורך חידוש זה בענין קימת הבן שהוא רבו של אביו? ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003זימנין דאתי\u0004 \u0005[פעמים ש\u0006אביך \u0005בא]\u0006 \u0003מאחורי\u0004 ואין אני רואה אותו, ואני איני עומד מפניו, \u0003קום את מקמיה ולא תיחוש ליקרא דידי\u0004 \u0005[עמוד אתה מלפניו ואל תחשוש לכבודי שלי].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003בנו והוא רבו\u0004 של האב, \u0003מהו שיעמוד אביו מפניו? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ש\u0003אמר ר' יהושע בן לוי: אני איני כדי\u0004 (ראוי, צריך), \u0003לעמוד מפני בני\u0004 לפי גדולתו בתורה לפי שאני גדול ממנו, \u0003אלא משום כבוד בית נשיא\u0004 שהבן נעשה חתן לנשיא — עומד אני מפניו.","ומכאן נדייק: \u0003טעמא דאנא רביה\u0004 \u0005[הטעם,\u0006 דווקא, מפני \u0005שאני רבו]\u0006 ולכן איני צריך לעמוד מפניו, \u0003הא איהו רבאי\u0004 \u0005[הרי\u0006 אם היה \u0005הוא רבי]\u0006 — \u0003קאימנא מקמיה\u0004 \u0005[הייתי עומד מפניו]!\u0006 ודוחים: אין מכאן ראיה, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אני איני כדי לעמוד מפני בני ואפילו\u0004 היה \u0003הוא רבאי\u0004 \u0005[רבי]\u0006 \u0003דהא אנא אבוה\u0004 \u0005[שהרי אני אביו],\u0006 \u0003אלא משום כבוד בית נשיא\u0004 אקום מפניו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 רבו שהיה \u0003רכוב\u0004 על גבי בהמה האם \u0003כמהלך דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 וצריך לעמוד בפניו, \u0003או לא\u0004 צריך לקום מפניו כיון שנחשב הוא כיושב? \u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 דברים בשאלה זו: \u0003טמא\u0004 מצורע, שהוא מטמא באהל, שכל הנכנס למקום שהמצורע נמצא בו נטמא, שהיה \u0003יושב תחת האילן\u0004 המאהיל עליו ומטמא, \u0003וטהור עומד\u0004 תחת אותו אילן — הרי הטהור נעשה \u0003טמא.\u0004","היה \u0003טמא עומד תחת האילן וטהור יושב\u0004 — \u0003טהור,\u0004 שכיון שהטמא שם שלא בדרך קביעות, אינו עושה את המקום לאהל הטומאה, \u0003ואם\u0004 לאחר מכן \u0003ישב הטמא\u0004 וקבע מקומו שם — \u0003הטהור טמא. ו\u0004מוסיפה המשנה ש","\u0003כן\u0004 הדין \u0003באבן המנוגעת\u0004 (שנטמאה בנגע) צרעת הבית שמטמאה אף היא באהל, ואם ישב הנושא אותה תחת האילן — נטמא הטהור העומד תחת האילן. ואם עמד הנושא אותה — אינה מטמאה. \u0003ואמר רב נחמן בר כהן: זאת אומרת רכוב כמהלך דמי\u0004 \u0005[נחשב],\u0006 שהולכים אנו לפי מצבו של נושא האבן המרכיב אותה עליו, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 לכל ענין שרכוב נחשב כמהלך.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו לעמוד מפני ספר תורה? ר' חלקיה ור' סימון ור' אלעזר אמרי\u0004 \u0005[\u0006היו \u0005אומרים]\u0006 ש\u0003קל וחומר\u0004 הוא: אם \u0003מפני לומדיה\u0004 של התורה \u0003עומדים\u0004 — \u0003מפניה\u0004 עצמה \u0003לא כל שכן?!\u0004","ומסופר: \u0003ר' אלעי ור' יעקב בר זבדי הוו יתבי\u0004 \u0005[היו יושבים]\u0006 ולומדים תורה. \u0003חליף ואזיל\u0004 \u0005[חלף ועבר]\u0006 על פניהם \u0003ר' שמעון בר אבא, וקמו מקמיה\u0004 \u0005[ועמדו לפניו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 אין אתם צריכים לעשות כן מפני שתי סיבות: \u0003חדא\u0004 \u0005[\u0006סיבה \u0005אחת]\u0006 — \u0003דאתון חכימי ואנא\u0004 \u0005[שאתם חכמים\u0006 סמוכים \u0005ואני]\u0006 אינני אלא \u0003חבר,\u0004 שלא נסמכתי. \u0003ועוד, כלום תורה עומדת מפני לומדיה,\u0004 שהרי אתם עוסקים בתורה, ואינכם צריכים באותה שעה לעמוד מפני לומדי תורה.","ומעירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: אין תלמיד חכם רשאי לעמוד מפני רבו בשעה שעוסק בתורה,\u0004 שהרי הוא עוסק בכבוד התורה עצמה. ומעירים: אף על פי כן \u0003לייט עלה\u0004 \u0005[היה מקלל על זה]\u0006 \u0003אביי\u0004 מי שעושה כן, משום שהדבר נראה כזלזול בכבוד הרב.","ועוד בענין מצות קימה: מה שנאמר \u0003\"והביטו אחרי משה עד באו האהלה\"\u0004 (שמות לג, ח), \u0003ר' אמי ור' יצחק נפחא\u0004 נחלקו בפירוש הדברים. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי דבר זה נאמר \u0003לגנאי, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שדבר זה נאמר \u0003לשבח. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לגנאי\u0004 — \u0003כדאיתא\u0004 \u0005[כמו שיש]\u0006 בענין זה במדרש, מה היו מדברים בגנותו. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לשבח,\u0004 כפי ש\u0003אמר חזקיה:\u0004","\u0003אמר לי ר' חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו, אמר ר' אבהו, אמר ר' אבדימי דמן חיפא:\u0004 אם היה \u0003חכם עובר\u0004 — \u0003עומד מלפניו\u0004 בתוך \u0003ארבע אמות\u0004 שלו, \u0003וכיון שעבר ארבע אמות\u0004 ממנו — \u0003יושב.\u0004 היה \u0003אב בית דין עובר\u0004 — \u0003עומד מלפניו\u0004 כשרואה אותו במרחק \u0003מלא עיניו, וכיון שעבר\u0004 ממנו \u0003ארבע אמות יושב.\u0004 אם \u0003נשיא עובר\u0004 — \u0003עומד מלפניו מלא עיניו, ואינו יושב עד שישב\u0004 הנשיא \u0003במקומו, שנאמר: \"והביטו אחרי משה עד באו האהלה\"\u0004 ורק אחר כך ישבו, הרי שדרשו זאת לשבח.","שנינו במשנה ש\u0003כל מצות עשה שהזמן גרמא\u0004 נשים פטורות מהן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזוהי מצות עשה שהזמן גרמא\u0004 — כגון ישיבה ב\u0003סוכה, ו\u0004נטילת \u0003לולב,\u0004 תקיעת \u0003שופר\u0004 בראש השנה שהן מצוות החלות רק בזמן מסויים בשנה, \u0003ו\u0004לבישת \u0003ציצית\u0004 (שמצוותה רק ביום)"],["\u0003ו\u0004הנחת \u0003תפילין\u0004 שאין מצוותה בלילה ולא בשבתות ובימים טובים.","\u0003ואיזוהי מצות עשה שלא הזמן גרמא\u0004 — כגון קביעת \u0003מזוזה,\u0004 עשיית \u0003מעקה\u0004 לגג, השבת \u0003אבידה, ושילוח הקן\u0004 (שמצוה לשלח ציפור כשמצאה רובצת על אפרוחים או ביצים).","ושואלים: \u0003וכללא\u0004 \u0005[ו\u0006האם \u0005כלל]\u0006 \u0003הוא\u0004 זה החל על כל מצוות עשה שהזמן גרמן? ו\u0003הרי\u0004 מצות אכילת \u0003מצה\u0004 בפסח, מצות \u0003שמחה\u0004 ברגל, מצות \u0003הקהל\u0004 בחג הסוכות שלאחר שנת השמיטה, שהכל באים ואף נשים, כמפורש בתורה, שכולן \u0003מצות עשה שהזמן גרמא\u0004 הן, \u0003ונשים חייבות\u0004 בהן! \u0003ותו\u0004 \u0005[ועוד]\u0006 מצד אחר: \u0003והרי\u0004 מצות \u0003תלמוד תורה,\u0004 ו\u0003פריה ורביה, ופדיון הבן דלאו\u0004 \u0005[שלא]\u0006 \u0003מצות עשה שהזמן גרמא הוא\u0004 — \u0003ו\u0004בכל זאת \u0003נשים פטורות\u0004 מהן!","\u0003אמר ר' יוחנן: אין למדין\u0004 הלכה למעשה \u0003מן הכללות, ואפילו במקום שנאמר בו \"חוץ\u0004 מדבר מסויים","\u0003\",\u0004 שאף שנראה בכך שהחכם קובע כלל מדוייק. בכל זאת אין סומכים על הכלל. וראיה לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בכל מערבין\u0004 עירובי תחומין \u0003ומשתתפין\u0004 בשיתופי מבואות \u0003חוץ מן המים ומלח,\u0004 ולכאורה יש כאן כלל מדוייק הקובע מיהם היוצאים מן הכלל הזה, ובאמת \u0003ותו ליכא\u0004 \u0005[ויותר אין\u0006 שאין מערבים בהם\u0005]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003כמהין ופטריות\u0004 שאין מערבים בהן! \u0003אלא\u0004 מכאן ש\u0003אין למדין מן הכללות, ואפילו במקום שנאמר בו \"חוץ\".\u0004","ומעתה באים לברר את מקורותיו של כלל זה. מה ששנינו ש\u0003כל מצות עשה שהזמן גרמא נשים פטורות\" מנלן\u0004 \u0005[מניין לנו]?\u0006 — \u0003גמר\u0004 \u0005[למד]\u0006 דבר זה בהיקש \u0003מתפילין; מה תפילין נשים פטורות\u0004 — \u0003אף כל מצות עשה\u0004 אחרות \u0003שהזמן גרמא נשים פטורות. ו\u0004מהיכן יודעים שנשים פטורות מ\u0003תפילין?\u0004 — \u0003גמר לה\u0004 \u0005[למד אותה]\u0006 \u0003מתלמוד תורה, מה תלמוד תורה נשים פטורות\u0004 — \u0003אף תפילין נשים פטורות,\u0004 שהרי נאמרו הדברים בתורה בסמיכות זה לזה.","ומקשים: ולמה לא נאמר להיפך, \u0003ונקיש\u0004 \u0005[ונשווה]\u0006 \u0003תפילין למזוזה,\u0004 שאף היא נזכרת באותה פרשה, ובה גם נשים חייבות ונחייב את הנשים גם בתפילין! ומשיבים: \u0003תפילין לתלמוד תורה איתקיש\u0004 \u0005[\u0006נסמך, \u0005הושווה]\u0006 \u0003בין בפרשה ראשונה בין בפרשה שניה\u0004 של קריאת שמע, ואילו \u0003תפילין למזוזה בפרשה שניה לא איתקיש\u0004 \u0005[הוקש],\u0006 ולפיכך עדיף ההיקש מתלמוד תורה לתפילין.","ואומרים: אם כן \u0003ונקיש\u0004 \u0005[ונשווה]\u0006 \u0003מזוזה לתלמוד תורה\u0004 ונאמר שנשים פטורות אף ממזוזה! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במצות מזוזה: \u0003\"למען ירבו ימיכם\"\u0004 (דברים יא, כא), וכי \u0003גברי בעי חיי, נשי לא בעי חיי\u0004 \u0005[גברים צריכים חיים\u0006 ואילו \u0005נשים אינן צריכות חיים]?!\u0006 ומכאן שהמזוזה היא מצוה לכל.","ומקשים עוד: \u0003והרי\u0004 מצות ישיבה ב\u0003סוכה\u0004 ש\u0003מצות עשה שהזמן גרמא\u0004 היא, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"בסכת תשבו שבעת ימים\"\u0004 (ויקרא כג, מב) ומצוה זו חלה רק בזמן מסויים בשנה, ובכל זאת \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא לפטור את הנשים ממצוה זו משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 באותו ענין \"כל \u0003האזרח\u0004 בישראל ישבו בסוכות\" ולמדו מן הכתוב \u0003להוציא\u0004 (למעט) \u0003את הנשים, הא לאו הכי\u0004 \u0005[הרי לולא כן]\u0006 היינו סבורים כי \u0003נשים חייבות,\u0004 משמע שלא כל מצות עשה שהזמן גרמא נשים פטורות ממנה!","\u0003אמר אביי:\u0004 לענין סוכה \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 מקרא מיוחד זה לפטור נשים ממצות ישיבה בסוכה, שאילמלא הוא \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"בסכת תשבו\"\u0004 היינו למדים שלכל ענין \u0003\"תשבו\" כעין תדורו,\u0004 שישיבה זו בסוכה צריכה להיות כדרך שאדם נמצא בדירתו, ונאמר: \u0003מה דירה\u0004 דרים בה יחד \u0003איש ואשתו\u0004 — \u0003אף סוכה\u0004 יהיו חייבים בה \u0003איש ואשתו\u0004 יחד, על כן בא \"האזרח\" כדי למעט את האשה מחיוב זה.","\u0003ורבא אמר:\u0004"],["\u0003איצטריך\u0004 \u0005[הוצרך]\u0006 מקרא זה להיאמר, מטעם אחר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה דעתך לומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה יום \u0003\"חמשה עשר\"\u0004 (בתשרי) האמור בחג הסוכות (ויקרא כג, לד) מיום \u0003\"חמשה עשר\"\u0004 (בניסן), היינו \u0003מחג המצות\u0004 (שם, ו), ונאמר כי \u0003מה להלן\u0004 בפסח \u0003נשים חייבות\u0004 במצות אכילת מצה — \u0003אף כאן נשים חייבות\u0004 בסוכה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 היה להיאמר במפורש \"האזרח\", להוציא את הנשים.","ומקשים עוד: \u0003והרי\u0004 חובת \u0003ראיה\u0004 להביא קרבן עולה ברגל, ש\u0003מצות עשה שהזמן גרמא\u0004 היא \u0003וטעמא\u0004 \u0005[והטעם]\u0006 לפטור את הנשים ממצוה זו דווקא משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 במצות ראיה \"שלש פעמים בשנה ייראה כל \u0003זכורך\u0004 אל פני האדון ה'\" (שמות כג, יז) — \u0003להוציא הנשים, הא לאו הכי\u0004 \u0005[הרי לולא כן]\u0006 הייתי אומר ש\u0003נשים חייבות\u0004 על אף שזו מצות עשה שהזמן גרמא!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר גם כאן, ולא די בכך שזו מצוה התלויה בזמן, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה \u0003ראיה ראיה מ\u0004מצות \u0003הקהל,\u0004 שכתוב בהקהל \"בבוא כל ישראל לראות את פני ה'\" (דברים לא, יא) וכמו שבהקהל נשים חייבות — גם במצות ראיה ברגל תהיינה נשים חייבות, לכן צריך היה להדגיש שהן פטורות ממצות ראיה.","על ההוכחה העיקרית לכלל שנשים פטורות ממצוות עשה התלויות בזמן, שואלים: \u0003ואדילפינן\u0004 \u0005[ועד שאנו למדים]\u0006 \u0003מתפילין לפטורא\u0004 \u0005[לפטור]\u0006 את הנשים מכל מצוות עשה שהזמן גרמא, \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003מ\u0004מצות \u0003שמחה\u0004 ברגל שהוזכרה לעיל שנשים חייבות בה \u0003לחיובא\u0004 \u0005[לחיוב]\u0006 הנשים בכל המצוות האלה. \u0003אמר אביי:\u0004 גם במצות שמחה אין החובה על האשה עצמה, אלא \u0003אשה בעלה משמחה\u0004 שהמצוה מוטלת איפוא עליו ולא עליה.","ושואלים: ב\u0003אלמנה מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שהרי אין לה בעל ובכל זאת היא חייבת בשמחה ככתוב \"ושמחת לפני ה' אלהיך אתה... והאלמנה\" (דברים טז, יא)? ומשיבים גם באלמנה אין החובה עליה אלא \u0003ב\u0004אותו אדם שהיא \u0003שרויה\u0004 (נמצאת) \u0003אצלו,\u0004 שעליו מוטלת החובה לשמחה.","ושואלים: ובכל זאת \u0003ונילף\u0004 \u0005[ונלמד]\u0006 לחייב את הנשים בכל מצוות עשה שהזמן גרמא \u0003מ\u0004מצות \u0003הקהל\u0004 שהחובה מוטלת במפורש גם על הנשים למרות שזו מצות עשה שהזמן גרמא! ומשיבים: אין הדבר ניתן ללמוד משם, \u0003משום דהוה\u0004 \u0005[שהיו]\u0006 \u0003מצה והקהל שני כתובים הבאים כאחד,\u0004 שבשניהם נאמר דבר אחד — שנשים חייבות למרות שהם מצוות עשה שהזמן גרמא — \u0003ו\u0004כלל הוא: \u0003כל שני כתובים הבאין כאחד\u0004 — \u0003אין מלמדים\u0004 על הכלל כולו ואנו רואים אותם כהדגשה של היוצאים מן הכלל, לומר שהכלל אינו דומה לפרטים אלה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, הרי \u0003תפילין וראיה נמי\u0004 \u0005[גם כן]\u0006 הרי הם \u0003שני כתובים הבאים כאחד\u0004 שאומרים דבר אחד — שנשים פטורות ממצות עשה שהזמן גרמא, \u0003ו\u0004לפיכך \u0003אין מלמדים!\u0004 ומשיבים: אין זה בכלל שני כתובים הבאים כאחד כי \u0003צריכי\u0004 \u0005[נצרכים]\u0006 שניהם להיאמר, כל אחד לעצמו; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 שנשים פטורות רק ממצות \u0003תפילין ולא כתב\u0004 \u0005[היתה כותבת]\u0006 שפטורות ממצות \u0003ראיה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה מצות \u0003ראיה\u0004 ברגל ממצות \u0003ראיה\u0004 ב\u0003הקהל\u0004 לחייב את הנשים בראיה ברגל, ולכן היה צריך לכתוב שנשים פטורות מראיה.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 פטור נשים רק ב\u0003ראיה ולא כתב\u0004 \u0005[היתה כותבת]\u0006 פטור הנשים ממצות \u0003תפילין, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אקיש\u0004 \u0005[הקש]\u0006 \u0003תפילין למזוזה,\u0004 ותתחייבנה נשים בתפילין כפי שחייבות במזוזה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים ואין לראותם כ\"שני כתובים הבאים כאחד\" שאינם מלמדים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה דן, \u0003מצה והקהל נמי צריכי\u0004 \u0005[גם כן צריכים]\u0006 להיאמר כל אחד לעצמו ואף הן אינן בכלל שני כתובים הבאים כאחד? ודוחים: \u0003למאי צריכי\u0004 \u0005[למה יש צורך\u0006 בשניהם\u0005]?\u0006 \u0003בשלמא אי כתב רחמנא\u0004 \u0005[נניח אם היתה כותבת התורה]\u0006 חיוב נשים ב\u0003הקהל ולא כתב\u0004 \u0005[היתה כותבת]\u0006 ב\u0003מצה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"חמשה עשר\" \"חמשה עשר\" מחג הסוכות\u0004 ונפטור נשים ממצה, על כן צריך לימוד מיוחד לחייב נשים במצה.","\u0003אלא ניכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003מצה\u0004 בלבד, \u0003ולא בעי\u0004 \u0005[צריך]\u0006 לכתוב דין זה ב\u0003הקהל, ואנא אמינא\u0004 \u0005[ואני\u0006 הייתי \u0005אומר]\u0006 מעצמי: אם \u0003טפלים\u0004 (טף) \u0003חייבים\u0004 בהקהל כפי שנאמר במפורש, \u0003נשים לא כל שכן?! הילכך\u0004 (על כן) כיון שלמרות זאת נאמר במפורש חיוב נשים בהקהל, \u0003הוה להו\u0004 \u0005[הריהם]\u0006 \u0003שני כתובים הבאים כאחד, ואין מלמדים.\u0004","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ככלל כי שני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר מלמדין מאי איכא למימר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 ששני כתובים הבאים כאחד \u0005מלמדים מה יש לומר]?\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003זה שב\u0004\u0003מצות עשה שלא הזמן גרמא נשים חייבות מנלן\u0004 \u0005[מניין לנו]?\u0006 ועונים: \u0003דיליף\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 דבר זה \u0003ממורא\u0004 אב ואם, \u0003מה\u0004 מצות \u0003מורא נשים חייבות\u0004 בה — \u0003אף כל מצות עשה שלא הזמן גרמא נשים חייבות\u0004 בה.","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 להיפך \u0003מתלמוד תורה,\u0004 שכמו שבתלמוד תורה נשים פטורות — כך תהיינה פטורות מכל מצוות עשה שאינן תלויות בזמן! ומשיבים: \u0003משום דהוה ליה\u0004 \u0005[שהיו להם]\u0006 \u0003תלמוד תורה ופריה ורביה שני כתובים הבאים כאחד,\u0004 שנאמר בהם שנשים פטורות ממצוות עשה אלה למרות שאין הזמן גרמן, \u0003וכל שני כתובים הבאים כאחד אין מלמדים.\u0004"],["\u0003ול\u0004דעת \u0003ר' יוחנן בן ברוקא,\u0004 ש\u0003אמר: על שניהם,\u0004 גם על האיש וגם על האשה, \u0003הוא\u0004 (הפסוק) \u0003אומר \"ויברך אתם אלהים\u0004 ויאמר להם אלהים \u0003פרו ורבו\u0004 ומלאו את הארץ וכבשוה\u0003\"\u0004 (בראשית א, כח) ולדעתו גם הנשים מצוות על פריה ורביה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שהרי יש כאן רק כתוב אחד, תלמוד תורה, ואם כן אפשר היה ללמוד ממנו לפטור נשים מכל מצוות עשה שלא הזמן גרמא! ומשיבים: \u0003משום דהוה\u0004 \u0005[שהיה]\u0006 \u0003תלמוד תורה ופדיון הבן\u0004 שנשים פטורות מהם \u0003שני כתובים הבאים כאחד, וכל שני כתובים הבאים כאחד אין מלמדין.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' יוחנן בן ברוקא נמי\u0004 \u0005[גם כן]\u0006 \u0003ניהוו\u0004 \u0005[שיהיו]\u0006 \u0003פריה ורביה\u0004 שנשים מצוות בהם \u0003ומורא\u0004 אב ואם \u0003שני כתובים הבאים כאחד ואין מלמדין!\u0004 ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 שני הדברים להיאמר; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק חיוב נשים ב\u0003מורא, ולא כתב\u0004 \u0005[היתה כותבת]\u0006 החיוב ב\u0003פריה ורביה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003\"\u0004פרו ורבו ומילאו את הארץ \u0003וכבשה\"\u0004 (שם) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 והייתי לומד כחכמים שנשים פטורות כי \u0003א\u0004 \u0003יש\u0004 ש\u0003דרכו\u0004 לצאת למלחמה ו\u0003לכבש\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב במצוה זו, \u0003אשה\u0004 ש\u0003אין דרכה לכבש\u0004 — \u0003לא.\u0004","\u0003ואי כתב\u0004 \u0005[ואילו היתה כותבת]\u0006 התורה רק ב\u0003פריה ורביה ולא כתב\u0004 \u0005[היתה כותבת]\u0006 ב\u0003מורא, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003איש\u0004 ש\u0003סיפק\u0004 (שאפשרות) \u0003בידו לעשות\u0004 שאין אימת אחרים עליו — \u0003אין\u0004 \u0005[כן]\u0006 חייב במורא אב ואם, \u0003אשה\u0004 ש\u0003אין סיפק בידה לעשות\u0004 כיון שהיא נשואה ומורא בעלה עליה — \u0003לא, וכיון\u0004 ש\u0003אין סיפק בידה לעשות\u0004 כשהיא נשואה \u0003לא תתחייב כלל\u0004 במצות כיבוד ואפילו כאשר היא פנויה, שאין לחלק ביניהן, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו הדברים בשני המקרים, ומשום כך אינם נחשבים לשני כתובים הבאים כאחד שאינם מלמדים.","ואולם עדיין עומדת בעינה שאלה קודמת: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שני כתובים הבאים כאחד אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי נוכל לחייב נשים במצוות עשה שהזמן גרמן ממצה והקהל, ולפוטרן ממצות עשה שלא הזמן גרמן מתלמוד תורה ופדיון הבן! \u0003אמר רבא: פפונאי ידעי לה לטעמא דהא מילתא\u0004 \u0005[\u0006חכמי \u0005פפוניא יודעים את טעמו של דבר זה].\u0006","ומעירים: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 שרמז לו רבא בכינוי זה — \u0003רב אחא בר יעקב,\u0004 שאמר כך: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והיה לך לאות על ידך ולזכרון בין עיניך למען תהיה תורת ה' בפיך\"\u0004 (שמות יג, ט), ובפסוק זה \u0003הוקשה\u0004 (הושוותה) \u0003כל התורה כולה לתפילין; מה תפילין\u0004 היא \u0003מצות עשה שהזמן גרמא, ונשים פטורות\u0004 ממנה — \u0003אף כל מצות עשה שהזמן גרמא\u0004 בכל התורה כולה — \u0003נשים פטורות. ומ\u0004כיון ש\u0003מצות עשה שהזמן גרמא נשים פטורות\u0004 ממנה — \u0003מכלל\u0004 הדברים אתה למד שבכל \u0003מצות עשה שלא הזמן גרמא נשים חייבות.\u0004","ועל כך מקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שמצות \u0003תפילין\u0004 היא \u0003מצות עשה שהזמן גרמא, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003תפילין מצות עשה שלא הזמן גרמא\u0004 היא, שלדעתו חיוב תפילין נוהג בכל השנה כולה, יום ולילה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי שמעת אותו ש\u0006הוא \u0005אומר]\u0006 ש\u0003תפילין מצות עשה שלא הזמן גרמא\u0004 היא — \u0003ר' מאיר\u0004 הוא, \u0003וסבר לה\u0004 \u0005[וסבור הוא]\u0006 שהם \u0003שני כתובים הבאים כאחד, וכל שני כתובים הבאים כאחד אין מלמדין.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' יהודה\u0004 ש\u0003אמר: שני כתובים הבאים כאחד מלמדין, ו\u0004הוא אומר ש\u0003תפילין מצות עשה שלא הזמן גרמא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003משום דהואי\u0004 \u0005[שהיו]\u0006 \u0003מצה, שמחה, והקהל שלשה כתובים הבאים כאחד, ו\u0004לדעת הכל \u0003שלשה כתובים הבאים כאחד אין מלמדין.\u0004","עוד שנינו במשנה: \u0003וכל מצות לא תעשה\u0004 נשים חייבות בה, בין שהזמן גרמא בין שלא הזמן גרמא. ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר רב יהודה אמר רב וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב]\u0006 לענין קרבן אשם \u0003\"איש או אשה כי יעשו מכל חטאת האדם\"\u0004 (במדבר ה, ו) — \u0003השוה הכתוב\u0004 בפסוק זה \u0003אשה לאיש לכל עונשים שבתורה,\u0004 שהרי הוצרכה גם האשה להביא קרבן לכפרה.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר תנא\u0004 \u0005[שנה\u0006 כך\u0005]:\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004ואלה המשפטים \u0003אשר תשים לפניהם\"\u0004 (שמות כא, א) בלשון רבים, ובפסוק הזה \u0003השוה הכתוב אשה לאיש לכל דינים,\u0004 דיני ממונות ונזיקין, \u0003שבתורה. דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנה]:\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והמית איש או אשה\"\u0004 (שם, כט), \u0003השוה הכתוב\u0004 בפסוק זה \u0003אשה לאיש לכל מיתות שבתורה,\u0004 לומר שההורג אותם דינו שווה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שלושה כתובים הללו; \u0003דאי אשמעינן הך קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק את \u0005זו הראשונה]\u0006 לענין חיוב האשה בקרבנות, הייתי אומר כי \u0003משום כפרה חס רחמנא עלה\u0004 \u0005[חסה התורה עליה]\u0006 ונתנה לה אפשרות להתכפר על ידי קרבן, \u0003אבל\u0004 ב\u0003דינין\u0004 של ממונות \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003איש דבר\u0004 \u0005[ש\u0006הוא \u0005בן]\u0006 \u0003משא ומתן\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 שייכים בו דינים אלה, אבל \u0003אשה\u0004 — \u0003לא. ו\u0004כן","\u0003אי אשמועינן הא\u0004 \u0005[ואם היה משמיע לנו\u0006 דבר \u0005זה]\u0006 רק בדינים, הייתי אומר שאשה שייכת בדינים הללו \u0003משום דחיותה היא\u0004 \u0005[שחייה הוא],\u0006 שלצורך משא ומתן ופרנסה צריכה גם היא להיות כלולה בדיני ממונות, \u0003אבל כופר\u0004 שמשלמים עבור מי שבהמתו הרגה את הנפש \u0003אימא\u0004 \u0005[אמור]:\u0006"],["\u0003איש דבר\u0004 \u0005[ש\u0006הוא \u0005בן]\u0006 \u0003מצות\u0004 שמצווה בכל המצוות — \u0003אין\u0004 \u0005[כן]\u0006 צריך לשלם על הריגתו כופר, ואולם \u0003אשה\u0004 — \u0003לא.\u0004 ולהיפך: \u0003ואי אשמעינן הא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005זאת]\u0006 בכופר, היינו אומרים: \u0003משום דאיכא\u0004 \u0005[שיש\u0006 כאן\u0005]\u0006 \u0003איבוד נשמה חס רחמנא עלה\u0004 \u0005[חסה התורה עליה]\u0006 וחייבה את הגורם לנזק לשלם כופר, \u0003אבל הנך תרתי\u0004 — \u0003אימא\u0004 \u0005[אבל אותן השתים\u0006 האחרות \u0005אמור]\u0006 ש\u0003לא\u0004 תשווה את האשה לאיש, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם.","שנינו במשנה שנשים חייבות בכל מצוות לא תעשה \u0003חוץ מ\"בל תקיף\" ו\"בל תשחית\"\u0004 ו\"בל תטמא למתים\". ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003\"בל תטמא למתים\"\u0004 אין אשה כהנת חייבת, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"אמר אל הכהנים בני אהרן\u0004 ואמרת אליהם לנפש לא ייטמא בעמיו\u0003\"\u0004 (ויקרא כא, א), שיש בכתוב הדגשה: \u0003בני אהרן\u0004 — \u0003ולא בנות אהרן. אלא \"בל תקיף\" ו\"בל תשחית\" מנלן\u0004 \u0005[מניין לנו]\u0006 שאינן חייבות בהן?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תקפו פאת ראשכם ולא תשחית את פאת זקנך\"\u0004 (שם יט, כז), וההיקש בין שני האיסורים בא ללמד: \u0003כל\u0004 מי \u0003שישנו ב\u0004איסור \u0003השחתה\u0004 של הזקן — \u0003ישנו ב\u0004איסור \u0003הקפה\u0004 של הראש, \u0003והני נשי\u0004 \u0005[ונשים אלה]\u0006 \u0003הואיל ולא איתנהו\u0004 \u0005[ואינן]\u0006 \u0003ב\u0004איסור \u0003השחתה, ליתנהו\u0004 \u0005[אינן]\u0006 גם \u0003ב\u0004איסור \u0003הקפה.\u0004","ושואלים: \u0003ומנלן דלא איתנהו\u0004 \u0005[ומניין לנו שאינן]\u0006 \u0003ב\u0004איסור \u0003השחתה?\u0004 ומשיבים: \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 מצד ה\u0005סברה]\u0006 — \u0003דהא לא אית להו\u0004 \u0005[שהרי\u0006 בסתם \u0005אין להן]\u0006 לנשים \u0003זקן. ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור כתוב]\u0006 המלמד אותנו על כך — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תקפו פאת ראשכם ולא תשחית את פאת זקנך\"\u0004","\u0003מדשני קרא בדיבוריה\u0004 \u0005[מ\u0006כיון \u0005ששינה הכתוב בדיבורו],\u0006 שבתחילה דיבר בלשון רבים ואחר כך בלשון יחיד, בא הדבר ללמדנו: ש\u0003אם כן\u0004 שמצות השחתת הזקן הריהי לכל — ראוי היה ש\u0003ניכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"\u0004ולא תשחיתו את \u0003פאת זקנכם\",\u0004 ויהיה סוף הפסוק בדומה לראשית הפסוק בסגנונו. \u0003מאי\u0004 \u0005[מדוע]\u0006 שינה הכתוב ונקט \u0003\"זקנך\"\u0004 בלשון יחיד — למיעוט: \u0003זקנך ולא זקן אשתך.\u0004","ושואלים: \u0003ולא?\u0004 האם אין זקן האשה נחשב לזקן? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זקן אשה, ו\u0004כן \u0003הסריס שהעלו שער\u0004 זקן — \u0003הרי הן כזקן לכל דבריהם. מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר הדבר \u0003ל\u0004ענין איסור \u0003השחתה?\u0004","\u0003אמר אביי: להשחתה לא מצית אמרת\u0004 \u0005[אינך יכול לומר]\u0006 שנתכוונה הברייתא \u0003דיליף\u0004 \u0005[ש\u0006הרי \u0005לומד]\u0006 בגזירה שווה \u0003\"פאת\u0004 זקנך\u0003\"\u0004 (ויקרא יט, כז) \u0003\"פאת\u0004 זקנם\u0003\"\u0004 (ויקרא כא, ה) \u0003מ\"בני אהרן\": מה להלן\u0004 המצוה שנאמרה בכהנים ודאי \u0003נשים פטורות,\u0004 שהרי מצוות הכהנים נאמרו רק לבני אהרן המשמשים בכהונה ולא לנשים — \u0003אף כאן\u0004 באיסור השחתת הזקן שנאמר לכל ישראל \u0003נשים פטורות.\u0004","ומקשים: \u0003ואי סבירא לן\u0004 \u0005[ואם\u0006 אכן \u0005סבורים אנו]\u0006 \u0003דכי כתב\u0004 \u0005[שכאשר נאמר]\u0006 באותו ענין \u0003\"בני אהרן\"\u0004 — \u0003אכוליה ענינא כתיב\u0004 \u0005[על כל הענין נאמר]\u0006 וגם על איסור השחתת הזקן, אם כן \u0003נישתוק קרא מיניה\u0004 \u0005[שישתוק הכתוב ממנו]\u0006 ולא ייאמר כלל האיסור לכל ישראל, \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003בקל וחומר, ואנא אמינא\u0004 \u0005[ו\u0006כך \u0005הייתי אומר]:\u0006 \u0003ומה כהנים שריבה בהם הכתוב מצות יתירות\u0004 ובכל זאת באיסור השחתה דייקנו שדווקא \u0003בני אהרן ולא בנות אהרן\u0004 — \u0003ישראל\u0004 שיש להם פחות מצוות \u0003לא כל שכן\u0004 שרק הגברים חייבים ונשים פטורות?","ומשיבים: בכל זאת צריכים לגזירה שווה, כי \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היתה \u0003גזירה שוה הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דין טומאה \u0003הפסיק הענין,\u0004 שדין הטומאה הקודם בפרשת הכהנים לשאר הדינים רק הוא נאמר ל\"בני אהרן\" אבל שאר הדינים האמורים בפרשה זו ובכלל זה איסור השחתת זקן מתייחסים גם לנשים.","ושואלים: אם כן \u0003השתא נמי נימא\u0004 \u0005[עכשיו גם כן נאמר]\u0006 כי באמת \u0003הפסיק הענין\u0004 וגם בנות אהרן אסורות בהשחתת זקן! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום גזירה שוה\u0004 שבאה להשוות דין זה בכהנים ובכל ישראל — \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 הגזירה שווה לענין אחר, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בכהנים \u0003\"\u0004ופאת זקנם \u0003לא יגלחו\"\u0004 (ויקרא כא, ה) \u0003יכול\u0004 שגם אם \u0003גילחו\u0004 את הזקן \u0003במספריים יהיה חייב? תלמוד לומר:\u0004 בצווי לכל ישראל \"ו\u0003לא תשחית\u0004 את פאת זקנך\" (שם יט, כז), לומר: אין חייבים אלא על השחתת הזקן עד השורש דבר שאינו נעשה בגילוח במספריים.","ולהיפך: \u0003יכול\u0004 אם \u0003לקטו\u0004 (הוציאו) \u0003במלקט\u0004 שתולש את השערות, או \u0003ברהיטני\u0004 (מעין מקצוע) שיש בהם השחתה \u0003יהא חייב\u0004 — \u0003תלמוד לומר:\u0004 בציווי לכהנים \u0003\"לא יגלחו\"\u0004 ובאלו אין דרך גילוח. \u0003הא כיצד\u0004 מצרפים את הדברים? אין האיסור אלא ב\u0003גילוח שיש בה השחתה, הוי אומר זה\u0004 גילוח על ידי \u0003תער.\u0004 ואם כן, הגזירה שווה נחוצה לבאר מהו איסור השחתה, ולא לדברים אחרים.","ומשיבים: \u0003אם כן\u0004 שרק לצורך זה נכתב הדבר, \u0003ניכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"את שבזקנך\", מאי\u0004 \u0005[מה]\u0006 טעם הרחבת הלשון \u0003\"פאת זקנך\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים]\u0006 גם לענין איסור הגילוח וגם לפטור נשים.","וחוזרים לעיקר הקושיה על המשנה: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003זקן האשה והסריס שהעלו שער הרי הן כזקן לכל דבריהם,\u0004 אם כן לא מדובר על איסור השחתה שהם פטורים ממנו אזי \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמרה? \u0003אמר מר זוטרא: לטומאת נגעים.\u0004 כלומר, שנגע צרעת שהיה בזקן האשה והסריס נידון כנגע בזקן, ולא כנגע בעור.","ומקשים: \u0003טומאת נגעים בהדיא כתיבא\u0004 \u0005[במ\u0006 \u0005פורש נאמרה]\u0006 באשה, שהרי נאמר \u0003\"ואיש או אשה כי יהיה בו נגע בראש או בזקן\"\u0004 (שם יג, כט), משמע שאין חילוק בין איש לאשה גם לגבי זקן! \u0003אלא אמר מר זוטרא:\u0004 ברייתא זו באה \u0003ל\u0004למדנו \u0003טהרת נגעים\u0004 שאף הנשים נטהרות מצרעת הזקן.","ומקשים: \u0003טהרת נגעים נמי פשיטא\u0004 \u0005[גם כן פשוט\u0006 הדבר\u0005],\u0006 \u0003כיון\u0004 ש\u0003בת טומאה היא\u0004 — \u0003בת טהרה היא!\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר לגבי טומאת נגעים שבזקן כי \u0003סלקא דעתך אמינא לצדדים כתיב\u0004 \u0005[יעלה על דעתך לומר\u0006 שהפסוק הזה \u0005כתוב ל\u0006שני \u0005צדדים]:\u0006 \u0003\"איש או אשה כי יהיה בו נגע בראש\"\u0004 הרי זה בשניהם באיש או באשה, ואילו במילים \u0003\"או בזקן\"\u0004 — \u0003הדר אתאן\u0004 \u0005[חזרנו\u0006 ו\u0005באנו]\u0006 \u0003ל\u0004דין \u0003איש\u0004 בלבד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא נלמד \"לצדדים\" ואף לענין נגעים אין חילוק בין איש לאשה.","\u0003איסי תני\u0004 \u0005[היה שונה\u0006 בברייתא\u0005]:\u0006 \u0003אף\u0004 האיסור של \u0003\"בל יקרחו\u0004 קרחה בראשם\u0003\"\u0004 (ראה ויקרא כא, ה) \u0003נשים פטורות.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003איסי דדריש הכי\u0004 \u0005[שדורש כך]?\u0006 ומשיבים: נאמר \u0003\"בנים אתם לה' אלהיכם לא תתגדדו ולא תשימו קרחה בין עיניכם למת. כי עם קדוש אתה לה' אלהיך\"\u0004 (דברים יד, א–ב), כיון שנאמר שם \u0003בנים ולא בנות\u0004 הרי זה \u0003ל\u0004ענין \u0003קרחה\u0004 שאין חיוב זה אלא בגברים בלבד.","ודנים: \u0003אתה אומר\u0004 בנים ולא בנות \u0003לקרחה, או אינו אלא ל\u0004איסור \u0003גדידה\u0004 האמור בתחילת הפסוק? ומשיבים: \u0003כשהוא אומר\u0004 בפסוק הבא \u0003\"כי עם קדוש אתה לה' אלהיך\"\u0004 — \u0003הרי\u0004 איסור \u0003גדידה אמור\u0004 גם לגבי גברים וגם לגבי נשים, שכולם שייכים לעם ה', \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 את ההדגשה \u0003בנים ולא בנות\u0004 — \u0003לקרחה.\u0004","ומקשים: \u0003ומה ראית לרבות את הגדידה ולהוציא את הקרחה?\u0004 שמא תאמר להיפך! ומשיבים: \u0003מרבה אני את הגדידה\u0004 שאיסורה רחב יותר, \u0003שישנה\u0004 אפשרות לעבור עליה בין שעושה אותה \u0003במקום השער ו\u0004בין \u0003שלא במקום שער, ומוציא אני את הקרחה\u0004 שאיסורה מצומצם יותר \u0003שאינה\u0004 מתקיימת \u0003אלא במקום שער.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003בנים ולא בנות בין לקרחה בין לגדידה, וכי כתב\u0004 \u0005[וכאשר נאמר]\u0006 \u0003\"כי עם קדוש אתה לה' אלהיך\"\u0004 שמשמעו, בין גברים ובין נשים — \u0003בשריטה הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ששריטה על המת אסורה לכל?! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003איסי\u0004 כי \u0003שריטה וגדידה\u0004"],["\u0003אחת היא\u0004 ואותו איסור הוא בשתיהן.","\u0003אביי אמר\u0004 באופן אחר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003איסי\u0004 הפוטר נשים מאיסור קרחה: \u0003דגמר\u0004 \u0005[שלמד]\u0006 בגזירה שוה \u0003\"קרחה\" \"קרחה\" מבני אהרן\u0004 שנאמר בהם \"לא יקרחו קרחה בראשם\" (ויקרא כא, ה); \u0003מה להלן\u0004 בבני אהרן \u0003נשים פטורות\u0004 שהרי אנו מדייקים: \"בני אהרן\" ולא בנות אהרן — \u0003אף כאן נשים פטורות.\u0004","ומקשים: \u0003ואי סבירא לן דכי כתיב קרא, בכולי עניינא הוא דכתיב\u0004 \u0005[ואם אנו סבורים שכאש\u0006 \u0005ר נאמר הכתוב\u0006 \"בני אהרן\" \u0005בכל הענין הוא שנאמר],\u0006 שכל הדינים האמורים בפרשה זו אלא לבני אהרן — לגברים ולא לנשים — אם כן \u0003נשתוק קרא מיניה\u0004 \u0005[שישתוק,\u0006 שיתעלם, \u0005הכתוב ממנו]\u0006 בישראל, ולא ייכתב פסוק זה הממעט נשים מאיסור קרחה, \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006 ההלכה \u0003בקל וחומר, ואנא אמינא\u0004 \u0005[ו\u0006כך \u0005הייתי אומר]:\u0006 \u0003ומה כהנים שריבה בהם הכתוב מצות יתירות\u0004 בכל זאת לענין קרחה דווקא \u0003בני אהרן ולא בנות אהרן, ישראל\u0004 שאין בהם ריבוי מצוות זה \u0003לא כל שכן\u0004 שדווקא גברים חייבים ונשים פטורות?","ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003גזרה שוה\u0004 זו \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הפסיק הענין\u0004 לאחר דיני טומאה, ושאר הדברים נאמרו גם לבנות אהרן.","ושואלים: אם כן \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003נימא\u0004 \u0005[נ אמר]\u0006 ש\u0003הפסיק הענין\u0004 ובאמת אינו מוגבל רק לגברים, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום גזרה שוה\u0004 — \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמוד גזירה שווה זו לענין אחר, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"לא יקרחו\", יכול אפילו קרח ארבע וחמש קרחות לא יהא חייב אלא אחת,\u0004 שהרי יש רק איסור אחד של קריחה, \u0003תלמוד לומר: \"קרחה\", לחייב על כל אחת ואחת\u0004 מהן, שהיא קרחה לעצמה.","\u0003\"בראשם\"\u0004 האמור לגבי איסור קריחה \u0003מה תלמוד לומר?\u0004 — \u0003לפי שנאמר: \"לא תתגדדו ולא תשימו קרחה בין עיניכם למת\"\u0004 (דברים יד, א), \u0003יכול לא יהא חייב אלא על\u0004 קריחת שיער ש\u0003בין העינים\u0004 בלבד, \u0003מנין לרבות כל הראש\u0004 ולאו דווקא בין העיניים — \u0003תלמוד לומר: \"בראשם\", לחייב על\u0004 כל \u0003הראש כ\u0004על \u0003בין העינים.\u0004","\u0003ואין לי\u0004 דין זה \u0003אלא\u0004 ב\u0003כהנים, שריבה בהם הכתוב מצות יתירות, ישראל מנלן\u0004 \u0005[מניין לנו]\u0006 שגם בהם נוהגות הלכות אלו לחייב על כל קרחה וקרחה, ועל כל הראש? — \u0003נאמר כאן\u0004 בכהנים \u0003\"קרחה\" ונאמר להלן\u0004 בישראל \u0003\"קרחה\", מה כאן\u0004 בכהנים \u0003חייב על כל קרחה וקרחה, וחייב על הראש כבין העינים\u0004 — \u0003אף להלן\u0004 בישראל \u0003חייב על כל קרחה וקרחה, וחייב על הראש כבין העינים. ו\u0004כן להיפך:","\u0003מה להלן\u0004 בישראל מפורש שמדובר בקרחה \u0003על מת, אף כאן\u0004 בכהנים אין קריחה אסורה אלא \u0003על מת\u0004 ולא במקרה אחר. ואם כן הגזירה השווה נחוצה ללמד את עצם דיני הקרחה, ומדוע אנו אומרים שהיא באה לענין נשים? ומשיבים: \u0003אם כן\u0004 שרק לצורך זה היה הכתוב \u0003נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"קרח\", מאי\u0004 \u0005[מהי]\u0006 לשון \u0003\"קרחה\"\u0004 — \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שתים]\u0006 גם לגזירה שווה, למעט נשים, וגם לריבוי לכל קרחה לעצמה.","\u0003רבא אמר\u0004 באופן אחר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003איסי\u0004 — \u0003דיליף\u0004 \u0005[שלומד]\u0006 בגזירה שווה \u0003\"בין עיניכם\" מתפילין,\u0004 שנאמר בהן \"לטוטפות בין עיניכם\" (דברים יא, יח), \u0003מה להלן\u0004 בתפילין — \u0003נשים פטורות, אף כאן\u0004 בקרחה \u0003נשים פטורות.\u0004 ושואלים: \u0003ורבא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כאביי?\u0004 ומשיבים: ההבדל בין \u0003\"קרח\"\u0004 ל\u0003\"קרחה\" לא משמע ליה\u0004 \u0005[נשמע,\u0006 נראה \u0005לו]\u0006 שאינו סבור שאפשר ללמוד הלכה משינוי לשון זה.","ושואלים: \u0003ואביי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבא?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה אביי \u0005לומר]\u0006 \u0003לך: תפילין גופייהו מהכא גמר לה\u0004 \u0005[עצמם מכאן\u0006 הוא \u0005לומד],\u0006 שאת משמעות \"בין עיניכם\" האמור בתפילין למדים מקרחה: \u0003מה להלן\u0004 לגבי קרחה \"בין עיניכם\" הוא \u0003מקום שעושים קרחה\u0004 כלומר במקום שיש שערות, והוא \u0003בגובהה\u0004 (בחלק העליון) \u0003של ראש\u0004 ולא ממש בין העיניים, \u0003אף כאן מקום הנחה\u0004 של התפילין הריהו \u0003בגובה הראש.\u0004","ושואלים: \u0003ובין לאביי ובין לרבא האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"בנים אתם\",\u0004 שלמדו ממנו לפי ההסבר הראשון לדעת איסי להוציא נשים, \u0003מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו],\u0006 כיון שהם למדים הלכה זאת ממקור אחר? ומשיבים: \u0003האי מיבעי לכדתניא\u0004 \u0005[זה נצרך לכפי\u0006 \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"בנים אתם לה' אלהיכם\"\u0004 בא לומר: \u0003בזמן שאתם נוהגים מנהג בנים\u0004 ודבקים בקדוש ברוך הוא — \u0003אתם קרוים בנים,\u0004 ובזמן ש\u0003אין אתם נוהגים מנהג בנים\u0004 — \u0003אין אתם קרוים בנים,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' מאיר אומר: בין כך ובין כך\u0004 עדיין \u0003אתם קרוים בנים, שנאמר: \"בנים סכלים המה\"\u0004 (ירמיה ד, כב), \u0003ואומר\u0004 גם כן: \u0003\"בנים לא אמן בם\"\u0004 (דברים לב, כ), \u0003ואומר\u0004 עוד: \u0003\"זרע מרעים בנים משחיתים\"\u0004 (ישעיה א, ד), \u0003ואומר: \"והיה במקום אשר יאמר להם לא עמי אתם יאמר להם בני אל חי\"\u0004 (הושע ב, א).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הצורך להוסיף ולהביא ראיות נוספות אלה של \u0003\"ואומר\"\u0004 לאותו דבר עצמו? ומשיבים שנצרכים הם כל הפסוקים הללו, שכן \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003סכלי הוא דמקרי בני\u0004 \u0005[\u0006כאשר הם \u0005סכלים, הם שנקראים\u0006 עדיין \u0005בנים]\u0006 כמו שנאמר \"בנים סכלים\", אבל \u0003כי לית בהו הימנותייהו\u0004 \u0005[כאשר אין בהם אמונתם]\u0006 \u0003לא מיקרו בני\u0004 \u0005[אינם נקראים בנים]\u0006 כלל — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר עוד: \u0003ואומר \"בנים לא אמן בם\",\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר\u0006 כפירכה על ההוכחה מפסוק זה\u0005]:\u0006 \u0003כי לית בהו הימנותא הוא דמיקרו\u0004 \u0005[\u0006אף \u0005כאשר אין בהם אמונה הוא שנקראים]\u0006 \u0003בנים\u0004 כאמור, אבל \u0003כי פלחו\u0004 \u0005[כאשר\u0006 הם \u0005עובדים]\u0006 \u0003לעבודה זרה לא מיקרו\u0004 \u0005[אינם נקראים]\u0006 עוד \u0003בנים\u0004 — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003ואומר \"זרע מרעים בנים משחיתים\"\u0004 ואנו יודעים שלשון \"השחתה\" היא רמז לעבודה זרה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"בנים משחיתים\" הוא דמיקרו\u0004 \u0005[שנקראים]\u0006 אבל \u0003בני מעלייא לא מיקרו\u0004 \u0005[בנים מעולים\u0006 לקדוש ברוך הוא \u0005אינם נקראים\u0006 עוד\u0005]\u0006 לאחר שחטאו — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003ואומר \"והיה במקום אשר יאמר להם לא עמי אתם יאמר להם בני אל חי\".\u0004 משמע שאינם קרויים כך (\"לא עמי\") לעולם, וכאשר הם חוזרים בתשובה חוזרים ונקראים בנים מעולים (\"בני אל חי\").","\u0003הסמיכות\u0004 שסומכים על הקרבנות, \u0003והתנופות\u0004 שצריך להניף קרבנות שונים, \u0003וההגשות\u0004 שמגישים מנחה אל קרנות המזבח, \u0003והקמיצות\u0004 שקומצים מן המנחה, \u0003והקטרות\u0004 הדברים הנשרפים על המזבח, \u0003והמליקות\u0004 של קרבן העוף, \u0003והקבלות\u0004 של דם הקרבן בכלי, \u0003והזאות\u0004 של הדם — \u0003נוהגים באנשים ולא בנשים,\u0004 שכל הדברים הללו הם מצוה על גברים בלבד ולא על הנשים. \u0003חוץ ממנחת סוטה ו\u0004מנחת \u0003נזירה שהן\u0004 (הנזירה או הסוטה) \u0003מניפות\u0004 את מנחתן.","\u0003סמיכות\u0004 מניין לנו שנוהגות רק בגברים? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"דבר אל בני ישראל... וסמך\"\u0004 (ויקרא א, ב–ד) ללמוד מן ההיקש: \u0003בני ישראל סומכים, ואין בנות ישראל סומכות.\u0004","\u0003תנופות\u0004 — שנאמר: \u0003\"דבר אל בני ישראל... והניף\"\u0004 (ראה שם ז, כט–ל), לומר: \u0003בני ישראל מניפין ואין בנות ישראל מניפות.\u0004","\u0003הגשות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזאת תורת המנחה... הקרב אתה בני אהרן\"\u0004 (שם ו, ז), לומר: \u0003בני אהרן ולא בנות אהרן.\u0004","\u0003קמיצות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והביאה אל בני אהרן\u0004 הכהנים \u0003וקמץ\"\u0004 (שם ב, ב) לומר: \u0003בני אהרן ולא בנות אהרן.\u0004","\u0003הקטרות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקטירו אתו בני אהרן\"\u0004 (שם ג, ה) לומר: \u0003בני אהרן ולא בנות אהרן.\u0004","\u0003המליקות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ומלק... והקטיר\"\u0004 (שם א, טו) \u0003איתקש\u0004 \u0005[\u0006נסמכה ו\u0005הושוותה]\u0006 בפסוק זה \u0003מליקה להקטרה,\u0004 וכשם שהקטרה נעשית רק על ידי גברים גם מליקה רק בגברים.","\u0003הקבלות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והקריבו בני אהרן\"\u0004 (שם ה) \u0003ואמר מר\u0004 \u0005[החכם]\u0006 בביאור פסוק זה:"],["\u0003\"והקריבו\" זו קבלת הדם.\u0004","על מה שנאמר במשנה \u0003והזאות\u0004 שואלים: \u0003הזאה דהיכא\u0004 \u0005[של היכן],\u0006 באיזו הזאה מדובר? \u0003אי\u0004 \u0005[אם]\u0006 זו של \u0003פרה\u0004 אדומה, הלא \u0003\"אלעזר\" כתוב בה\u0004 (במדבר יט, ד), שאותה הזאה עושה דווקא או הסגן ואפילו כהנים אחרים פסולים בה וכל שכן נשים. \u0003אי\u0004 \u0005[אם]\u0006 הזאה שעושים ב\u0003פנים,\u0004 כלומר, בקדשי הקדשים \u0003\"הכהן המשיח\" כתוב בה\u0004 (ויקרא ד, טז–יז) ואם כן שוב אין פה מקום לספק. \u0003אלא הזאה\u0004 שמזים את דם חטאת \u0003בן עוף.\u0004","\u0003דאתיא\u0004 \u0005[שבאה,\u0006 נלמדת\u0005]\u0006 \u0003בקל וחומר מבן צאן.\u0004 כיצד: \u0003ומה בן צאן שלא קבע לו כהן לשחיטתו,\u0004 שלאו דווקא כהן חייב לשוחטו אלא כל אדם רשאי לשחוט את הקרבן — בכל זאת \u0003קבע לו כהן להזאתו,\u0004 שכן נאמר \"וזרקו בני אהרן הכהנים את דמו...\" (ויקרא א, יא), אם כן \u0003בן עוף שקבע לו כהן למליקתו\u0004 שהיא העבודה המקבילה לשחיטת בן צאן — \u0003אינו דין שיקבע לו\u0004 כהן \u0003להזאתו?\u0004 ומכאן למדים שהיא דווקא בכהנים — גברים, ולא בנשים.","שנינו במשנה: \u0003חוץ ממנחת סוטה ונזירה\u0004 שאותן הנשים מניפות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר לר' יאשיה דדריה\u0004 \u0005[בן דורו],\u0006 כלומר, לאמורא ר' יאשיה, ולא לתנא בשם זה, שהיה גדול ממנו: \u0003לא תיתיב אכרעך\u0004 \u0005[תשב על רגליך]\u0006 \u0003עד דאמרת\u0004 \u0005[שתאמר]\u0006 \u0003לי להא שמעתתא\u0004 \u0005[את ההלכה הזו]:\u0006 \u0003מנין למנחת סוטה שטעונה תנופה?\u0004 ותוהים: מה מקום יש לשאלה \u0003מנלן\u0004 \u0005[מניין לנו]?!\u0006 והלא \u0003בגופה כתיב\u0004 \u0005[ב\u0006פרשת סוטה \u0005עצמה נאמר]:\u0006 \u0003\"והניף את המנחה\"!\u0004 (במדבר ה, כה) \u0003אלא\u0004 כך היתה השאלה: שצריך \u0003תנופה בבעלים מנלן\u0004 \u0005[מניין לנו]?\u0006 שמא הכוונה היא שהכהן בלבד מניף?","והשיב ר' יאשיה: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה \u0003\"יד\" \"יד\" משלמים. כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במנחת סוטה \u0003\"ולקח הכהן מיד האשה\"\u0004 (שם) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \"המקריב את זבח שלמיו... \u0003ידיו תביאינה...\u0004","להניף אותו תנופה\" (ויקרא ז, כט–ל), \u0003מה כאן\u0004 בסוטה \u0003כהן\u0004 מניף (\"ולקח הכהן\") — \u0003אף להלן\u0004 בשלמים \u0003כהן\u0004 מניף, \u0003מה להלן\u0004 בשלמים \u0003בעלים\u0004 מניפים (\"ידיו תביאנה\") — \u0003אף כאן\u0004 בסוטה, גם \u0003בעלים\u0004 מניפים. \u0003הא כיצד\u0004 מקיימים את שני הכתובים יחד שגם הכהן וגם הבעלים יניפו? \u0003כהן מכניס ידו תחת יד בעלים ומניף,\u0004 נמצא שגם הכהן וגם הבעלים מניפים.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה ל\u0003סוטה, נזירה מנלן\u0004 \u0005[מניין לנו]\u0006 שהיא מניפה? ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה, של המלים: \u0003\"כף\"\u0004 האמור בנזירות (\"ונתן על כפיה נזיר\". במדבר ו, ט) ו\u0003\"כף\"\u0004 האמור ב\u0003סוטה\u0004 (\"ונתן על כפיה\". שם ה, יח) וכמו שהסוטה מניפה גם נזירה מניפה.","\u0003כל מצוה שהיא תלויה בארץ\u0004 — \u0003אינה נוהגת אלא בארץ\u0004 ישראל, \u0003ושאינה תלויה בארץ\u0004 — \u0003נוהגת בין בארץ בין בחוצה לארץ,\u0004"],["\u0003חוץ מן הערלה וכלאים\u0004 שנוהגות גם בחוץ לארץ. \u0003ר' אליעזר אומר: אף החדש\u0004 האיסור לאכול מתבואה חדשה עד זמן הקרבת העומר (ששה עשר בניסן).","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מצוה \u0003תלויה\u0004 בארץ, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 מצוה \u0003שאינה תלויה\u0004 בארץ? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003תלויה\u0004 משמעה מצוה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 צירוף לשון כזה או אחר הנגזר מהשרש \"בוא\" שיש בו משמעות \u0003ביאה\u0004 לארץ ישראל, \u0003ושאינה תלויה\u0004 — ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה ביאה\u0004 — \u0003והרי\u0004 מצות הנחת \u0003תפילין ו\u0004פדיון \u0003פטר חמור, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בהן ביאה\u0004 (\"והיה כי יביאך ה' אל ארץ הכנעני וכו'\". שמות יג, יא), \u0003ונוהגין בין בארץ בין בחוץ לארץ!\u0004","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך צריך להבין\u0005]\u0006 את ההגדרה של מצוה התלויה בארץ: \u0003כל מצוה שהיא חובת הגוף\u0004 שמוטלת על גופו של אדם — \u0003נוהגת בין בארץ בין בחוץ לארץ.\u0004 ואילו מצוה שהיא \u0003חובת קרקע,\u0004 שהיא תלויה בארץ במובן זה שהיא תלויה וקשורה בקרקע ובגידוליה — \u0003אינה נוהגת אלא בארץ\u0004 ישראל.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 על הכתוב \"אלה החוקים והמשפטים אשר תשמרון לעשות בארץ אשר נתן ה' אלהי אבותיך לך לרשתה כל הימים אשר אתם חיים על האדמה\" (דברים יב, א), שכך נדרש המקרא: \u0003\"אלה החקים\"\u0004 — \u0003אלו המדרשות\u0004 שדורשים מן הכתובים, \u0003\"והמשפטים\"\u0004 — \u0003אלו הדינים,\u0004 דיני ממונות, \u0003\"אשר תשמרון\"\u0004 — \u0003זו משנה\u0004 שהם הדברים שיש לשמור אותם על מנת לעשות. \u0003\"לעשות\"\u0004 — \u0003זו מעשה\u0004 המצוות,","\u0003\"בארץ\"\u0004 — \u0003יכול כל המצות כולן לא יהו נוהגים אלא בארץ\u0004 ישראל — \u0003תלמוד לומר: \"כל הימים אשר אתם חיים על האדמה\",\u0004 משמע בכל מקום שאתם חיים. \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"כל הימים\" יכול יהו\u0004 כל המצוות \u0003נוהגים בין בארץ בין בחוצה לארץ?\u0004 — \u0003תלמוד לומר: \"בארץ\".\u0004","\u0003אחר ש\u0004גם \u0003ריבה הכתוב\u0004 מצוות בחוץ לארץ \u0003ו\u0004גם \u0003מיעט\u0004 אותן, איך אנחנו יודעים אלו מצוות נוהגות גם בחוצה לארץ ואלו אינן נוהגות? ומשיבים: \u0003צא ולמד ממה שאמור בענין\u0004 הסמוך לו: \u0003\"אבד תאבדון את כל המקמות אשר עבדו שם\u0004 הגויים אשר אתם יורשים אותם את אלהיהם\u0003\"\u0004 (שם ב), \u0003מה\u0004 מצוות איסור \u0003עבודה זרה מיוחדת\u0004 בכך \u0003שהיא חובת הגוף, ו\u0004מצאנו ש\u0003נוהגת בין בארץ בין בחוצה לארץ\u0004 — \u0003אף כל\u0004 מצוה \u0003שהיא חובת הגוף נוהגת בין בארץ בין בחוצה לארץ,\u0004 אבל דברים שאינם חובת הגוף אלא הם חובת הקרקע אינם נוהגים אלא בארץ בלבד.","על מה ששנינו שכל מצוה שהיא תלויה בארץ אינה נוהגת אלא בארץ... \u0003חוץ מן הערלה והכלאים,\u0004 אומר ר' אליעזר: אף החדש. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003ר' אליעזר לקולא פליג\u0004 \u0005[להקל חלק]\u0006 על התנא הראשון \u0003או לחומרא פליג\u0004 \u0005[להחמיר חלק]?\u0006","ומסבירים את הדברים: \u0003לחומרא פליג\u0004 \u0005[להחמיר חלק]\u0006 \u0003והכי קאמר תנא קמא\u0004 \u0005[וכך אמר התנא הראשון]:\u0006 \u0003חוץ מן הערלה ומן הכלאים דהלכתא גמירי לה\u0004 \u0005[שהלכה\u0006 למשה מסיני אנו \u0005למדים אותה]\u0006 \u0003אף על גב דאיכא למימר\u0004 \u0005[אף על פי שיש לומר]\u0006 \u0003חובת קרקע היא\u0004 ואין חיובה אלא בארץ, בכל אופן חייבים לקיימן גם בחוץ לארץ. \u0003אבל\u0004 איסור \u0003חדש\u0004 שהוא חובת הקרקע \u0003בארץ\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בחוצה לארץ\u0004 — \u0003לא.\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לחלוקה זו — שכן הביטוי \u0003\"מושב\"\u0004 (\"בכל מושבותיכם\". ויקרא כג, יד) האמור בדין \"חדש\" לא בא ללמד שחייבים בו בכל מקום בו ישראל יושבים, אלא אף היא נוהגת בארץ ישראל בלבד, ו\"מושבותיכם\" הכוונה — \u0003לאחר ירושה\u0004 (כיבוש) \u0003וישיבה\u0004 של בני ישראל בארץ ישראל \u0003משמע\u0004 ולא לפני שהתיישבו בה בשלימות.","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003אף חדש נוהג בין בארץ בין בחוצה לארץ, מאי טעמא\u0004 \u0005[מה טעם]\u0006 — שהוא מפרש \u0003\"מושב\"\u0004 — \u0003בכל מקום שאתם יושבים.\u0004 זו היא אפשרות הבנה אחת שעל פיה ר' אליעזר מחמיר ביחס לתנא הראשון.","\u0003או דלמא לקולא פליג\u0004 \u0005[שמא להקל חלק]\u0006 \u0003והכי קאמר תנא קמא\u0004 \u0005[וכך אמר התנא הראשון]:\u0006 \u0003חוץ מן הערלה והכלאים דהלכתא גמירי לה\u0004 \u0005[שהלכה\u0006 למשה מסיני אנו \u0005למדים אותה],\u0006 \u0003וכל שכן חדש\u0004 שנוהג אף בחוץ לארץ ש\u0003\"מושב\"\u0004 — \u0003כל מקום שאתם יושבים משמע.\u0004","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003חדש אינו נוהג אלא בארץ,\u0004 ש\u0003\"מושב\"\u0004 — \u0003לאחר ירושה וישיבה משמע. ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 \u0003\"אף\"\u0004 שאומר ר' אליעזר — אינו מתייחס לערלה וכלאיים שמצווים עליהם אף בחוץ לארץ אלא \u0003אקמייתא\u0004 \u0005[על\u0006 הפיסקה \u0005הראשונה]\u0006 שמצווה התלויה בארץ נוהגת בארץ בלבד ומוסיף ר' אליעזר שדין זה כולל גם את החדש.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, ממה ש\u0003אמר אביי: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[החולק עליו],\u0006 על \u0003ר' אליעזר\u0004 — \u0003ר' ישמעאל היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 לענין מצות הבאת נסכים עם קרבנות: \u0003ללמדך, שכל מקום שנאמר בו \"מושב\" אינו אלא לאחר ירושה וישיבה, דברי ר' ישמעאל.\u0004","\u0003אמר לו ר' עקיבא: הרי שבת שנאמר בו \"מושבות\"\u0004 (ויקרא כג, ג) \u0003ונוהגת בין בארץ בין בחוצה לארץ! אמר לו: שבת\u0004 על ידי \u0003קל וחומר אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]:\u0006 \u0003מה מצות קלות נוהגות בין בארץ בין בחוצה לארץ\u0004 — \u0003שבת חמירא\u0004 \u0005[\u0006שהיא \u0005חמורה]\u0006 \u0003לא כל שכן\u0004 שתנהג בכל מקום.","ומן הדברים הללו נדייק, \u0003מדאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003אביי: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[החולק עליו],\u0006 על \u0003ר' אליעזר\u0004 — \u0003ר' ישמעאל\u0004 האומר ש\"מושבות\" משמעו רק לאחר שיתיישבו לגמרי בארץ, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ר' אליעזר לחומרא פליג\u0004 \u0005[להחמיר חלק]\u0006 שהוא סבור ש\"מושבות\" משמעו בכל מקום שישראל מצויים בו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","אגב כך שואלים על עיקר דברי ר' ישמעאל: \u0003מכדי\u0004 \u0005[והרי]\u0006 \u0003ר' ישמעאל אהיכא קאי\u0004 \u0005[היכן עומד,\u0006 למה מתייחסים דבריו\u0005]\u0006 בענין זה, \u0003אנסכים\u0004 \u0005[על\u0006 חובת \u0005נסכים]\u0006 ומשם למד לכל מצוה שהוזכרו בה \"מושבות\" שנוהגת דווקא בארץ ישראל אך לאחר ירושה וישיבה, והלא \u0003בנסכים\u0004"],["\u0003ביאה ומושב\u0004 יחד \u0003כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (\"כי תבואו אל ארץ מושבותיכם\". במדבר טו, ב), וכיצד הוא למד מכאן לענין שנאמר בו \"מושבות\" בלבד? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ללמד שכל מקום שנאמר\u0004 בו גם \u0003ביאה ו\u0004גם \u0003מושב\u0004 — \u0003אינו אלא לאחר ירושה וישיבה,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, על מה ש\u0003אמר לו ר' עקיבא: הרי שבת שנאמר בו \"מושבות\",\u0004 והשיב ר' ישמעאל \u0003ואמר לו: שבת קל וחומר היא\u0004 נלמדת, \u0003נימא ליה\u0004 \u0005[שיאמר לו\u0006 במקום זה\u0005]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003ביאה ומושב\u0004 יחד \u0003קאמינא\u0004 \u0005[אומר אני]\u0006 ובשבת נאמר רק \"מושב\"! ומשיבים: \u0003חדא ועוד קאמר ליה\u0004 \u0005[\u0006תשובה \u0005אחת ועוד\u0006 אחת \u0005אמר לו];\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ביאה ומושב\u0004 יחד \u0003קאמינא\u0004 \u0005[אומר אני].\u0006 \u0003ועוד\u0004 תשובה על קושיה זו: \u0003דקא אמרת\u0004 \u0005[\u0006זה \u0005שאתה אומר]\u0006 \u0003הרי שבת שנאמר בו \"מושבות\"\u0004 — \u0003שבת קל וחומר היא.\u0004","ולעצם מחלוקת ר' ישמעאל ור' עקיבא שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה נושא, \u0005נחלקו\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003ב\u0004שאלה אם \u0003קירבו\u0004 (הקריבו) \u0003נסכים במדבר קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 \u0003ר' ישמעאל סבר: לא קירבו נסכים במדבר\u0004 ולא נתחייבו בהם אלא לאחר שנתיישבו בארץ, לאחר ביאה ומושב. \u0003ור' עקיבא סבר\u0004 \u0003: קירבו נסכים במדבר,\u0004 ולומד מ\"מושב\" דין אחר.","\u0003אמר אביי: האי תנא דבי\u0004 \u0005[תנא זה מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 שלדבריו רק במצוה שנזכרו בה \"ביאה\" ו\"מושב\" יחד נצטוו ישראל לאחר ירושה וישיבה \u0003מפיק\u0004 \u0005[מוציא,\u0006 חולק\u0005]\u0006 \u0003מאידך תנא דבי\u0004 \u0005[מ\u0006דברי \u0005תנא אחר של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל.\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל ונאמרו ביאות\u0004 לארץ בכמה מצוות \u0003בתורה סתם, ופרט לך הכתוב באחד מהן\u0004 שמדובר \u0003לאחר ירושה וישיבה,\u0004 שנאמר במצוות מינוי המלך \"כי תבוא אל הארץ... וירשתה וישבתה בה\" (דברים יז, יד) — \u0003אף כל\u0004 מקום שנאמרה ביאה לארץ בסתם כוונתה \u0003לאחר ירושה וישיבה\u0004 ואין צורך גם ב\"מושב\".","\u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר],\u0006 (הראשון) משמו של ר' ישמעאל אומר שאין זו ראיה \u0003משום דהוה\u0004 \u0005[שהיה]\u0006 כתוב זה במצוות מינוי מלך \u0003ו\u0004הכתוב במצות \u0003ביכורים\u0004 (שאף במצוות ביכורים נאמרה ביאה ירושה וישיבה) \u0003שני כתובים הבאים כאחד, וכל שני כתובים הבאים כאחד אין מלמדין.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 השני\u0005]\u0006 בשם ר' ישמעאל משיב: שני כתובים אלה \u0003צריכי\u0004 \u0005[צריכים]\u0006 שייאמרו במפורש ואינם למדים זה מזה; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 דבר זה רק לגבי \u0003מלך ולא כתב\u0004 \u0005[היתה כותבת]\u0006 כך לגבי \u0003ביכורים הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דבר זה הוא דווקא במצות מינוי מלך אבל במצות \u0003ביכורים\u0004 שהוא מביא על מה \u0003דקא מיתהני\u0004 \u0005[שנהנה]\u0006 מאכילת הפירות, צריך להביא \u0003לאלתר\u0004 \u0005[מיד]\u0006 ולא ימתין עד לירושה וישיבה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כתב\u0004 רק לגבי \u0003ביכורים ולא כתב\u0004 לגבי \u0003מלך הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מלך\u0004 ש\u0003דרכו לכבש\u0004 — צריך למנותו \u0003לאלתר\u0004 \u0005[מיד]\u0006 עוד לפני כניסתם לארץ.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 (הראשון) בשם ר' ישמעאל טוען כנגד זה: \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003מלך ולא בעי\u0004 \u0005[יצטרך]\u0006 לכתוב דבר זה לגבי \u0003ביכורים, ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 מן הסברה: \u0003ומה מלך ש\u0004תפקידו \u0003לכבש\u0004 את הארץ, בכל זאת מצוה למנותו רק \u0003לאחר ירושה וישיבה, ביכורים\u0004 — \u0003לא כל שכן.\u0004 ואם כן שני כתובים הבאים כאחד הם, ואינם מלמדים.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 השני\u0005]\u0006 בשם ר' ישמעאל אומר: \u0003אי כתב הכי\u0004 \u0005[אם היה כותב כך]\u0006 רק בענין מלך \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 מן הסברה להיפך: שיתחייבו בביכורים מיד בכניסה לארץ \u0003מידי דהוה אחלה\u0004 \u0005[כשם שהדבר הוא ל\u0006ענין הפרשת \u0005חלה]\u0006 שמצוותה מיד עם הכניסה לארץ, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן.","ושואלים: \u0003והשתא דאמרת\u0004 \u0005[ועכשיו שאתה אומר]\u0006 ש\u0003חובת הגוף נוהגת בין בארץ ישראל בין בחוצה לארץ, \"מושב\" דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 \u0003גבי שבת\u0004 \"שבת היא לה' בכל מושבותיכם\" (ויקרא כג, ג) שהיא חובת הגוף, \u0003למה לי?\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר; \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובענינא\u0004 \u0005[ובענין]\u0006 בפרשת\u0005]\u0006 ה\u0003מועדות כתיבא\u0004 \u0005[נאמרה]\u0006 מצות השבת, \u0003תיבעי\u0004 \u0005[תצטרך]\u0006 \u0003קידוש\u0004 על ידי בית דין דווקא \u0003כי\u0004 \u0005[כמו]\u0006 \u0003מועדות,\u0004 שמקדשים את ראש החודש כדי לדעת מתי יחולו המועדות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","ועוד שואלים: \"\u0003מושב\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003גבי חלב ודם\u0004 (\"חוקת עולם לדורותיכם בכל מושבותיכם כל חלב וכל דם לא תאכלו\". ויקרא ג, יז), \u0003למה לי?\u0004 והרי חובת הגוף הם! ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובענינא\u0004 \u0005[ובענין,\u0006 בפרשתם\u0005]\u0006 של \u0003קרבנות כתיבי\u0004 \u0005[נאמרו]\u0006 איסורים אלה, לכן \u0003בזמן דאיכא\u0004 \u0005[שיש]\u0006 \u0003קרבן\u0004 ומעלים למזבח את חלבו ודמו, דהיינו בזמן שבית המקדש קיים \u0003ניתסר\u0004 \u0005[ייאסרו]\u0006 \u0003חלב ודם,\u0004 ואילו \u0003בזמן דליכא\u0004 \u0005[שאין]\u0006 \u0003קרבן\u0004 — \u0003לא\u0004 ייאסרו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם אסורים לעולם.","ועוד שואלים: \u0003\"מושב\" דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 \u0003גבי מצה ומרור\u0004 (\"בכל מושבותיכם תאכלו מצות\". שמות יב, כ), \u0003למה לי?\u0004 והרי חובת הגוף הם! ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"על מצות ומררים יאכלהו\"\u0004 (את הפסח) (במדבר ט, יא), \u0003בזמן דאיכא\u0004 \u0005[שיש]\u0006 קרבן \u0003פסח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בזמן דליכא\u0004 \u0005[שאין]\u0006 קרבן \u0003פסח\u0004 — \u0003לא\u0004 יתחייבו אף באלה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהיא חובה לעולם.","ושואלים עוד: \u0003ביאה דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 \u0003גבי תפילין ופטר חמור\u0004 (בתחילת הפרשה העוסקת בהם. שמות יג, יא) \u0003למה לי?\u0004 והלא חובת הגוף הן ואינן תלויות בארץ! ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 \u0003לכדתנא דבי\u0004 \u0005[לכמו ששנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: עשה מצוה זו\u0004 של תפילין, \u0003שבשבילה\u0004 תזכה ו\u0003תיכנס לארץ.\u0004","ועוד שואלים לענין איסור \"חדש\" שנזכר בו \"מושב\": \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שדורש \u0003\"מושב\"\u0004 — \u0003כל מקום שאתם יושבים משמע,\u0004 וממילא אין הוא דורש \"מושב\" — לומר שנתחייבו רק לאחר ירושה וישיבה — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 על בני ישראל מיד לאחר שנכנסו לארץ \u0003\"ויאכלו מעבור\u0004 (תבואת) \u0003הארץ ממחרת הפסח\"\u0004 (יהושע ה, יא), ונדייק: \u0003ממחרת הפסח אכול\u0004 \u0005[אכלו]\u0006 מתבואת ארץ ישראל, \u0003מעיקרא\u0004 \u0005[מתחילה,\u0006 קודם לכן\u0005]\u0006 — \u0003לא אכול\u0004 \u0005[אכלו].\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006"]]};
